	["%s ganados"] = "%s 획득",
	["%s huele distinto a todo lo demás. Me gusta olfatearlo."] = "%s에서는 다른 곳과 다른 냄새가 나요. 킁킁 맡는 게 좋아요.",
	["%s le queda a su clase y su nivel (%d). ¿Se lo regalas?"] = "%s, 직업과 레벨(%d)에 맞아요. 선물할래요?",
