	["%s no entra: %s."] = "%s 제외: %s.",
	["%s no está a tu lado: mándaselo por correo. Al abrir un buzón, su nombre ya estará puesto."] = "%s 님이 옆에 없어요. 우편으로 보내세요. 우체통을 열면 이름이 이미 들어가 있어요.",
	["%s no puede ir a tu cita"] = "%s 님은 약속에 못 와요",
	["%s no se puede invitar desde Alfa: el juego solo lo deja desde su ventana. Ábrela aquí y pega el nombre."] = "Alfa에서는 %s에 초대할 수 없습니다. 게임이 자체 창에서만 허용합니다. 여기서 창을 열고 이름을 붙여 넣으세요.",
	["%s no se puede tomar"] = "%s 받을 수 없음",
