	["%s pidió entrar a tu guarida: lo invitaste a tu grupo. Saldrá solo al llegar."] = "%s님이 굴에 들어오고 싶어 해서 파티에 초대했어요. 도착하면 알아서 나가요.",
	["%s por hora"] = "시간당 %s",
	["%s prefiere seguir por su cuenta por ahora."] = "%s 님은 당분간 혼자 가고 싶어 해요.",
