	["%s pudo volver ya"] = "%s, 다시 나왔을 수도",
	["%s puede vender lo gris y reparar, igual que Alfa. Si lo tienes encendido allá, los dos lo harían a la vez."] = "%s도 Alfa처럼 회색 아이템을 팔고 수리할 수 있어요. 거기서 켜져 있으면 둘이 동시에 해요.",
	["%s quedó completa. Elige qué sigue y la manada va contigo."] = "%s 완료. 다음 할 일을 고르면 무리가 함께합니다.",
	["%s quiere ser tu mentor"] = "%s 님이 내 멘토가 되고 싶어 해요",
	["%s resultados"] = "결과 %s개",
	["%s se borra de todos tus personajes. No se puede deshacer."] = "모든 캐릭터에서 %s 경로를 삭제합니다. 되돌릴 수 없습니다.",
	["%s se compartirá con tu grupo al salir de la instancia."] = "인스턴스에서 나가면 %s 마커를 파티와 공유합니다.",
	["%s también arregla el buzón: dos «Tomar todo» se estorban."] = "%s도 우편함을 개선해요. '모두 받기' 버튼 두 개가 서로 방해해요.",
	["%s también cambia tus bolsas y el banco: las dos ventanas se pisan al abrirlas."] = "%s도 가방과 은행을 바꿔요. 열면 두 창이 서로 방해해요.",
	["%s también es una guía: las dos aceptarían y entregarían tus misiones a la vez."] = "%s도 가이드예요. 둘이 동시에 퀘스트를 수락하고 완료해요.",
	["%s también hace “%s”. ¿Cazan juntos?"] = "%s님도 «%s» 퀘스트를 하고 있어요. 같이 사냥할래요?",
	["%s también marca tus misiones en el mapa. Conviven bien; si ves marcas dobles, apaga las de uno de los dos."] = "%s도 지도에 퀘스트를 표시해요. 함께 써도 괜찮아요. 표시가 겹쳐 보이면 하나를 끄세요.",
	["%s también pone precios en el cuadro de los objetos: verías dos."] = "%s도 아이템 툴팁에 가격을 표시해요. 두 개가 보일 거예요.",
	["%s te abre la puerta"] = "%s님이 문을 열어 줘요",
	["%s te abre su guarida"] = "%s 님이 굴을 열어 줘요",
	["%s te encargó «%s». Hay toda una historia detrás… ¿Te la cuento?"] = "%s: «%s»을(를) 맡겼어요. 그 뒤에 긴 이야기가 있어요… 들려줄까요?",
	["%s te habló de %s, y hay más historia de la que dice la flecha. ¿Te la cuento?"] = "%s: %s에 대해 말해 줬죠. 화살표가 알려 주는 것보다 이야기가 더 있어요. 들려줄까요?",
	["%s tiene hambre. Una buena comida y vuelve a pelear contento."] = "%s, 배고파요. 맛있게 먹으면 다시 즐겁게 싸울 거예요.",
	["%s tiene sus razones para pedirte «%s». ¿Te las cuento?"] = "%s: «%s»을(를) 부탁한 데는 이유가 있어요. 들려줄까요?",
