	["*bosteza* Cazar contigo es lo mejor de mi día."] = "*하품* 함께 사냥하는 게 하루 중 제일 좋아요.",
	["*la devora en un segundo* ¡Gracias! Ahora sí, a cazar."] = "*1초 만에 꿀꺽* 고마워요! 이제 진짜 사냥하러 가요.",
	["*levanta la manita* ¿Salchicha? Prometo cuidarte el doble."] = "*앞발을 들며* 소시지요? 두 배로 잘 지켜 줄게요, 약속해요.",
	["*mueve la cola despacito* Todo bien por aquí."] = "*천천히 꼬리를 흔든다* 여긴 다 괜찮아요.",
	["*mueve la cola* Aquí sigo, atenta."] = "*꼬리를 흔든다* 여기서 지켜보고 있어요.",
	["*mueve la cola* Huelo una salchicha en tu mochila. ¿Me la das?"] = "*꼬리를 흔들며* 가방에서 소시지 냄새가 나요. 저 주면 안 돼요?",
	["*olfatea el aire* Huele a aventura."] = "*공기 냄새를 맡는다* 모험의 냄새가 나요.",
	["*olfatea el suelo* Por aquí pasó un jabalí... hace rato."] = "*땅 냄새를 맡는다* 여기로 멧돼지가 지나갔어요... 좀 전에요.",
	["*persigue su cola un ratito* …¡Casi la atrapo!"] = "*잠깐 자기 꼬리를 쫓는다* …거의 잡았는데!",
	["*se echa un ratito* No estoy dormida, estoy vigilando con los ojos cerrados."] = "*잠깐 엎드린다* 자는 거 아니에요. 눈 감고 망보는 중이에요.",
	["*se estira y bosteza* Listo, ¡a seguir!"] = "*기지개를 켜고 하품한다* 좋아요, 계속 가요!",
	["*se rasca la oreja* Listo, ya me quedé tranquila."] = "*귀를 긁는다* 됐다, 이제 개운해요.",
	["*se sienta y te mira con ojitos tiernos* ¿Me das una salchicha? Solo una… bueno, una."] = "*앉아서 초롱초롱한 눈으로 바라보며* 소시지 하나 줄래요? 딱 하나만… 음, 하나요.",
