	["1 misión"] = "퀘스트 1개",
	["1 misión entregada"] = "완료한 퀘스트 1개",
	["1 misión para recoger"] = "받을 퀘스트 1개",
	["1 misión para tu bando."] = "내 진영 퀘스트 1개.",
	["1 misión que aún no haces."] = "아직 하지 않은 퀘스트 1개.",
	["1 muerte"] = "1번 죽음",
	["1 más sin XP conocida: no cuenta."] = "경험치를 모르는 1개 더: 계산하지 않음.",
	["1 nivel"] = "1레벨",
	["1 objeto"] = "물품 1개",
	["1 objeto más es de un jefe que aún no descubres."] = "아이템 1개는 아직 발견하지 못한 우두머리가 떨어뜨립니다.",
	["1 para después"] = "나중에 1개",
	["1 para recoger"] = "받을 것 1개",
	["1 para recoger ahora"] = "지금 받을 것 1개",
	["1 punto libre"] = "남은 포인트 1개",
	["1 resultado"] = "결과 1개",
	["1 tótem puesto"] = "토템 1개",
	["1. Llega al nivel 40. La montura y la equitación se compran a la vez: junta el oro mientras subes."] = "1. 40레벨에 도달하세요. 탈것과 타기 숙련은 함께 삽니다. 레벨을 올리는 동안 골드를 모으세요.",
	["2 h"] = "2시간",
	["2. Ve con el instructor de equitación de tu raza y aprende la de aprendiz."] = "2. 내 종족의 탈것 조련사에게 가서 수습 타기를 배우세요.",
	["3 de XP, 3 de oro, 3 de XP, 20 de tu profesión y 3 de clase para un objeto único."] = "경험치 퀘스트 3개, 골드 퀘스트 3개, 경험치 퀘스트 3개, 내 전문 기술 재료 20개, 고유 아이템을 주는 직업 퀘스트 3개.",
	["3. Compra la montura con el vendedor de tu raza (al lado del instructor) y úsala para aprenderla."] = "3. 내 종족의 상인(조련사 옆)에게서 탈것을 사고, 사용해서 배우세요.",
	["30 min"] = "30분",
	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. 60레벨이 되면 같은 조련사가 숙련 타기를 가르치고, 상인은 빠른 탈것을 팝니다.",
	["A %s"] = "거리 %s",
	["A %s le queda poco"] = "%s 곧 사라짐",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "언더시티는 로데론 수도의 폐허에서 승강기를 타고 내려가요.",
	["A Mis planes"] = "내 계획으로",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "라그나로스는 너무 일찍 깨우는 걸 싫어해서, 청지기 이그젝큐투스가 톡톡히 대가를 치러요.",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "실리더스는 운고로 분화구에서 들어가요.",
	["A cualquier lugar: vuelos, barcos, zepelines, portales y a pie."] = "어디든: 비행, 배, 비행선, 차원문, 도보.",
	["A distancia"] = "원거리",
	["A entregar tus misiones"] = "퀘스트 제출하러",
	["A estas horas hasta los murlocs duermen. No te desveles mucho, que mañana también se caza."] = "이 시간엔 멀록도 자요. 너무 늦게까지 있지 마세요. 내일도 사냥이 있어요.",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "스톰윈드 입구에서는 2차 대전쟁의 위대한 영웅들의 석상이 방문객을 맞이해요.",
	["A la vista: %d de la manada · %d de tu grupo"] = "보이는 인원: 무리 %d명 · 파티 %d명",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "나머지는 무엇이 부족한지 알려 줍니다. 레벨이나 먼저 할 퀘스트.",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "모델 양옆에 부위마다 버튼이 있습니다. 한 번 클릭하면 그 부위를 숨기고, 다시 클릭하면 다시 입힙니다.",
	["A mi lista de compras"] = "내 장보기 목록에",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "전투 중반에 서리 망령이 나타납니다. 빨리 처치하거나 광역 공격을 쓰세요.",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "전투 중반에 보호막을 두르고 큰 폭발을 준비합니다. 빛나기 시작하면 멀리 떨어지세요!",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "10레벨에 첫 야수를 길들이는 퀘스트를 해요.",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "20레벨에 늑대 정령을 배워요. 저처럼 늑대가 되는 거예요! 자, 달리기 시합해요.",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "60레벨에는 빠른 탈것: 숙련 타기와 에픽 탈것.",
	["A probar"] = "테스트",
	["A quién ir"] = "찾아갈 곳",
	["A su entrenador"] = "전문가에게",
	["A tu gusto"] = "내 취향대로",
	["A tu lado"] = "곁에서",
	["A tu medida"] = "내 방식대로",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "내 레벨에서는 적이 빨리 쓰러집니다. 연계 점수 3점으로 마무리하세요.",
	["A tu nivel te conviene %s: lo vende el posadero o un vendedor de comida."] = "내 레벨에는 %s을(를) 챙기세요. 여관주인과 음식 상인이 팔아요.",
	["A tu nivel: %s"] = "내 레벨에는: %s",
	["A un clic"] = "바로 가기",
	["A veces"] = "가끔",
	["A veces el golpe ni te toca."] = "공격이 아예 빗나가기도 합니다.",
	["A veces el juego tarda o no deja mover a nadie más a esa capa. Puedes salir del grupo y probar con otra."] = "가끔 게임이 늦거나 그 레이어로 더는 옮겨 주지 않아요. 파티를 나가서 다른 곳을 시도해 보세요.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "가끔 퀘스트를 시작하는 상자나 편지가 든 병을 낚기도 해요.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "채광하다 보석이 나올 때가 있어요. 여러 전문 기술이 제작법에 쓰니까 간직하세요.",
	["Abajo"] = "아래",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "모델 아래에서 캐릭터의 동작(걷기, 춤추기, 손 흔들기...)을 고르고 일시 정지할 수 있습니다.",
	["Abajo y al centro del ícono, con letra que crece con él. Apagada, chiquita en la esquina."] = "아이콘 아래 가운데, 아이콘과 함께 커지는 글자로. 끄면 모서리에 작게.",
	["Abalorio"] = "장신구",
	["Abalorios"] = "장신구",
	["Abandonar"] = "포기",
	["Abandonar marcadas (%d)"] = "표시한 것 포기 (%d)",
	["Abandonaste %d misiones"] = "퀘스트 %d개를 포기했습니다",
	["Abierta"] = "열림",
	["Abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo (fuera de combate)."] = "열림: 무리 중 누가 들어오고 싶어 하면 Alfa가 파티에 초대해요(전투 중 제외).",
	["Abiertas"] = "열린 가이드",
	["Abrazo vampírico: tu daño de sombras te cura."] = "흡혈의 선물: 암흑 피해를 주면 생명력이 회복됩니다.",
	["Abre Heridas profundas."] = "깊은 상처를 엽니다.",
	["Abre Hoy: ahí te digo lo más útil para este momento en grande, y tu camino a un par de clics."] = "오늘을 열어요. 지금 가장 쓸모 있는 걸 크게 보여 주고 길도 몇 번 클릭이면 돼요.",
	["Abre Paisaje y gráficos"] = "풍경과 그래픽 열기",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "채집 창을 엽니다. «ruta»를 붙이면 현재 지역에 파밍 경로를 만들고 따라갑니다.",
	["Abre desde el sigilo para empezar con ventaja."] = "은신 상태에서 시작해 유리하게 싸움을 엽니다.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "같은 지역으로 게임 지도를 엽니다. 전투 중에는 Alfa에서 게임 지도를 열 수 없습니다.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "지도를 열고 원하는 곳을 오른쪽 클릭(또는 Shift+클릭)하세요. 이름, 아이콘, 색을 정하면 언제든 화살표가 안내합니다. 게임 지도에서는 Shift+오른쪽 클릭입니다.",
	["Abre el mapa: cada muelle dice cuánto falta para que llegue su barco o zepelín."] = "지도를 여세요. 부두마다 배나 비행선 도착까지 남은 시간이 나와요.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "낚시 모드를 열고(여기서, /alfa pesca로, 또는 낚싯대를 장착하면) %s 키를 누르세요. 그 키 하나로 장비를 입고, 미끼를 달고, 던지고, 찌가 튀면 낚아 올립니다.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "낚시 모드를 열고 키를 고르세요. 장비를 입고, 미끼를 달고, 던지고, 찌가 튀면 낚아 올립니다.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "낚시 모드를 열고 키를 누르세요. 낚은 것이 여기에 나타납니다.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "게임의 요리 창을 열고(버튼이 열어 줍니다) 다시 누르세요.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "백과사전을 열고 아이템 정보에서 «내 경로에 추가»를 누르세요.",
	["Abre la casa de subastas para escanear."] = "스캔하려면 경매장을 여세요.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "경매장을 열고 «Alfa로 스캔»을 누르면 내 아이템의 가치를 알 수 있습니다.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "이 아이템을 얻는 곳으로 안내하는 Alfa 가이드를 엽니다.",
	["Abre la pelea a distancia antes de que llegue."] = "적이 다가오기 전에 원거리에서 전투를 여세요.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "전투를 엽니다. 적에게 다가가고 분노를 얻습니다.",
	["Abre la siguiente fila."] = "다음 줄을 엽니다.",
	["Abre la ventana Historias."] = "이야기 창을 엽니다.",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "Blizzard의 클릭 시전 창을 열어 같은 클릭을 설정하고 그 파티 프레임에서도 똑같이 치유할 수 있게 해요 (게임이 애드온의 복사를 허용하지 않아요).",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "게임의 특성 창을 한 번 열거나 몇 초 기다리세요. Alfa가 읽는 즉시 무엇을 찍을지 알려 줍니다. 그동안 아래에서 내 빌드를 볼 수 있습니다.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "전문 기술 창을 한 번 열면 Alfa가 제조법을 읽고 어떤 것이 이득인지 알려 줍니다.",
	["Abre la ventana principal de Alfa."] = "Alfa 메인 창을 엽니다.",
	["Abre o cierra el mapa de Alfa"] = "Alfa 지도 열기/닫기",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "항상 돌진으로 시작하고, 전투 시작 때 분쇄를 거세요.",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "항상 은신 상태에서 가장 강한 공격으로 시작하세요.",
	["Abre su ficha en Mazmorras y toca «Guíame»: la flecha te lleva hasta la puerta, aunque esté escondida en una cueva."] = "던전에서 해당 정보를 열고 「안내해 줘」를 누르세요. 동굴에 숨어 있어도 화살표가 문까지 데려가요.",
	["Abre su ficha."] = "정보를 엽니다.",
	["Abre tus bolsas con su tecla o con el botón de la mochila."] = "가방 키나 배낭 버튼으로 가방을 열어 주세요.",
	["Abre tus bolsas con tu tecla (%s)."] = "가방 키(%s)로 가방을 열어 주세요.",
	["Abre un buzón para tomar tus cartas."] = "우편을 받으려면 우편함을 여세요.",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "메시지가 준비된 귓속말을 엽니다. 상대가 접속 중이 아니면 게임이 알려 줍니다.",
	["Abrir"] = "열기",
	["Abrir Hermandad y comunidades"] = "길드 및 커뮤니티 열기",
	["Abrir Historias"] = "이야기 열기",
	["Abrir Hoy"] = "오늘 열기",
	["Abrir Mazmorras"] = "던전 열기",
	["Abrir Misiones"] = "퀘스트 열기",
	["Abrir Paisaje y gráficos"] = "풍경과 그래픽 열기",
	["Abrir bolsas"] = "가방 열기",
	["Abrir clic para lanzar"] = "클릭 시전 열기",
	["Abrir el Legado del juego"] = "게임의 유산 열기",
	["Abrir el diario"] = "도감 열기",
	["Abrir el mapa"] = "지도 열기",
	["Abrir el mapa de Alfa"] = "Alfa 지도 열기",
	["Abrir el mapa de Alfa con la tecla del mapa"] = "지도 키로 Alfa 지도 열기",
	["Abrir el mapa de vuelo"] = "비행 지도 열기",
	["Abrir el modo al ponerte una caña"] = "낚싯대를 장착하면 모드 열기",
	["Abrir el modo pesca"] = "낚시 모드 열기",
	["Abrir la Enciclopedia"] = "백과사전 열기",
	["Abrir la cocina"] = "요리 열기",
	["Abrir la configuración"] = "설정 열기",
	["Abrir la enciclopedia"] = "백과사전 열기",
	["Abrir la guía"] = "가이드 열기",
	["Abrir la ventana"] = "창 열기",
	["Abrir la ventana de Alfa"] = "Alfa 창 열기",
	["Abrir la ventana de talentos"] = "특성 창 열기",
	["Abrir la ventana del juego"] = "게임 창 열기",
	["Abrir las comodidades (minimapa, cuadro de información, probador...)"] = "편의 기능 열기 (미니맵, 툴팁, 미리보기 창...)",
	["Abrir mi guarida"] = "내 굴 열기",
	["Abrir mis bolsas"] = "내 가방 열기",
	["Abrir o cerrar el mapa de Alfa"] = "Alfa 지도 열기/닫기",
	["Abrir o cerrar el modo pesca"] = "낚시 모드 열기/닫기",
	["Abrir otra guía"] = "다른 가이드 열기",
	["Abrir otra guía..."] = "다른 가이드 열기...",
	["Abrir su ficha en la Enciclopedia"] = "백과사전에서 정보 열기",
	["Abrir su guía"] = "가이드 열기",
	["Abrumar casi siempre crítico."] = "제압이 거의 항상 치명타로 들어갑니다.",
	["Abrumar crítico contra pícaros que esquivan."] = "회피하는 도적에게 제압이 치명타로 들어갑니다.",
	["Abrumar hace crítico casi siempre."] = "제압이 거의 매번 치명타로 들어갑니다.",
	["Abrumar hace crítico mucho más seguido."] = "제압이 훨씬 자주 치명타로 들어갑니다.",
	["Acaba de abrirle la puerta a alguien. Prueba en un momento."] = "방금 누군가에게 문을 열어 줬어요. 잠시 후 다시 해 보세요.",
	["Acabas de vencer a un enemigo: este ataque es gratis y te cura."] = "방금 적을 처치했습니다. 이 공격은 비용이 없고 생명력을 회복시킵니다.",
	["Accesos rápidos"] = "바로 가기",
	["Acecho"] = "숨기",
	["Acento propio (elegido en Ajustes)"] = "내 강조 색(설정에서 선택)",
	["Acento: %s"] = "강조 색: %s",
	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "친구와 길드원의 파티 초대를 수락합니다.",
	["Acepta por ti"] = "대신 수락",
	["Acepta su invitación al grupo. Al llegar a su guarida, Alfa te avisa para salir del grupo."] = "파티 초대를 수락하세요. 그 굴에 도착하면 Alfa가 파티를 나가라고 알려 줘요.",
	["Acepta una invocación al momento, salvo en combate."] = "전투 중이 아니면 소환을 바로 수락합니다.",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "가능해지는 즉시 부활을 수락합니다. 하드코어에서는 절대 하지 않습니다.",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "나머지(일반, 일일, 주간)를 수락하고 제출합니다. 회색 퀘스트나 골드·재료를 요구하는 퀘스트는 절대 하지 않습니다.",
	["Acepta y entrega tus misiones, elige tu guía y sigue sola, vende, repara y toma tus vuelos. Tú solo juegas."] = "퀘스트를 수락하고 반납하며, 가이드를 골라 계속 가고, 팔고, 수리하고, 비행도 타요. 당신은 즐기기만 해요.",
	["Aceptar"] = "확인",
	["Aceptar invocaciones"] = "소환 수락",
	["Aceptar las misiones de tu guía"] = "가이드 퀘스트 수락",
	["Aceptar resurrecciones"] = "부활 수락",
	["Aceptar solas las misiones de la guía"] = "가이드 퀘스트 자동 수락",
	["Aceptar todas las misiones ya no pierde una diaria porque la ventana se cerraba antes de tiempo."] = "모든 퀘스트 수락이 창이 너무 일찍 닫혀서 일일 퀘스트를 놓치는 일이 없어졌습니다.",
	["Aceptar y entregar"] = "수락과 제출",
	["Aceptar y entregar misiones"] = "퀘스트 수락과 완료",
	["Aceptar y entregar solo las misiones de mi ruta"] = "내 경로의 퀘스트만 수락하고 제출",
	["Aceptar y entregar todas las misiones"] = "모든 퀘스트 수락 및 제출",
	["Acercar"] = "확대",
	["Acomoda tus marcos"] = "프레임 배치",
	["Acomodar"] = "정리",
	["Actitud de batalla"] = "전투 태세",
	["Actitud defensiva"] = "방어 태세",
	["Actitud rabiosa"] = "광폭 태세",
	["Activa el rastreo de hierbas para verlas en el minimapa mientras viajas."] = "약초 찾기를 켜면 이동하면서 미니맵에서 약초를 볼 수 있어요.",
	["Activa el rastreo de minerales y sigue las montañas: ahí están las mejores vetas."] = "광석 찾기를 켜고 산을 따라가세요. 거기에 가장 좋은 광맥이 있어요.",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "벽에 있는 기계를 켜서 걸어 다니는 폭탄을 풀어 놓습니다. 기계 옆 버튼을 눌러 끄거나, 폭탄이 도착하기 전에 처치하세요.",
	["Activar el medidor de daño"] = "피해 측정기 활성화",
	["Activar el modo limpio"] = "깔끔 모드 켜기",
	["Activar módulo"] = "모듈 켜기",
	["Activar módulos"] = "모듈 켜기",
	["Activo"] = "사용 중",
	["Actual"] = "현재",
	["Actualizar mi guía"] = "내 가이드 갱신",
	["Actualizar mis barras"] = "내 단축바 업데이트",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "CurseForge 앱이나 최신 zip으로 업데이트한 다음 /reload를 입력하세요.",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "CurseForge 앱이나 최신 zip으로 업데이트한 다음 게임을 다시 시작하거나 /reload를 입력하세요.",
	["Acércate para usar %s"] = "%s 사용하려면 더 가까이 가세요",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "아이콘과 함께 바 주위에 깜빡이는 금색 빛.",
	["Adopta a un lobo 10 niveles menor que tú. Si acepta, ves su nivel, su zona y su misión (solo tú) y te aviso si se atora."] = "나보다 10레벨 낮은 늑대를 맡아 보세요. 수락하면 그 늑대의 레벨, 지역, 퀘스트를 나만 보고, 막히면 알려 줄게요.",
	["Adopta a un lobo nuevo o deja que uno con más nivel te adopte. Lo que comparten queda entre los dos."] = "새 늑대를 맡거나 레벨 높은 늑대가 나를 맡게 하세요. 공유하는 건 둘만 알아요.",
	["Adoptar"] = "맡기",
	["Afinar cosa por cosa"] = "하나씩 세부 조정",
	["Afinar siempre"] = "항상 선명하게",
	["Aflicción"] = "고통",
	["Aflicción para subir"] = "레벨업용 고통",
	["Agarras a varios enemigos a la vez."] = "여러 적을 한꺼번에 붙잡아 둡니다.",
	["Agilidad"] = "민첩성",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "첫 목표를 추가하세요: 아이템, 골드, 전문 기술, 장소, 퀘스트, 레벨, 메모.",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "위에서 구간을 추가하세요. Alfa가 퀘스트를 골라 줍니다.",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "그 유닛의 대상을 한 줄 추가합니다. 대상이 나라면 그렇게 알려 줍니다.",
	["Agregada"] = "추가됨",
	["Agregada a Cerrar mis misiones"] = "내 퀘스트 끝내기에 추가됨",
	["Agregado a tu plan"] = "계획에 추가됨",
	["Agregado a tu ruta"] = "경로에 추가됨",
	["Agregar a Cerrar mis misiones"] = "내 퀘스트 끝내기에 추가",
	["Agregar a Mis planes"] = "내 계획에 추가",
	["Agregar a mi lista"] = "내 목록에 추가",
	["Agregar a mi ruta"] = "내 경로에 추가",
	["Agregar lo que me falta"] = "부족한 것 추가",
	["Agregar todo a mi lista"] = "모두 내 목록에 추가",
	["Agregar un tramo:"] = "구간 추가:",
	["Agregar una meta"] = "목표 추가",
	["Agregué %s ×%d a tu lista."] = "목록에 %s ×%d을(를) 추가했어요.",
	["Agregué lo que falta para %s"] = "먼저 필요한 것을 추가했습니다: %s",
	["Agregué lo que te falta para subir %s. Lo ves en Comercio."] = "%s 올리는 데 부족한 걸 추가했어요. 거래에서 볼 수 있어요.",
	["Agrégale una en Mis planes."] = "내 계획에서 하나 추가하세요.",
	["Agrégale uno en la página Ruta."] = "경로 페이지에서 추가하세요.",
	["Agua"] = "물",
	["Agua de manantial refrescante"] = "상쾌한 샘물",
	["Agua y comida"] = "물과 음식",
	["Agua: llevas %d (mejor %d o más). A tu nivel: %s"] = "물: %d개 있어요(%d개 이상이 좋아요). 내 레벨에는: %s",
	["Aguante"] = "체력",
	["Aguas conocidas"] = "아는 물",
	["Ahora"] = "지금",
	["Ahora corre más que la manada. ¡Auuu!"] = "이제 무리보다 빨라요. 아우우!",
	["Ahora estás en la %s. Ya puedes salir del grupo: el plano se queda contigo."] = "이제 %s에 있어요. 파티를 떠나도 레이어는 그대로예요.",
	["Ahora ganas la XP normal"] = "이제 일반 경험치를 얻습니다",
	["Ahora mismo te ayudaría con"] = "지금 이걸 도와줄 수 있어요",
	["Ahora no"] = "나중에",
	["Ahora no pude armar el camino a esta misión."] = "지금은 이 퀘스트로 가는 길을 만들지 못했어요.",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "지금은 보내지 않습니다. Alfa가 무리와 연결할 방법을 찾고 있습니다.",
	["Ahora no se puede"] = "지금은 할 수 없음",
	["Ahora no se puede anunciar"] = "지금은 알릴 수 없음",
	["Ahora no se puede avisar a la manada. Inténtalo en un momento."] = "지금은 무리에게 알릴 수 없어요. 잠시 뒤에 다시 해 보세요.",
	["Ahora no se puede hablar con la manada. Prueba en un rato."] = "지금은 무리에게 닿지 않아요. 잠시 뒤에 다시 해 보세요.",
	["Ahora no se puede llamar a la manada: Alfa busca cómo unirse a ella."] = "지금은 무리를 부를 수 없어요. Alfa가 무리에 합류할 방법을 찾고 있어요.",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "지금은 메시지를 보낼 수 없습니다(인스턴스 안이거나 체험판 계정). %s",
	["Ahora toca la colección: completa tu diario, los logros y prueba el concurso de los domingos."] = "이제 수집할 차례예요. 도감과 업적을 채우고 일요일 낚시 대회에 도전해 보세요.",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "지금 사용 중: %s. %s 가중치를 켜면 Alfa가 내 빌드에 맞게 장비를 비교합니다.",
	["Ahora va por el canal oculto de Alfa."] = "이제 Alfa의 숨은 채널로 보냅니다.",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "이제 길드로 보냅니다. Alfa의 숨은 채널을 쓸 수 없어 길드에서 공유하는 사람만 나를 봅니다.",
	["Ahora vas a: %s"] = "지금 가는 곳: %s",
	["Ahora · %s"] = "지금 · %s",
	["Ahora: %d %% del nivel %d"] = "현재: %d %% (%d레벨)",
	["Ahora: %s"] = "지금: %s",
	["Ahora: %s · De fábrica: %s"] = "현재: %s · 기본값: %s",
	["Ahora: %s."] = "현재: %s.",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "그곳에는 지역이 없습니다. 땅 위에 마커를 놓으세요.",
	["Ahí no se puede poner la flecha."] = "그곳에는 화살표를 놓을 수 없습니다.",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "그곳에서 모든 것을 함께 정합니다. 링크를 클릭하고 Ctrl+C로 복사하세요.",
	["Ajustar"] = "조정",
	["Ajustar los avisos"] = "경고 조정",
	["Ajustes"] = "설정",
	["Ajustes de Alfa en todos los idiomas: las fechas en el orden de cada uno y los nombres de cada especialización bien puestos."] = "모든 언어의 Alfa 조정: 언어마다 맞는 날짜 순서와 각 전문화의 올바른 이름.",
	["Ajustes de Bolsas"] = "가방 설정",
	["Ajustes de Lya"] = "Lya 설정",
	["Ajustes de mazmorras"] = "던전 설정",
	["Ajustes de pesca"] = "낚시 설정",
	["Ajustes del mapa"] = "지도 설정",
	["Ajustes del medidor"] = "측정기 설정",
	["Ajustes en orden: Comodidades y Calidad de vida son una sola página con pestañas, y todo lo de misiones vive en Ajustes > Misiones. Tu configuración se mudó sola, sin perder nada."] = "설정 정리: 편의 기능과 삶의 질이 탭이 있는 한 페이지가 되었고, 퀘스트 관련 설정은 모두 설정 > 퀘스트에 있습니다. 설정은 그대로 옮겨져 아무것도 사라지지 않았습니다.",
	["Ajustes importados"] = "설정을 가져왔어요",
	["Al abrir el buzón, un aviso si una carta con objetos vence en menos de 3 días."] = "우편함을 열 때, 물품이 든 우편이 3일 안에 만료되면 알려 줘요.",
	["Al abrirse el mapa de vuelo, vuela al destino que marca tu ruta."] = "비행 지도가 열리면 경로에 표시된 목적지로 날아갑니다.",
	["Al acercar o cargar el mapa, cada parte aparece completa de una vez, sin cuadritos sueltos."] = "지도를 확대하거나 불러올 때 각 부분이 작은 칸 없이 한 번에 온전히 나타납니다.",
	["Al acercar se ven las montañas y el relieve, igual que en el minimapa. Apagado: el mapa pintado del juego."] = "확대하면 미니맵처럼 산과 지형이 보입니다. 끄면: 게임의 그림 지도.",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "경로를 만들 때 Alfa는 정예가 필요한 퀘스트를 뺍니다.",
	["Al banco (%d)"] = "은행으로 (%d)",
	["Al cambiar de forma o de actitud, el juego usa otra barra de abajo. Si está vacía, Alfa te avisa una vez y puede llenar sus casillas vacías con las habilidades de esa forma que ya sabes, fuera de combate y sin tocar lo que ya tienes."] = "변신하거나 태세를 바꾸면 게임은 아래쪽의 다른 단축바를 씁니다. 그 단축바가 비어 있으면 Alfa가 한 번 알려 주고, 전투 중이 아닐 때 이미 있는 것은 건드리지 않고 빈 칸을 그 형태에서 이미 배운 기술로 채울 수 있습니다.",
	["Al cambiar de forma, el juego cambia tu barra de abajo por la de esa forma, y esta todavía no tiene nada: por eso parece que desaparece. Alfa puede poner en sus casillas vacías las habilidades de esa forma que ya sabes."] = "변신하면 게임이 아래쪽 단축바를 그 형태의 단축바로 바꾸는데, 이 단축바에는 아직 아무것도 없습니다. 그래서 단축바가 사라진 것처럼 보입니다. Alfa가 그 형태에서 이미 배운 기술을 빈 칸에 넣어 줄 수 있습니다.",
	["Al comerciante"] = "상인에게",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "아이템을 비교할 때 Alfa는 %s에 필요한 것, 즉 능력치 목록 위쪽을 더 높게 칩니다.",
	["Al completar una misión vuelve a salir en el chat: «[Misión] está lista para entregar» y, al entregarla, «¡Misión completada!». En grupo lo ve todo el grupo; solo, tú."] = "퀘스트를 완료하면 다시 채팅에 나와요: 「[퀘스트] 반납 가능」, 반납하면 「퀘스트 완료!」. 파티에서는 파티 모두가, 혼자일 때는 나만 봐요.",
	["Al completar una misión vuelve a salir en tu chat: «[Misión] está lista para entregar» y «¡Misión completada!». Si lo prendes, también tu grupo lo ve."] = "퀘스트를 완료하면 다시 내 채팅에 나와요: 「[퀘스트] 반납 가능」과 「퀘스트 완료!」. 켜면 파티도 볼 수 있어요.",
	["Al curar con un clic, ese compañero queda seleccionado para tus otros poderes."] = "클릭으로 치유하면 그 동료가 다른 기술을 위해 대상으로 남아요.",
	["Al día"] = "최신 상태",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "빌드를 고르면 가방의 향상 화살표가 그 빌드에 필요한 것을 기준으로 평가합니다.",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "시작할 때 제단에서 자신을 깨운 사람을 기절시킵니다. 정상입니다.",
	["Al enemigo le queda poca vida: Quemadura de las Sombras lo remata."] = "적의 생명력이 얼마 남지 않았습니다. 어둠의 연소로 마무리합니다.",
	["Al enemigo le queda poca vida: remátalo al instante."] = "적의 생명력이 얼마 남지 않았습니다. 즉시 마무리하세요.",
	["Al enemigo le queda poca vida: remátalo."] = "적의 생명력이 얼마 남지 않았습니다. 마무리하세요.",
	["Al entrar a una mazmorra, Lya te da un consejo corto y un botón para verla. Nunca en combate."] = "던전에 들어가면 리아가 짧은 조언과 그걸 볼 수 있는 버튼을 줘요. 전투 중에는 절대 안 해요.",
	["Al entrar a una zona con enemigos muy arriba de tu nivel, un aviso corto (una vez por zona)."] = "레벨보다 훨씬 높은 적이 있는 지역에 들어가면 짧게 알려 줘요(지역마다 한 번).",
	["Al entrar al juego, Lya te dice quién de tu hermandad anda conectado y dónde."] = "게임에 들어오면 리아가 길드에서 누가 접속해 있고 어디 있는지 알려 줘요.",
	["Al entrar o al juntarse tu grupo reviso tu equipo, tus bolsas, tu comida y lo de tu clase. Si falta algo te digo qué y te llevo a conseguirlo. También con /alfa listo."] = "들어가거나 파티가 다 차면 장비, 가방, 음식, 직업 재료를 점검해요. 부족하면 무엇인지 알려 주고 사러 데려가요. /alfa listo로도 돼요.",
	["Al entrar o al juntarse tu grupo: equipo, bolsas, comida, agua, munición y lo de tu clase. Nunca en combate."] = "들어갈 때나 파티가 다 찼을 때: 장비, 가방, 음식, 물, 탄약, 직업 재료. 전투 중에는 안 해요.",
	["Al entregar una misión, Lya te ofrece contarte cómo terminó."] = "퀘스트를 제출하면 Lya가 어떻게 끝났는지 들려주겠다고 합니다.",
	["Al final de la Tercera Guerra, Arthas subió al Trono Helado, se puso el yelmo y se volvió uno con el Rey Exánime."] = "3차 대전쟁이 끝날 무렵 아서스는 얼어붙은 왕좌에 올라 투구를 쓰고 리치 왕과 하나가 되었어요.",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "전투 막바지에 격노해서 더 빨리 때립니다. 그때를 위해 치유를 아껴 두세요.",
	["Al final se enfurece: guarden su mejor daño para el final."] = "마지막에 격노합니다. 가장 강한 공격은 마지막을 위해 아껴 두세요.",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "마지막에 나랄렉스의 신봉자에게 말을 걸고, 걸어가는 동안 지켜 주세요. 그러면 마지막 우두머리가 나타납니다.",
	["Al hablar con el maestro de vuelo, abre su mapa directamente."] = "비행 조련사와 대화하면 바로 지도를 엽니다.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola."] = "경로의 퀘스트를 주는 NPC와 대화하면 자동으로 수락됩니다.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "경로의 퀘스트를 주는 NPC와 대화하면 자동으로 수락합니다. Shift를 누르면 직접 고릅니다.",
	["Al hablar con un PNJ"] = "NPC와 대화할 때",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "은행원과 대화하면 빠른 보관 기능이 있는 Alfa 은행이 열립니다. 캐릭터마다 처음 방문할 때는 게임 은행이 나오며, 그래야 첫 탭을 받습니다.",
	["Al hurtar a los humanoides ganas monedas y a veces cajas cerradas."] = "인간형 몹을 소매치기하면 돈과 가끔 잠긴 상자를 얻어요.",
	["Al invitar a una comunidad ya no sale el aviso de bloqueo: Alfa te deja el nombre listo para copiar y te abre la ventana. A tu hermandad, un clic como antes."] = "커뮤니티에 초대할 때 더 이상 차단 경고가 뜨지 않습니다. Alfa가 복사할 이름을 준비하고 창을 열어 줍니다. 길드는 예전처럼 클릭 한 번.",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "마을이나 여관에 도착했을 때 알립니다. 가이드 창이 숨겨져 있으면 가이드의 수련 안내도 다시 알려 줍니다.",
	["Al llegar a una zona con una mazmorra para tu nivel, Lya te dice quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "내 레벨에 맞는 던전이 있는 지역에 오면, 리아가 근처에 있는 같은 레벨대 무리를 '초대' 버튼과 함께 알려 줘요.",
	["Al llegar a una zona con una mazmorra para tu nivel, te digo quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "내 레벨에 맞는 던전이 있는 지역에 오면, 근처에 있는 같은 레벨대 무리를 '초대' 버튼과 함께 알려 줄게요.",
	["Al llegar en barco o al encontrar un raro, un anuncio grande con animación, como la intro."] = "배로 도착하거나 희귀 몹을 찾으면 인트로처럼 큰 애니메이션 알림이 나와요.",
	["Al llegar en barco o cuando Lya encuentra un raro, un anuncio grande con animación, como la intro, en vez de una tarjeta."] = "배로 도착하거나 리아가 희귀 몹을 찾으면, 카드 대신 인트로처럼 큰 애니메이션 알림이 떠요.",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "죽으면 공허방랑자 네 마리가 함께 안뜰을 걸어옵니다. 여러 마리와 싸울 준비를 하세요.",
	["Al morir en un campo de batalla, liberas tu espíritu al momento."] = "전장에서 죽으면 바로 영혼을 해방합니다.",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "죽으면 수련생이 많이 몰려옵니다. 한꺼번에 많은 적을 상대할 준비를 하세요.",
	["Al moverte, la tecla vuelve a la normal"] = "움직이는 동안은 키가 원래대로",
	["Al moverte, solo de lado"] = "움직일 때는 옆으로만",
	["Al norte de estas montañas están las Estepas Ardientes y la Montaña Roca Negra, de donde salen los orcos que amenazan Villa del Lago."] = "이 산맥 북쪽에는 불타는 평원과 검은바위 산이 있어요. 레이크샤이어를 위협하는 오크들이 거기서 와요.",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "대상의 생명력이 얼마 남지 않았습니다. 마무리 일격이 분노를 써서 끝냅니다.",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "대상의 생명력이 얼마 남지 않았습니다. 망치로 멀리서 마무리합니다.",
	["Al pasar el ratón por un objeto: «Tienes 12 (Lobato: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "아이템에 마우스를 올리면 모든 캐릭터를 합쳐 «12개 보유 (Lobato: 가방 7개, Alt: 은행 5개)»처럼 보여 줍니다.",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "아이템에 마우스를 올리면 경매장 가격, 상인 판매가, 가장 좋은 선택을 보여 줍니다.",
	["Al pie de Cima del Trueno está el poblado Pezuña de Sangre, donde Baine, el hijo de Cairne, cuida a su gente."] = "썬더 블러프 아래에는 블러드후프 마을이 있어요. 케언의 아들 베인이 그곳 사람들을 돌봐요.",
	["Al poner algo a la venta en la subasta: su precio sugerido, su historial de 14 días y un aviso si lo das muy barato."] = "경매장에 물건을 올릴 때: 추천 가격, 14일 기록, 너무 싸게 팔면 경고.",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "피해를 입으면 작은 조각이 떨어져 나옵니다. 광역 공격으로 처치하세요.",
	["Al sacar algo"] = "무언가 낚았을 때",
	["Al salir de una mazmorra"] = "던전에서 나올 때",
	["Al seguir, Alfa se recarga para cambiar el idioma y esta configuración sigue donde la dejaste."] = "계속하면 언어를 바꾸기 위해 Alfa를 다시 불러오고, 이 설정은 멈춘 곳에서 이어집니다.",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "레벨이 오르면(접속했을 때 남은 포인트가 있을 때도) 어떤 특성을 찍을지 알림과 적용 버튼이 나옵니다.",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "레벨이 오르면 배울 것과 비용을 보여 줍니다.",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "레벨이 오르면 무엇을 배울지, 비용과 상급자를 알림으로 알려 주고 길 안내 버튼도 나옵니다.",
	["Al sur de Cuna del Invierno, una garganta escondida está llena de demonios."] = "여명의 설원 남쪽, 숨겨진 협곡에는 악마가 가득해요.",
	["Al sur de Los Baldíos, el Gran Elevador baja hasta Las Mil Agujas. ¡No mires hacia abajo!"] = "불모의 땅 남쪽에서 거대한 승강기가 버섯구름 봉우리로 내려가요. 아래를 보지 마세요!",
	["Al sur está Dalaran, la ciudad de los magos. Archimonde la arrasó en la Tercera Guerra, y sus magos la reconstruyen protegidos bajo una cúpula."] = "남쪽에는 마법사의 도시 달라란이 있어요. 3차 대전쟁 때 아키몬드가 파괴했고, 마법사들이 보호막 아래에서 다시 짓고 있어요.",
	["Al sur se alza una muralla enorme: el rey Genn Cringris la levantó para aislar Gilneas del resto del mundo."] = "남쪽에는 거대한 장벽이 솟아 있어요. 겐 그레이메인 왕이 길니어스를 세상과 단절하려고 세웠어요.",
	["Al terminar una guía de nivel, carga la siguiente sin preguntar."] = "레벨업 가이드가 끝나면 묻지 않고 다음 가이드를 불러옵니다.",
	["Al terminar una guía, la que sigue para tu nivel a un clic."] = "가이드를 끝내면 내 레벨에 맞는 다음 가이드가 클릭 한 번 거리에.",
	["Al terminar una pelea, Alfa te deja una tarjeta pequeña con cuánto duró, tu daño y tu curación por segundo y lo que más te pegó. Usa el medidor oficial del juego y solo cuenta lo tuyo."] = "전투가 끝나면 Alfa가 작은 카드를 남겨요. 얼마나 걸렸는지, 초당 피해와 치유, 가장 아팠던 공격. 게임 공식 측정기를 쓰고 내 것만 세요.",
	["Al terminar una pelea, aquí queda su resumen: tu daño, tu curación y lo que más te pegó."] = "전투가 끝나면 여기에 요약이 남아요. 내 피해, 내 치유, 가장 아팠던 공격.",
	["Al terminar: cuánto duró, tu daño y tu curación por segundo y lo que más te pegó."] = "끝나면: 걸린 시간, 초당 피해와 치유, 가장 아팠던 공격.",
	["Al terminarla, te propongo la siguiente para tu nivel. Un clic en «Seguir con…» y seguimos de caza."] = "끝내면 내 레벨에 맞는 다음 걸 추천해요. '…로 계속'을 한 번 누르면 계속 사냥해요.",
	["Al tomar una misión te la resumo en dos líneas, a mi modo: qué hay que hacer y un consejito. La historia completa sigue en «Historias»."] = "퀘스트를 받으면 제 방식으로 두 줄로 요약해 줘요. 할 일과 작은 조언이요. 전체 이야기는 '이야기'에 그대로 있어요.",
	["Al tomar una misión, Lya te la resume en dos líneas: qué hay que hacer y un consejito suyo."] = "퀘스트를 받으면 리아가 두 줄로 요약해 줘요. 할 일과 리아의 작은 조언.",
	["Al volver con una misión lista, se entrega sola. Si hay recompensas para elegir, eliges tú."] = "완료한 퀘스트를 가지고 돌아오면 자동으로 제출됩니다. 고를 보상이 있으면 직접 고릅니다.",
	["Alamuerte forjó en secreto el Alma de Demonio, un disco dorado cargado con el poder de los demás Aspectos, que se lo dieron sin saber para qué lo quería."] = "데스윙은 몰래 악마의 영혼을 만들었어요. 다른 위상들의 힘이 담긴 황금 원반인데, 그들은 무엇에 쓸지도 모르고 힘을 내주었어요.",
	["Alamuerte se hizo pasar por Lord Daval Prestor, un noble que casi llegó a rey de Alterac. ¡A esa familia le encantan los disfraces!"] = "데스윙은 알터랙의 왕이 될 뻔한 귀족 다발 프레스터 경으로 위장했어요. 그 가족은 변장을 정말 좋아해요!",
	["Alcance de las sombras"] = "그림자 거리",
	["Alcanza para %d"] = "%d번 분량",
	["Alejar"] = "축소",
	["Alejar la cámara"] = "카메라 최대 거리",
	["Alejar más la cámara"] = "카메라 더 멀리 빼기",
	["Alertas"] = "경고",
	["Alexandros Mograine empuñaba la Crematoria, y la Plaga le temía como a nadie. Lo traicionó su propio hijo, Renault."] = "알렉산드로스 모그레인은 파멸의 인도자를 휘둘렀고, 스컬지는 누구보다 그를 두려워했어요. 그를 배신한 건 친아들 르노였어요.",
	["Alfa"] = "Alfa",
	["Alfa %s ya está aquí"] = "Alfa %s 버전이 나왔습니다",
	["Alfa %s · cliente %s (%s) · %s · Alfa en %s"] = "Alfa %s · 클라이언트 %s (%s) · %s · Alfa 언어: %s",
	["Alfa (el de siempre), Clásico WoW (marcos y letras del juego), Cristal (transparente), La Jauría nocturno (azul de noche y plata de luna) o Fogata (carbón y brasas). El modo compacto y tus colores funcionan en todos."] = "Alfa(늘 쓰던 것), WoW 클래식(게임의 틀과 글꼴), 유리(투명), La Jauría 밤(밤의 파랑과 달빛 은색), 모닥불(숯과 불씨). 간단 모드와 내 색은 모두에서 돼요.",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa(고유 스타일, 기본값), WoW 클래식(게임의 프레임과 글꼴), 유리(투명, 내가 고른 강조 색). 간소 모드와 내 색은 세 가지 모두에서 작동합니다.",
	["Alfa arma el reporte y tú lo pegas en el buzón privado del Discord de La Jauría. También con /alfa reportar."] = "Alfa가 보고서를 만들면 La Jauría Discord의 비공개 우편함에 붙여 넣으세요. /alfa reportar로도 됩니다.",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa가 NPC별로 묶어 제출하는 가장 짧은 경로를 만듭니다. 화살표는 유리할 때 비행과 귀환석을 쓰고, 제출할 곳이 멀면 알려 줍니다.",
	["Alfa atrapó errores"] = "Alfa가 오류를 잡았어요",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco y su equipo. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa가 저장한 %s의 가방, 은행, 장비 정보를 삭제합니다. 그 캐릭터로 다시 플레이하면 새로 저장됩니다.",
	["Alfa completo"] = "전체 Alfa",
	["Alfa de La Jauría"] = "La Jauría의 알파",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa가 근처에서 경험치를 가장 많이 주는 퀘스트를 세 묶음으로 고릅니다.",
	["Alfa elige por ti: entregar las que tienes listas, cerrar las de esta zona o recoger misiones nuevas."] = "Alfa가 대신 골라 줘요: 완료한 퀘스트 제출, 이 지역 퀘스트 마무리, 또는 새 퀘스트 받기.",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "Alfa가 모두 고릅니다: 거리 대비 경험치 순 퀘스트와 내 직업 퀘스트.",
	["Alfa es la %s, pero estas son de otra: %s. Reinstala Alfa completo para que todo sea de la misma."] = "Alfa는 %s인데, 이것들은 다른 버전이에요: %s. 모두 맞도록 Alfa 전체를 다시 설치하세요.",
	["Alfa es un addon que toxic3000 creó para sus amigos y quiso compartir con todos."] = "Alfa는 toxic3000이 친구들을 위해 만들고 모두와 나누고 싶었던 애드온입니다.",
	["Alfa estable: en orden y en manada"] = "안정판 Alfa: 정돈된 설정, 함께하는 무리",
	["Alfa está armando tu ruta..."] = "Alfa가 경로를 만드는 중...",
	["Alfa está eligiendo..."] = "Alfa가 고르는 중...",
	["Alfa está leyendo tu clase"] = "Alfa가 내 직업을 읽는 중",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa가 숨겨져 있습니다. 클릭하면 표시하고 창을 엽니다",
	["Alfa guarda una copia de tus ajustes y perfiles cada semana y antes de cada actualización. Quedan las últimas 3."] = "Alfa는 매주, 그리고 업데이트 전마다 설정과 프로필을 복사해 둬요. 최근 3개를 보관해요.",
	["Alfa guarda unos %.1f MB. Es mucho: el juego tarda más en entrar. Lo que más pesa: %s."] = "Alfa가 약 %.1fMB를 저장해요. 많아요. 접속이 오래 걸려요. 가장 무거운 부분: %s.",
	["Alfa guarda unos %.1f MB. Todo bien."] = "Alfa가 약 %.1fMB를 저장해요. 괜찮아요.",
	["Alfa junta tus misiones y las de aquí y busca el camino más corto."] = "Alfa가 내 퀘스트와 이 근처 퀘스트를 모아 가장 짧은 길을 찾아요.",
	["Alfa la vuelve a poner al entrar."] = "접속할 때 Alfa가 다시 적용합니다.",
	["Alfa las ordena por el camino más corto y te lleva de una en una."] = "Alfa가 가장 짧은 길 순서로 정리해 하나씩 안내해요.",
	["Alfa le agregó lo que ayuda a arreglarlo: versiones, idioma, tu clase y nivel y dónde estás. No lleva tu nombre ni tu reino."] = "Alfa가 해결에 도움이 되는 정보를 덧붙였습니다: 버전, 언어, 직업과 레벨, 현재 위치. 이름과 서버는 들어가지 않습니다.",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa는 게임의 공식 측정기를 읽습니다. 켜면 여기에 파티의 피해량이 표시되며, 측정기 창은 편집 모드에서 숨길 수 있습니다.",
	["Alfa lo creó toxic3000 para sus amigos y quiso compartirlo con todos. No juega por ti: te ayuda a entender y disfrutar el juego a tu ritmo."] = "toxic3000이 친구들을 위해 Alfa를 만들고 모두와 나누고 싶어 했어요. 대신 플레이하지 않아요. 당신의 속도로 게임을 이해하고 즐기도록 도와요.",
	["Alfa lo hace por ti"] = "Alfa가 대신 해요",
	["Alfa lo hace toxic3000 para La Jauría. Es software libre (GPL-3.0) y su código está en github.com/toxic3000/alfa-forever."] = "Alfa는 toxic3000이 La Jauría를 위해 만듭니다. 자유 소프트웨어(GPL-3.0)이며 코드는 github.com/toxic3000/alfa-forever에 있습니다.",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa가 위치를 옮기지 않고 새 레벨로 바꿉니다.",
	["Alfa mantiene %d ajustes que elegiste. Abre la ventana para ver o cambiar cada uno."] = "Alfa가 고른 설정 %d개를 유지합니다. 창을 열어 각각 보거나 바꾸세요.",
	["Alfa mantiene %d ajustes tuyos y los vuelve a poner al entrar."] = "Alfa가 내 설정 %d개를 유지하고 접속할 때 다시 적용합니다.",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa가 이동 방법(비행, 귀환석)을 계산합니다. 몇 초 걸립니다.",
	["Alfa nació en La Jauría, la comunidad de Toxic (toxic3000) en WoW Forever: un solo addon con todo lo que la manada necesita para jugar, con un solo estilo."] = "Alfa는 WoW Forever의 Toxic(toxic3000) 커뮤니티 La Jauría에서 태어났어요. 무리가 플레이하는 데 필요한 모든 걸 하나의 스타일로 담은 단 하나의 애드온이에요.",
	["Alfa no está afiliado a esos proyectos ni ellos lo respaldan; gracias a todos por compartir su trabajo."] = "Alfa는 그 프로젝트들과 제휴하거나 보증받지 않았습니다. 작업을 나눠 준 모두에게 감사드립니다.",
	["Alfa no ha cambiado nada todavía. Prueba «Paisaje de la manada» o abre la ventana para ver los ajustes que el menú del juego no enseña."] = "Alfa는 아직 아무것도 바꾸지 않았습니다. «무리의 풍경»을 써 보거나, 창을 열어 게임 메뉴에 없는 설정을 보세요.",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa가 %s까지 가는 길을 만들지 못했습니다. 백과사전에서 확인하세요.",
	["Alfa no sabe dónde estás (en una instancia no hay notas)."] = "Alfa가 위치를 몰라요(인스턴스 안에서는 메모가 없어요).",
	["Alfa no sabe en qué zona estás."] = "Alfa가 지금 지역을 모르겠어요.",
	["Alfa no tiene datos de esto todavía."] = "Alfa에 아직 이에 대한 데이터가 없습니다.",
	["Alfa no tiene el instructor de tu raza: busca «equitación» en PNJ."] = "Alfa가 내 종족의 조련사를 모릅니다. NPC에서 «타기»를 검색하세요.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa는 경로에 필요 없는 퀘스트를 받지 않고 자동으로 제출하지도 않습니다. 편의 기능의 «모든 퀘스트»도 이를 따릅니다.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones»."] = "Alfa는 경로에 필요 없는 퀘스트를 받지 않고 혼자 완료하지도 않습니다. «모든 퀘스트»도 이 설정을 따릅니다.",
	["Alfa no toma misiones que no sirven a tu ruta. Tu registro queda limpio."] = "Alfa는 경로에 필요 없는 퀘스트는 받지 않습니다. 퀘스트 목록이 깔끔하게 유지됩니다.",
	["Alfa nunca apaga otros addons: eso lo decides tú en tu lista de addons."] = "Alfa는 다른 애드온을 절대 끄지 않아요. 애드온 목록에서 직접 정하세요.",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa가 덜 걷도록 경유지 순서를 정합니다. 몇 초 걸리며 게임이 멈추지 않습니다.",
	["Alfa recuerda cuándo cayó cada raro: su cuadro dice hace cuánto lo cazaron y si pudo volver ya."] = "Alfa는 희귀 몹이 언제 쓰러졌는지 기억해요: 툴팁에 언제 잡혔는지, 다시 나왔을 수 있는지 나와요.",
	["Alfa recuerda lo que llevabas antes de ponerte lo de pesca y te lo vuelve a poner."] = "Alfa는 낚시 장비를 입기 전에 입고 있던 것을 기억했다가 다시 입혀 줍니다.",
	["Alfa revisa lo que elegiste cuando el juego termina de cargar. Si los cambias en el menú del juego, se queda con lo nuevo."] = "Alfa는 게임 로딩이 끝나면 고른 값을 확인합니다. 게임 메뉴에서 바꾸면 새 값을 유지합니다.",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa가 게임을 멈추지 않고 아이템 데이터베이스를 살펴봅니다. 처음에는 몇 초 걸립니다.",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa가 아이템 데이터베이스에서 내 레벨 근처에 내 직업이 쓸 수 있는 것을 골라, 내 빌드의 가중치로 지금 착용한 장비와 비교합니다.",
	["Alfa se encarga de lo repetitivo (aceptar, entregar, vender, reparar) y te pregunta en los cruces del camino."] = "Alfa가 반복 작업(수락, 반납, 판매, 수리)을 맡고 갈림길마다 물어봐요.",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa가 La Jauría의 숨은 채널에 들어가는 중입니다. 몇 초 뒤 공유하는 사람이 보입니다.",
	["Alfa se muestra en el idioma que elijas, aunque tu juego esté en otro."] = "게임 언어가 달라도 Alfa는 선택한 언어로 표시됩니다.",
	["Alfa se recarga para cambiar el idioma. La configuración sigue donde la dejaste."] = "언어를 바꾸기 위해 Alfa를 다시 불러옵니다. 설정은 멈춘 곳에서 이어집니다.",
	["Alfa sencillo"] = "간단한 Alfa",
	["Alfa solo leyó tus valores: nada cambia hasta que toques un control."] = "Alfa는 값을 읽기만 했습니다. 조절 항목을 건드리기 전까지는 아무것도 바뀌지 않습니다.",
	["Alfa solo te sugiere: el precio lo pones tú."] = "Alfa는 추천만 해요. 가격은 직접 정해요.",
	["Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus recargas, los efectos que el juego activa y la vida del enemigo cuando se puede leer. Con varios enemigos cambia a las de área. Tú decides qué presionar."] = "Alfa는 %s 우선순위로 추천하며 내 캐릭터만 읽습니다: 자원, 재사용 대기시간, 게임이 활성화하는 효과, 그리고 읽을 수 있을 때 적의 생명력. 적이 여럿이면 광역 기술로 바꿉니다. 무엇을 누를지는 직접 정합니다.",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "Alfa에도 아직 지금 배운 기술에 맞는 내 직업 우선순위가 없습니다. 반응 알림과 측정기는 작동합니다.",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "중요한 것을 Alfa가 여기서 알려 줍니다: 수리할 장비, 가득 찬 가방, 새 기술, 내 강화 효과, 휴식 상태.",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa가 닳은 장비, 가득 찬 가방, 배울 수 있는 것, 버프, 휴식을 알려 줍니다. 무엇을 언제 알릴지 여기에서 고르세요.",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff, tu descanso, tu comida y lo que te falta para una mazmorra. Aquí eliges cuáles y cuándo."] = "Alfa는 낡은 장비, 가득 찬 가방, 배울 수 있는 기술, 강화 효과, 휴식, 음식, 던전에 부족한 것을 알려 줘요. 여기서 무엇을, 언제 알릴지 골라요.",
	["Alfa te guía con la flecha y te avisa, pero tú aceptas, entregas, eliges y viajas. Lo mínimo: vender lo gris y reparar."] = "Alfa가 화살표로 안내하고 알려 주지만 수락, 반납, 선택, 이동은 당신이 해요. 최소한: 회색 판매와 수리.",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa가 화살표와 지도의 경로로 한 단계씩 안내합니다. 내 지역과 레벨에 맞는 가이드를 고르세요.",
	["Alfa te recomienda: %s"] = "Alfa 추천: %s",
	["Alfa tiene muchas páginas, ¿se puede más sencillo?"] = "Alfa는 페이지가 많은데, 더 간단하게 할 수 있나요?",
	["Alfa todavía no tiene builds para tu clase"] = "Alfa에 아직 내 직업용 빌드가 없음",
	["Alfa usa %.1f MB de memoria ahora. Lo que más usa:"] = "Alfa가 지금 메모리를 %.1f MB 쓰고 있어요. 가장 많이 쓰는 곳:",
	["Alfa usa código y datos de estos proyectos libres, con sus avisos de autor y sus licencias incluidos en cada carpeta:"] = "Alfa는 다음 자유 프로젝트의 코드와 데이터를 사용하며, 각 폴더에 저작권 고지와 라이선스가 들어 있습니다:",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa가 지금 위치에서 다시 고릅니다(고정한 퀘스트는 남습니다).",
	["Alfa ya no se pone encima de %s. %s sigue como estaba."] = "이제 Alfa가 %s을(를) 방해하지 않아요. %s은(는) 그대로예요.",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · 상위 %d: %s (%s%s)",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa, WoW 클래식, 유리 스타일, 늑대 화살표와 울음소리.",
	["Alfa: agregar a Cerrar mis misiones"] = "Alfa: 내 퀘스트 끝내기에 추가",
	["Alfa: capas del mapa"] = "Alfa: 지도 레이어",
	["Alfa: cerrar mis misiones"] = "Alfa: 내 퀘스트 끝내기",
	["Alfa: quitar de Cerrar mis misiones"] = "Alfa: 내 퀘스트 끝내기에서 제거",
	["Alfa: ver la cadena completa"] = "Alfa: 연계 퀘스트 전체 보기",
	["Alfa_Codex está apagado en la lista de addons."] = "애드온 목록에서 Alfa_Codex가 꺼져 있습니다.",
	["Algo de Alfa no funciona, ¿qué reviso?"] = "Alfa에서 뭔가 안 되면 무엇을 확인하나요?",
	["Algo importante pasa aquí; no te lo pierdas."] = "여기서 중요한 일이 일어나요. 놓치지 마세요.",
	["Algo no anda bien en el árbol: los furbolgs que viven en él se están volviendo agresivos."] = "나무에 뭔가 이상한 일이 있어요. 거기 사는 퍼볼그들이 난폭해지고 있어요.",
	["Algunas cosas se ven completas al recargar."] = "어떤 것은 다시 불러오면 완전히 보여요.",
	["Algunas fórmulas de encantamiento muy buscadas caen de enemigos en las Tierras de la Peste."] = "인기 많은 마법부여 제조법 몇 개는 역병지대의 적에게서 떨어져요.",
	["Algunas recetas raras se compran a vendedores lejanos o caen de enemigos; vale la pena buscarlas."] = "희귀한 제조법은 먼 곳의 상인이 팔거나 적에게서 떨어져요. 찾아볼 가치가 있어요.",
	["Algunos ajustes, como el HDR, se ven hasta reiniciar los gráficos. Te pide confirmación."] = "HDR 같은 일부 설정은 그래픽을 다시 시작해야 보입니다. 확인을 요청합니다.",
	["Algunos ogros tienen dos cabezas, y no siempre se ponen de acuerdo entre ellas."] = "어떤 오우거는 머리가 둘인데, 둘이 늘 의견이 맞지는 않아요.",
	["Algunos orcos nunca siguieron a Thrall: los Roca Negra de la montaña sirven a los dragones negros."] = "모든 오크가 스랄을 따른 건 아니에요. 산의 검은바위 오크는 검은용을 섬겨요.",
	["Alianza"] = "얼라이언스",
	["Alimenta a tu mascota: si está contenta pega más y te es más leal."] = "야수에게 먹이를 주세요. 기분이 좋으면 더 세게 때리고 충성심도 커져요.",
	["Alquimia"] = "연금술",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "아이템을 Alt+클릭하면 정보가 열림",
	["Alta"] = "높음",
	["Altas"] = "높음",
	["Alto"] = "높이",
	["Alto [calidad]"] = "높음",
	["Alto de las barras"] = "바 높이",
	["Altos"] = "높음",
	["Ambiente mientras pescas"] = "낚시 중 분위기",
	["Amenaza"] = "위협",
	["Anasterian, el rey de los altos elfos, dejó la Alianza tras la Segunda Guerra, y murió frente a Arthas defendiendo la Fuente del Sol."] = "하이 엘프의 왕 아나스테리안은 2차 대전쟁 뒤 얼라이언스를 떠났고, 태양샘을 지키다 아서스에게 쓰러졌어요.",
	["Ancho"] = "너비",
	["Andan conectados: %s."] = "지금 접속 중: %s.",
	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "안돌할은 로데론의 곡창이었어요. 켈투자드가 그곳에서 역병 든 곡식을 나눠 주었고, 역병이 왕국 전체로 퍼졌어요.",
	["Anduin Lothar, el León de Azeroth, llevó a los refugiados de Ventormenta hasta Lordaeron y fue el primer comandante de la Alianza."] = "아제로스의 사자 안두인 로타는 스톰윈드 피난민을 로데론으로 이끌었고, 얼라이언스의 첫 사령관이 되었어요.",
	["Anillos"] = "반지",
	["Animación anterior"] = "이전 동작",
	["Animación siguiente"] = "다음 동작",
	["Anisotrópico 16x"] = "비등방성 16x",
	["Anisotrópico 2x"] = "비등방성 2x",
	["Anisotrópico 4x"] = "비등방성 4x",
	["Anisotrópico 8x"] = "비등방성 8x",
	["Ankh"] = "십자가",
	["Anterior"] = "이전",
	["Antes de %s te falta:"] = "%s 전에 아직 필요한 것:",
	["Antes de abandonarla"] = "포기하기 전에",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "공격하기 전에 주변을 살펴봐요. 한 번에 하나씩 싸우는 게 더 안전해요.",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "검을 찾으러 가기 전에 아서스는 병사들이 집으로 돌아가지 못하도록 자기 배를 불태우게 했어요.",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "경매장에서 사기 전에 상인이 더 싸게 파는지 확인하세요.",
	["Antes de empezar, unas palabras de la manada."] = "시작하기 전에, 무리가 전하는 몇 마디.",
	["Antes de entrar"] = "들어가기 전에",
	["Antes de entregarla te falta: %s."] = "제출하기 전에 남은 것: %s.",
	["Antes de importar"] = "가져오기 전에",
	["Antes de irte: tienes %d misiones listas para entregar. ¿Pasamos a cobrarlas?"] = "가기 전에: 제출할 퀘스트가 %d개 있어요. 보상 받으러 갈까요?",
	["Antes de irte: tienes una misión lista para entregar. ¿Pasamos a cobrarla?"] = "가기 전에: 제출할 퀘스트가 하나 있어요. 보상 받으러 갈까요?",
	["Antes de la mazmorra te falta:"] = "던전 전에 아직 필요한 것:",
	["Antes de pelear"] = "전투 전",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "전투 전: 가장 강한 주문인 불덩이 작렬로 시작하세요.",
	["Antes de restaurar"] = "복원하기 전에",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "사냥을 떠나기 전에 Alfa를 내게 맞게 설정하세요: 언어, 모양, 대신 해 줄 일, 그리고 무리가 게임 지도에서 나를 볼 수 있게 할지.",
	["Antes de una misión de élite o de grupo, un aviso con «Llamar a la manada»."] = "정예나 파티 퀘스트 전에 '무리 부르기' 알림.",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "원래 이곳은 늪이었어요. 차원문의 마력과 전쟁 때문에 붉고 메마른 죽음의 땅이 됐어요.",
	["Antes hay que hacer otra misión"] = "먼저 다른 퀘스트를 해야 함",
	["Antes necesitas"] = "먼저 필요한 것",
	["Antes necesitas otra misión"] = "먼저 다른 퀘스트 필요",
	["Antes pide %s (%s)"] = "먼저 필요: %s (%s)",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "엘프보다 먼저 트롤이 아제로스에 큰 제국을 세웠어요. 북쪽의 아마니와 남쪽의 구루바시처럼요.",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "옛날에 스톰윈드 왕국의 이름은 세계와 같은 아제로스였어요. 스톰윈드는 수도의 이름일 뿐이었죠.",
	["Antes: %s"] = "먼저: %s",
	["Antes: %s."] = "먼저: %s.",
	["Antes: %s. Ahora: %s."] = "전: %s. 지금: %s.",
	["Anunciar"] = "알리기",
	["Anunciar en el chat"] = "대화창에 알리기",
	["Anunciar en el grupo"] = "파티에 알리기",
	["Anuncios animados"] = "애니메이션 알림",
	["Anuncios animados y la manada a la vista"] = "애니메이션 알림과 눈앞의 무리",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "비네트, 필름 그레인, 바, 색조를 한 번에 끕니다.",
	["Apagada"] = "꺼짐",
	["Apagadas"] = "꺼짐",
	["Apagado"] = "꺼짐",
	["Apagado en los ajustes de abajo."] = "아래 설정에서 꺼져 있어요.",
	["Apagado, el grano se queda quieto."] = "끄면 그레인이 움직이지 않습니다.",
	["Apagado, solo las acepta y la entrega la haces tú."] = "끄면 수락만 하고, 제출은 직접 합니다.",
	["Apagados"] = "꺼짐",
	["Apagar la parte de Alfa que choca"] = "충돌하는 Alfa 부분 끄기",
	["Apagarlo"] = "끄기",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "나랄렉스의 신봉자 이벤트 마지막에 나타납니다. 드루이드가 걸어가는 동안 지켜 주세요.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "징을 세 번째로 울리면 거미 두 무리가 나온 뒤에 나타납니다.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "호드 퀘스트(물속의 물체)로 나타납니다. 냉기 주문을 씁니다.",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "Alfa 환영 설정을 마치면 바로 나타납니다.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "폭파 전문가 이벤트에서 나타납니다. 트로그 무리가 몰려오는 동안 폭파 전문가를 지켜 주세요.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "예시 프레임이 나타납니다. 원하는 곳으로 끌고 크기를 조절하세요. 파티가 이렇게 보입니다.",
	["Aplaudir"] = "박수",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "해상도 배율을 쓰지 않아도 아래 선명도를 적용합니다.",
	["Aplicar"] = "적용",
	["Aplicar %d puntos"] = "%d포인트 적용",
	["Aprende %s"] = "%s 배우기",
	["Aprende Cocina con un instructor."] = "요리 전문가에게 요리를 배우세요.",
	["Aprende Cocina para encender fogatas."] = "모닥불을 피우려면 요리를 배우세요.",
	["Aprende Minería o Herboristería"] = "채광이나 약초채집을 배우세요",
	["Aprende Pesca"] = "낚시 배우기",
	["Aprende Pesca con un instructor"] = "낚시 전문가에게 낚시 배우기",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "낚시 전문가에게 낚시를 배우고 낚싯대를 사세요. 가이드가 안내합니다.",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "낚시 전문가에게 낚시를 배우고, 낚싯대를 사서 시작 지역이나 수도에서 낚시하세요. 50부터 숙련 단계를 배우세요.",
	["Aprende equitación con %s"] = "타기 배우기: %s",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "둘 다 배우고 낚싯대를 구한 뒤 잡은 것을 75까지 요리하세요.",
	["Aprender %s"] = "배우기: %s",
	["Aprender de tus búsquedas"] = "내 검색에서 배우기",
	["Aprender una profesión o llegar a un nivel en ella."] = "전문 기술을 배우거나 숙련도를 올립니다.",
	["Aprendiste %s. %s"] = "%s을(를) 배웠어요. %s",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "클릭에 더 잘 맞는 주문을 배웠습니다:",
	["Aprendiz"] = "수습",
	["Aprendí un hechizo nuevo, ¿para qué sirve?"] = "새 주문을 배웠어요. 어디에 쓰나요?",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "아무 수도에서나 내 직업 상급자에게 배우세요.",
	["Apunto el primer día que te vi. Cada año, ese día, lo festejamos juntos. Y el 16 de noviembre es el cumpleaños de Alfa."] = "당신을 처음 본 날을 적어 뒀어요. 해마다 그날 함께 축하해요. 그리고 11월 16일은 Alfa의 생일이에요.",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "낚시할 때 Alfa가 키, 장비, 설정을 건드리지 않길 원하면 끄세요.",
	["Aquí"] = "여기",
	["Aquí adentro se caza en equipo: espera a que quien cura tenga maná antes de seguir."] = "여기서는 팀으로 사냥해요: 치유사의 마나가 찰 때까지 기다렸다가 나아가요.",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Alfa의 다른 모듈(가방, 경로, 월드 등)은 설치되는 대로 여기에 나타납니다.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "이곳에서는 게임이 위치를 알려 주지 않습니다(예: 던전 안).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "여기에서는 게임이 공유를 막습니다. 나가면 흔적이 다시 자동으로 보내집니다.",
	["Aquí empieza tu historia. Y yo voy contigo."] = "여기서 당신의 이야기가 시작돼요. 나도 함께 갈게요.",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "언제나처럼 여기 있어요. 저는 누구도 두고 가지 않아요.",
	["Aquí estoy. Si no sabes por dónde empezar, toca «¿Por dónde empiezo?»."] = "여기 있어요. 어디서 시작할지 모르면 「어디서 시작하지?」를 눌러요.",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "여기에 어둠의 문이 있어요. 1차 대전쟁 때 호드가 이 문을 지나 드레노어에서 아제로스로 쳐들어왔어요.",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "여기에 아서스의 스승, 빛의 수호자 우서의 무덤이 있어요. 테레나스 왕의 유골을 지키다 제자의 손에 쓰러졌어요.",
	["Aquí juntas XP descansada poco a poco (más si cierras sesión aquí): luego ganas el doble por enemigo hasta gastarla."] = "여기서는 휴식 경험치가 조금씩 쌓여요(여기서 접속을 종료하면 더 많이): 그 뒤로 다 쓸 때까지 적마다 두 배를 얻어요.",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "여기서 처음부터 끝까지 읽을 수 있어요: 어떻게 시작하고, 무엇을 부탁하고, 어떻게 끝나는지.",
	["Aquí no hay nodos que recolectar"] = "여기에는 채집할 것이 없음",
	["Aquí sale por qué se activó la habilidad."] = "기술이 활성화된 이유가 여기에 표시됩니다.",
	["Aquí verás cuánto llevas descubierto de cada zona de tu continente."] = "여기서 내 대륙의 지역마다 얼마나 발견했는지 볼 수 있어요.",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "몇 개 있는지, 어디서 나는지, 어떻게 쓸지 여기서 볼 수 있습니다.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "알아야 할 모든 것과 다음 할 일을 여기서 봅니다.",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "여기: %s %.1f, %.1f. 이 지점을 저장합니다.",
	["Arañazo: sangrado con el tiempo."] = "갈퀴 발톱: 지속 출혈 피해.",
	["Arcano"] = "비전",
	["Arcano para subir"] = "레벨업용 비전",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "아키몬드는 세계수의 힘을 빼앗으려 하이잘에 올랐지만, 오히려 그 나무가 그의 끝이 되었어요.",
	["Arco"] = "활",
	["Arcos, ballestas y armas de fuego"] = "활, 석궁, 총",
	["Arena"] = "모래색",
	["Arma"] = "무기",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "받는 데 필요한 레벨이나 선행 퀘스트를 경로로 만들어 줍니다.",
	["Arma de asta"] = "장창",
	["Arma de dos manos"] = "양손 무기",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "양손 무기, 문장, 심판: 혼자 레벨 올리기에 가장 좋은 성기사입니다.",
	["Arma de fuego"] = "총",
	["Arma de puño"] = "장착 무기",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "퀘스트 목록의 퀘스트를 끝낼 계획을 세우고 하나씩 안내합니다.",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "5인 파티를 꾸리세요(파티 찾기 또는 내 무리).",
	["Arma tu primer plan"] = "첫 계획 만들기",
	["Arma una ruta de %s en %s"] = "%s 경로 만들기: %s",
	["Arma y escudo"] = "무기와 방패",
	["Armadura"] = "방어도",
	["Armaduras"] = "방어구",
	["Armando"] = "만드는 중",
	["Armando el circuito de la zona..."] = "지역 순회 짜는 중...",
	["Armando «Cerrar mis misiones»..."] = "«내 퀘스트 끝내기»를 만드는 중...",
	["Armar la ruta"] = "경로 만들기",
	["Armar lo que falta"] = "빠진 것 만들기",
	["Armar mi plan"] = "내 계획 만들기",
	["Armar un plan nuevo"] = "새 계획 만들기",
	["Armas"] = "무기",
	["Armas a dos manos"] = "양손 무기 전문",
	["Armas a muerte"] = "공격 일변도 무기 전문",
	["Armas contra jugadores"] = "PvP 무기 전문",
	["Armas para grupo"] = "파티용 무기 전문",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "던전용 무기 전문: 휩쓸기 일격으로 여러 적에게 큰 피해를 주고, 우두머리에게는 죽음의 일격을 쓰며, 빗나가지 않도록 적중도 높입니다.",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "죽지 않는 것을 우선하는 무기 전문: 무기 막기가 늘고, 도망치는 적을 느리게 하며, 마지막에 방어 특성을 조금 찍어 받는 피해를 줄입니다.",
	["Armas seguro"] = "안전한 무기 전문",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "무기, 방어구, 재료, 제조법, 탈것: 누가 떨어뜨리고 누가 파는지.",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "각 전투 프레임을 원하는 곳으로 끌어 옮기세요. 끝나면 방해되지 않게 고정하세요.",
	["Arrastra otra bolsa aquí para cambiarla."] = "다른 가방을 여기로 끌어 놓으면 교체합니다.",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "끌어서 프레임을 옮기세요. 크기와 열은 치유 페이지에서 바꿀 수 있습니다.",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "끌어서 프레임을 옮기세요. 클릭하면(Shift, Ctrl, Alt와 함께 또는 없이) 무엇을 시전할지 보여 줍니다.",
	["Arrastra una bolsa aquí para ponerla."] = "가방을 여기로 끌어 놓으면 장착합니다.",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "수정: '내 퀘스트 마무리'가 다시 경로를 만들고, 순환 도우미가 다시 무엇을 쓸지 알려 주며, 지도를 확대해도 붙여 놓은 듯한 사각형이 더 이상 보이지 않습니다.",
	["Arriba a la derecha, el ícono de magia, maldición, veneno o enfermedad. Al pasar el ratón te dice qué clic lo quita."] = "오른쪽 위에 마법, 저주, 독, 질병 아이콘. 마우스를 올리면 어떤 클릭으로 해제하는지 알려 줘요.",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "창 위쪽에 장착한 가방과 칸 수가 나옵니다. 마우스를 올리면 든 것을 강조하고, 다른 가방을 끌어 놓으면 교체합니다.",
	["Arriba de tus marcos, el maná de quienes curan en tu grupo. Se destaca al terminar cada pelea."] = "틀 위에 파티 치유 전담들의 마나. 전투가 끝날 때마다 강조돼요.",
	["Arriba en esta ventana está lo último que te dije, con sus botones. Para ver los 20 más recientes: /alfa lya historial."] = "이 창 맨 위에 내가 마지막으로 한 말이 버튼과 함께 있어요. 최근 20개: /alfa lya historial.",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "위에는 Alfa 추천이 있습니다. 클릭 한 번으로 시작하세요.",
	["Arriesgado"] = "공격적",
	["Arrodillarse"] = "무릎 꿇기",
	["Arrojadiza"] = "투척 무기",
	["Arrástralo para moverlo"] = "끌어서 이동",
	["Artefacto"] = "유물",
	["Artesano"] = "장인",
	["Artesanía y comercio"] = "제작 및 직업용품",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "아서스는 안돌할에서 켈투자드를 죽였지만, 나중에 태양샘의 힘으로 리치로 되살렸어요.",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "아서스는 달라란에서 대마법사 안토니다스를 죽였고, 그 뒤 아키몬드가 도시를 파괴했어요.",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "아서스는 곡식이 감염됐다는 이유로 스트라솔름을 정화했어요. 그 결정으로 우서와 제이나와는 영원히 멀어졌어요.",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "아서스는 백성을 구할 수 있다고 믿고 노스렌드에서 서리한을 손에 넣었어요. 검은 그의 영혼을 빼앗았어요.",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "아서스와 제이나는 역병이 둘을 갈라놓기 전까지 서로 사랑했어요.",
	["Asesinato"] = "암살",
	["Asesinato para subir"] = "레벨업용 암살",
	["Aspecto"] = "상",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "아스트라나르는 잿빛 골짜기 한가운데, 호수 위 섬에 있는 엘프 마을이에요.",
	["Asusta a los enemigos cercanos. Cuidado: pueden correr y traer a otros."] = "주변 적을 공포에 빠뜨려요. 조심하세요. 도망쳐서 다른 적을 데려올 수 있어요.",
	["Asusta a los enemigos cercanos. Te da tiempo para escapar o curarte."] = "주변 적을 공포에 빠뜨려요. 도망치거나 치유할 시간을 벌어요.",
	["Asusta a todos los enemigos cercanos."] = "주변의 모든 적을 공포에 빠뜨려요.",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "주변 모두에게 공포를 겁니다. 공포에 걸리면 다른 감방 쪽으로 뛰어가지 않도록 조심하세요.",
	["Asusta a un enemigo y lo hace huir. Cuidado: puede traer a otros."] = "적을 공포에 빠뜨려 도망치게 해요. 조심하세요. 다른 적을 데려올 수 있어요.",
	["Asusta un momento al enemigo y te cura. Tu escape de emergencia."] = "잠깐 적을 공포에 빠뜨리고 나를 치유해요. 비상 탈출용이에요.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "플레이어에게 공포와 수면을 겁니다. 공포에 걸리면 다른 적 쪽으로 뛰어가지 않도록 조심하세요.",
	["Así la manada se encuentra para cazar juntos. Es tu decisión, y la cambias cuando quieras."] = "이렇게 무리가 만나서 함께 사냥해요. 선택은 당신 몫이고 언제든 바꿀 수 있어요.",
	["Así queda tu Alfa"] = "완성된 내 Alfa",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "다음 전투 전에 클릭마다 무엇을 하는지 알 수 있습니다.",
	["Así se lee tu ayuda de rotación"] = "로테이션 도우미 읽는 법",
	["Así se ven tus avisos"] = "알림은 이렇게 보입니다",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "프레임은 이렇게 보입니다. 끌어서 옮기고 아래 프레임에서 크기를 바꾸세요. 끝나면 완료를 누르세요.",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "프레임이 이렇게 보입니다. 끌어서 옮기고 아래에서 크기를 바꾸세요. 다 되면 '완료'를 누르세요.",
	["Así terminó «%s»… ¿Te cuento el final?"] = "«%s»은(는) 이렇게 끝났어요… 결말을 들려줄까요?",
	["Así: /alfa cita mañana 21:30 Minas de la Muerte"] = "예: /alfa cita tomorrow 21:30 죽음의 폐광",
	["Atacas más rápido según tus puntos de combo. Mantenlo en las peleas largas."] = "연계 점수에 따라 공격이 빨라져요. 긴 전투에서 유지하세요.",
	["Atajos"] = "바로 가기",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "폭풍의 일격: 큰 피해. 준비될 때마다 쓰세요.",
	["Ataques más rápidos después de un crítico."] = "치명타 뒤에 공격 속도가 빨라집니다.",
	["Atardecer"] = "해 질 녘",
	["Atenuar a quien está lejos"] = "멀리 있는 대상 흐리게",
	["Atiesh, el Gran Bastón del Guardián, fue de Medivh. En el Clásico se puede rehacer con fragmentos que caen en Naxxramas."] = "수호자의 지팡이 아티쉬는 메디브의 것이었어요. 클래식에서는 낙스라마스에서 떨어지는 조각으로 다시 만들 수 있어요.",
	["Atrapa al enemigo en su lugar. Para alejarte y lanzar tranquilo."] = "적을 제자리에 묶어요. 물러나서 편하게 시전하세요.",
	["Atravesar objetos pequeños"] = "작은 사물 통과",
	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "강한 천둥벼락: 여러 몬스터를 모아 모두 느리게 만듭니다.",
	["Atronar más barato para agarrar varios."] = "천둥벼락의 비용이 줄어 여러 적을 붙잡기 좋습니다.",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "더 강하고 저렴한 천둥벼락: 여러 적을 한꺼번에 붙잡아 둡니다.",
	["Atrás"] = "뒤로",
	["Aturde al enemigo en forma de oso. Úsalo para interrumpir."] = "곰 변신 상태에서 적을 기절시켜요. 차단용으로 쓰세요.",
	["Aturde al enemigo unos segundos. Úsalo para interrumpir o para escapar."] = "몇 초간 적을 기절시켜요. 차단하거나 도망칠 때 쓰세요.",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "망치로 방어 전담을 기절시킵니다. 방어 전담의 생명력을 높게 유지하세요.",
	["Aturde según tus puntos de combo. Úsalo para interrumpir o rematar."] = "연계 점수에 따라 기절시켜요. 차단하거나 마무리할 때 쓰세요.",
	["Aturdes a uno mientras peleas con otro."] = "다른 적과 싸우는 동안 한 명을 기절시킵니다.",
	["Aturdes al enemigo más peligroso."] = "가장 위험한 적을 기절시킵니다.",
	["Aturdimiento a demanda."] = "원할 때 쓰는 기절 기술입니다.",
	["Auberdine es el puerto de los elfos de la noche: de ahí salen barcos a Teldrassil y a los Reinos del Este."] = "아우버다인은 나이트 엘프의 항구예요. 텔드랏실과 동부 왕국으로 가는 배가 여기서 떠나요.",
	["Aullar al completar una misión"] = "퀘스트를 완료하면 울기",
	["Aullar con tu grupo"] = "파티와 함께 울기",
	["Aullido"] = "울음",
	["Aullido al abrir Alfa"] = "Alfa를 열 때 울음소리",
	["Aun de día el Bosque del Ocaso está oscuro. Aquí nunca sale el sol del todo."] = "그늘숲은 낮에도 어두워요. 여기선 해가 완전히 뜨지 않아요.",
	["Aura"] = "오라",
	["Automática"] = "자동",
	["Automático"] = "자동",
	["Automático: el del buscador de grupo, o por tu clase y tu forma (postura defensiva u oso tanquean)."] = "자동: 파티 찾기의 역할, 또는 직업과 변신 상태(방어 태세나 곰 변신이면 방어 전담).",
	["Automático: el que marcaste en tu grupo, o tu actitud o forma."] = "자동: 파티에서 정한 역할, 또는 태세나 변신 상태.",
	["Avanza en tu guía con la flecha"] = "화살표와 함께 가이드 진행",
	["Avanzado"] = "고급",
	["Aventura"] = "모험",
	["Aventura (2): explorar todo el mapa del mundo con un personaje y terminar la cadena de Lord Valthalak (el conjunto de mazmorra 2)."] = "모험 (2): 한 캐릭터로 세계 지도 전체를 탐험하고 군주 발탈락 연계 퀘스트(던전 세트 2) 완료.",
	["Aventura, Personaje, Mundo, Oficios, Manada y Ajustes. Cada una tiene sus páginas."] = "모험, 캐릭터, 월드, 전문 기술, 무리, 설정. 각각 자기 페이지가 있어요.",
	["Aventura: descanso más rápido, vida y maná tras cada muerte, ver mejor a los sigilosos, talentos hasta 5 niveles antes y vuelos más baratos y rápidos."] = "모험: 휴식 경험치가 더 빨리 쌓이고, 처치할 때마다 생명력과 마나 회복, 은신 감지 향상, 특성을 5레벨 일찍, 더 싸고 빠른 비행.",
	["Avienta a todos los que están cerca: si peleas de lejos, aléjate."] = "주변 모두를 밀쳐 냅니다. 원거리라면 떨어져 있으세요.",
	["Avienta y aturde a todos los que están cerca: ponte con la espalda en la pared."] = "주변 모두를 밀쳐 내고 기절시킵니다. 벽을 등지고 서세요.",
	["Avisar a tu grupo cuando completas una misión"] = "퀘스트를 완료하면 파티에 알리기",
	["Avisar al juntar lo de tu lista"] = "목록을 다 모으면 알림",
	["Avisar antes de una misión que cierra otra"] = "다른 퀘스트를 막는 퀘스트 전에 알림",
	["Avisar con estos espacios libres o menos"] = "빈 칸이 이 수 이하이면 알림",
	["Avisar cuando baje de"] = "다음 아래로 떨어지면 알림",
	["Avisar cuando estén casi llenas"] = "거의 찼을 때 알리기",
	["Avisar cuando los precios tengan más de"] = "가격이 다음보다 오래되면 알림",
	["Avisar cuando me queden"] = "이만큼 남으면 알려 줘",
	["Avisar cuando queden"] = "이만큼 남으면 알림",
	["Avisar de cartas que vencen"] = "만료되는 우편 알리기",
	["Avisar de misiones de élite"] = "정예 퀘스트 경고",
	["Avisar de misiones grises"] = "회색 퀘스트 알려 주기",
	["Avisar de zonas peligrosas"] = "위험한 지역 알리기",
	["Avisar desde"] = "알림 시작",
	["Avisar en el chat cuando completas una misión"] = "퀘스트를 완료하면 채팅에 알리기",
	["Avisar los hechizos nuevos para entrenar"] = "배울 새 주문 알리기",
	["Avisar rangos viejos en tus barras"] = "단축바의 낮은 레벨 주문 알리기",
	["Avisar si la barra de una forma está vacía"] = "형태의 단축바가 비어 있으면 알림",
	["Avisar si lo das más barato de"] = "이만큼 싸게 팔면 경고",
	["Avisar también si le quedan menos de"] = "남은 시간이 이보다 적어도 알림",
	["Avisarme al descubrir un jefe"] = "우두머리를 발견하면 알림",
	["Avisarme al entrar a una mazmorra"] = "던전에 들어가면 알림",
	["Avisarme cuando mi equipo se gaste"] = "장비가 닳으면 알림",
	["Avisarme cuando mis bolsas se llenen"] = "가방이 가득 차면 알림",
	["Avisarme cuando se me acabe la comida o el agua"] = "음식이나 물이 떨어져 가면 알려 줘",
	["Avisarme de mi XP descansada"] = "휴식 경험치 알림",
	["Avisarme del talento que toca"] = "다음 특성 알리기",
	["Avisarme en la ciudad si tengo habilidades por aprender"] = "배울 기술이 있으면 마을에서 알림",
	["Avisarme si me falta mi buff fuera de combate"] = "전투 중이 아닐 때 강화 효과가 없으면 알림",
	["Aviso"] = "알림음",
	["Aviso al poner la flecha"] = "화살표를 설정할 때 알림",
	["Aviso con lo que sacas"] = "낚은 것 요약",
	["Aviso para cortar"] = "차단 알림",
	["Aviso urgente, con sonido"] = "긴급 알림 (소리 포함)",
	["Avisos"] = "알림",
	["Avisos con sonido"] = "소리 알림",
	["Avisos de descanso"] = "휴식 알림",
	["Avisos de jefes"] = "우두머리 경고",
	["Avisos de jefes como los recomienda Alfa"] = "Alfa 추천대로 설정한 우두머리 경고",
	["Avisos de jefes del juego"] = "게임의 우두머리 경고",
	["Avisos de reacción"] = "반응 알림",
	["Avisos y diario"] = "알림 및 일지",
	["Avisos, golpe y estadísticas"] = "알림, 공격 주기, 능력치",
	["Ay, lobo… van varias caídas seguidas. Respira, repara tu equipo y, si quieres, pide ayuda a la manada."] = "아이고, 늑대야… 연달아 여러 번 쓰러졌네요. 숨 한번 쉬고, 장비를 수리하고, 원하면 무리에게 도움을 청해요.",
	["Ayuda al subastar"] = "경매 도우미",
	["Ayuda de rotación"] = "로테이션 도우미",
	["Ayuda de rotación para las 27 especializaciones y la ventana /alfa paisaje con 68 ajustes gráficos explicados."] = "27개 전문화 모두를 위한 로테이션 도우미와, 그래픽 설정 68개를 설명해 주는 /alfa paisaje 창.",
	["Ayudas de combate"] = "전투 도우미",
	["Ayudas para tu personaje"] = "캐릭터 도우미",
	["Azeroth"] = "아제로스",
	["Azeroth tiene dos continentes en el Clásico: Kalimdor al oeste y los Reinos del Este. En medio está el Gran Mar."] = "클래식의 아제로스에는 대륙이 둘 있어요. 서쪽의 칼림도어와 동부 왕국이고, 그 사이에 대해가 있어요.",
	["Azshara lleva el nombre de la reina de los elfos que abrió la puerta a la Legión Ardiente. Tras la Gran División se convirtió en la reina de los naga."] = "아즈샤라는 불타는 군단에게 문을 열어 준 엘프 여왕의 이름을 땄어요. 대분리 이후 그녀는 나가의 여왕이 됐어요.",
	["Azshara y los Altonato que se hundieron con su palacio no murieron: se transformaron en los naga."] = "궁전과 함께 가라앉은 아즈샤라와 명가는 죽지 않았어요. 나가로 변했어요.",
	["Azul"] = "파란색",
	["Azul de medianoche casi negro con detalles en plata de luna. Para cazar de noche."] = "거의 검은 한밤의 파랑에 달빛 은색 장식. 밤 사냥용.",
	["Aún nada esta semana"] = "이번 주는 아직 없어요",
	["Aún nadie responde"] = "아직 응답 없음",
	["Aún no conozco ese objeto. Pásale el ratón encima y vuelve a intentarlo."] = "아직 모르는 아이템입니다. 마우스를 올린 다음 다시 시도하세요.",
	["Aún no conozco su precio. Al buscarlo o escanear, Alfa lo aprende."] = "아직 가격을 몰라요. 검색하거나 훑어보면 Alfa가 배워요.",
	["Aún no dejas notas. También sirve /alfa nota <texto>."] = "아직 메모가 없어요. /alfa nota <내용>도 돼요.",
	["Aún no está terminada: te falta %s."] = "아직 완료되지 않았습니다. 남은 것: %s.",
	["Aún no está terminada: termínala antes de entregarla."] = "아직 완료되지 않았습니다. 제출하기 전에 완료하세요.",
	["Aún no ganas oro en esta sesión. Alfa cuenta lo que ganas desde que entraste al juego."] = "이번 접속에서는 아직 번 골드가 없어요. Alfa는 접속한 뒤로 번 것을 세요.",
	["Aún no guardas ningún conjunto."] = "아직 저장한 구성이 없어요.",
	["Aún no hay historias"] = "아직 이야기가 없습니다",
	["Aún no hay misiones de clase para ti: la próxima abre a nivel %d."] = "아직 내 직업 퀘스트가 없습니다. 다음 퀘스트는 %d레벨에 열립니다.",
	["Aún no hay personajes guardados"] = "아직 저장된 캐릭터가 없습니다",
	["Aún no la aprendes"] = "아직 배우지 않음",
	["Aún no la tomas"] = "아직 받지 않음",
	["Aún no lo aprendes"] = "아직 배우지 않음",
	["Aún no los aprendes"] = "아직 배우지 않음",
	["Aún no picaba"] = "아직 입질 없음",
	["Aún no puedes tomar %s"] = "아직 %s 받을 수 없음",
	["Aún no sé cómo va."] = "아직 소식이 없어요.",
	["Aún no tienes el nivel"] = "아직 레벨이 낮음",
	["Aún no tienes nada abierto. Mira Todas o usa los filtros de arriba para encontrar una guía."] = "아직 열린 가이드가 없습니다. 전체를 보거나 위의 필터로 가이드를 찾아보세요.",
	["Aún no tienes perfiles"] = "아직 프로필이 없어요",
	["Aún no tienes precios de la subasta: escanéala para saber cuánto vale de verdad."] = "아직 경매장 가격이 없습니다. 실제 가치를 알려면 경매장을 스캔하세요.",
	["Aún no tienes precios. Pulsa «Escanear con Alfa»."] = "아직 가격이 없습니다. «Alfa로 스캔»을 누르세요.",
	["Aún no tienes rutas. Ármalas en la ventana de Alfa: Aventura > Rutas; cada una aparece aquí como guía."] = "아직 경로가 없습니다. Alfa 창의 모험 > 경로에서 만드세요. 만든 경로는 각각 여기에 가이드로 나타납니다.",
	["Aún sin abrir: gana tu primer punto"] = "아직 열리지 않음: 첫 점수를 얻으세요",
	["Bahía del Botín es el puerto del cártel Bonvapor, y ahí manda el barón Revilgaz."] = "무법항은 스팀휘들 무역회사의 항구이고, 리빌가즈 남작이 다스려요.",
	["Bailar"] = "춤추기",
	["Baja"] = "낮음",
	["Baja tu amenaza un rato. Úsalo si los enemigos se te vienen encima."] = "한동안 위협을 낮춰요. 적이 쫓아오면 쓰세요.",
	["Baja tu amenaza. Úsalo en grupo para no quitarle el enemigo al tanque."] = "위협을 낮춰요. 파티에서 방어 전담의 적을 뺏지 않게 쓰세요.",
	["Bajar"] = "아래로",
	["Bajarlas ayuda en tarjetas de video con poca memoria."] = "낮추면 메모리가 적은 그래픽 카드에 도움이 됩니다.",
	["Bajas"] = "낮음",
	["Bajas la amenaza que generas. Úsalo si el enemigo se te viene encima."] = "위협을 낮춰요. 적이 쫓아오면 쓰세요.",
	["Bajo"] = "낮음",
