	["Bienvenido a %s. Mira bien antes de jalar: un grupo de más nos puede tumbar a todos."] = "%s에 온 걸 환영해요. 끌기 전에 잘 봐요: 몹 한 무더기만 더 끌어도 다 같이 쓰러질 수 있어요.",
	["Bilineal"] = "쌍선형",
	["Blackmoore le enseñó a Thrall a leer y a pelear para usarlo como arma... y eso terminó volviéndose en su contra."] = "블랙무어는 스랄을 무기로 쓰려고 글과 싸움을 가르쳤어요... 그게 결국 자신을 겨누게 됐죠.",
	["Blanco"] = "흰색",
	["Blizzard no deja que un addon copie tu mapa. Abre su ventana con el botón «Abrir clic para lanzar» o escribe %s en el chat, y arma ahí los mismos clics."] = "블리자드는 애드온이 클릭 설정을 복사하는 것을 허용하지 않습니다. «클릭 시전 열기» 버튼으로 창을 열거나 채팅에 %s 명령어를 입력한 뒤, 거기서 같은 클릭을 설정하세요.",
	["Blizzard no deja que un addon copie tu mapa. Se abrió su ventana de clic para lanzar: arma ahí los mismos clics."] = "블리자드는 애드온이 클릭 설정을 복사하는 것을 허용하지 않습니다. 블리자드 클릭 시전 창이 열렸으니, 거기서 같은 클릭을 설정하세요.",
	["Blizzard no deja que un addon copie tu mapa. Ábrelo en el menú del juego: Opciones, Clic para lanzar."] = "블리자드는 애드온이 클릭 설정을 복사하는 것을 허용하지 않습니다. 게임 메뉴의 설정 > 클릭 시전에서 여세요.",
