	["Bloquear su lugar"] = "자리 잠금",
	["Bloqueas más y ganas ira al bloquear."] = "방패 막기가 늘고 막을 때 분노를 얻습니다.",
	["Bloqueas más y ganas ira."] = "방패 막기가 늘고 분노를 얻습니다.",
	["Bloqueas más, y cada bloqueo te da ira."] = "방패 막기가 늘고, 막을 때마다 분노를 얻습니다.",
	["Bloqueaste, esquivaste o paraste: Revancha es barata y genera mucha amenaza. Necesita actitud defensiva."] = "방패 막기, 회피, 무기 막기를 했습니다. 복수가 저렴하고 위협 수준을 많이 만듭니다. 방어 태세가 필요합니다.",
