	["Brillo normal (nits)"] = "기본 밝기 (니트)",
	["Brillo: un borde dorado que late y una insignia «!» (llena si el objeto empieza una misión). Marco fijo: el marco dorado del juego. Nada: sin marca."] = "반짝임: 깜빡이는 금색 테두리와 «!» 배지(아이템이 퀘스트를 시작하면 채워진 배지). 고정 테두리: 게임의 금색 테두리. 없음: 표시 안 함.",
	["Brujo"] = "흑마법사",
