	["Buen lanzamiento"] = "좋은 던지기",
	["Buena caza hoy: %s Descansa, que yo cuido tu lugar."] = "오늘 사냥 잘했어요: %s 푹 쉬어요, 자리는 제가 지킬게요.",
	["Buenas noches, lobo. Si te vas a ir pronto, termina en una posada para descansar bien."] = "좋은 저녁이에요, 늑대님. 곧 나갈 거면 여관에서 끝내서 푹 쉬세요.",
	["Buenas tardes. Es buena hora para entregar misiones y ver qué hay de nuevo."] = "좋은 오후예요. 퀘스트를 제출하고 새 소식을 볼 좋은 때예요.",
	["Buff activo"] = "버프 활성",
