	["Build completo"] = "빌드 완성",
	["Build importado"] = "가져온 빌드",
	["Build importado de una cadena. Alfa lo resuelve en tu árbol y te avisa si algún talento no existe."] = "문자열에서 가져온 빌드입니다. Alfa가 내 특성 트리에 맞춰 풀고, 없는 특성이 있으면 알려 줍니다.",
	["Busca %s en: %s."] = "%s 찾을 곳: %s.",
	["Busca addons que chocan con Alfa, partes apagadas y ajustes raros, con el arreglo a un clic. También con /alfa diagnostico."] = "Alfa와 충돌하는 애드온, 꺼진 부분, 이상한 설정을 찾아 클릭 한 번으로 고쳐요. /alfa diagnostico로도 돼요.",
	["Busca al entrenador de tu clase en la ciudad."] = "마을에서 직업 상급자를 찾으세요.",
	["Busca cualquier cosa del juego"] = "게임의 모든 것 찾기",
	["Busca cualquier cosa, en español o en inglés…"] = "무엇이든 찾아보세요(스페인어나 영어로)…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "초당 공격력이 가장 높은 양손 무기를 찾으세요. 피해를 가장 많이 올려 줍니다.",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "가장 느리고 강한 양손 무기를 찾으세요. 문장이 그 무기로 들어갑니다.",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "레벨업 가이드에서 퀘스트 지역을 찾으세요.",
	["Busca lo mejor que puedes usar"] = "쓸 수 있는 최고 장비 찾기",
	["Busca por aquí"] = "이 근처 찾기",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "초당 공격력이 가장 높은 활, 총, 석궁을 항상 찾으세요.",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "방패 피해 흡수량이 높은 방패를 찾으세요. 방패 밀쳐내기의 피해가 올라갑니다.",
	["Busca un objeto en las bolsas, bancos y equipo de todos tus personajes. Los demás, con lo último que guardó Alfa."] = "모든 캐릭터의 가방, 은행, 장비에서 아이템을 찾아요. 다른 캐릭터는 Alfa가 마지막으로 저장한 내용으로요.",
	["Busca una misión, un PNJ, una zona o una palabra…"] = "퀘스트, NPC, 지역, 단어 검색…",
	["Busca una versión nueva de Alfa"] = "Alfa 새 버전 확인",
