	["Buzones, entrenadores, banco, subasta, reparar..."] = "우체통, 전문가, 은행, 경매장, 수리...",
	["Buzón"] = "우체통",
	["Básico"] = "기본",
	["Búscalo en %s."] = "%s에서 찾아보세요.",
	["Búscalo en la Enciclopedia: objetos, PNJ, misiones, zonas y raros, con dónde están y el botón «Guíame»."] = "백과사전에서 찾으세요. 아이템, NPC, 퀘스트, 지역, 희귀 몹의 위치와 「안내해 줘」 버튼이 있어요.",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "이름으로 검색하세요. 가방에 있으면 달성됩니다.",
	["CPS"] = "HPS",
	["Cabeza"] = "머리",
	["Cada 2 niveles"] = "2레벨마다",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "위상마다 용군단을 이끌어요: 알렉스트라자는 붉은용, 이세라는 녹색용, 노즈도르무는 청동용, 말리고스는 푸른용, 넬타리온은 검은용.",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Alfa가 바꾼 설정은 모두 이전 값으로 돌아갑니다. 필터는 바뀌지 않습니다.",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "각 알림과 이유는 %d번까지 글자와 함께 나오고, 그 뒤에는 아이콘만 남습니다.",
	["Cada año, el día que empezaron a cazar juntos, Lya lo festeja. Y también el cumpleaños de Alfa."] = "해마다 함께 사냥을 시작한 날이면 리아가 축하해요. Alfa의 생일도요.",
	["Cada bloqueo te da ira: nunca te falta."] = "막을 때마다 분노를 얻어 부족할 일이 없습니다.",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "가방마다 이름과 칸 수가 있는 블록으로 나눕니다.",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "각 행동 단축 버튼에 스타일의 테두리와 배경, 사각 아이콘, 단축키와 개수에 Alfa 글꼴.",
	["Cada casilla en su lugar, como en tus bolsas."] = "모든 칸을 가방에 있는 그대로 보여 줍니다.",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "직업마다 25, 45, 60레벨에 유산 도전을 줘요. 다른 직업을 키워도 계정에 점수가 쌓여요.",
	["Cada clic que cura también selecciona a ese compañero, para seguir con otro poder, un buff o quitarle una maldición o un veneno."] = "치유하는 클릭마다 그 동료를 대상으로 지정해서, 다른 기술이나 강화 효과를 쓰거나 저주나 독을 해제할 수 있어요.",
	["Cada cofre o tesoro conocido."] = "알려진 모든 상자와 보물입니다.",
	["Cada crítico hace sangrar."] = "치명타마다 출혈을 일으킵니다.",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "매주 일요일 가시덤불 골짜기에서: 특별한 물고기 떼에서 얼룩무늬 별미고기 40마리를 가장 먼저 가져오는 사람이 우승해요. 상품으로 바꿀 수 있는 희귀한 물고기도 나와요.",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "모든 던전과 공격대 입구를 레벨 범위와 함께 표시합니다. 클릭: 해당 페이지, Shift+클릭: 화살표가 안내합니다.",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "각 대사는 최대 세 번까지 나옵니다. 이걸 누르면 처음부터 다시 나옵니다.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "치명타가 터질 때마다 적이 출혈 상태가 됩니다. 손쉽게 얻는 추가 피해입니다.",
	["Cada grupo de la banda en su propia columna (o fila), como en la ventana de banda. Con el orden por grupo."] = "공격대 파티마다 자기 열(또는 행)에, 공격대 창처럼. 파티별 정렬과 함께.",
	["Cada hierba pide más habilidad que la anterior: recoge todo lo que puedas y sube sola. Enciende el rastreo de hierbas."] = "약초마다 전보다 높은 숙련도가 필요해요. 보이는 건 다 캐면 저절로 올라요. 약초 찾기를 켜세요.",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "약초마다 자라는 곳이 있어요. 물가에, 산에, 나무 아래에.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "희귀 몹이 나타나는 알려진 모든 위치입니다.",
	["Cada lunes te pongo tres retos chiquitos: misiones, raros y uno sorpresa. Tu avance está en mi página y cada reto cumplido vale una salchicha de premio."] = "매주 월요일 작은 도전 세 개를 줘요. 퀘스트, 희귀, 그리고 깜짝 도전 하나. 진행도는 제 페이지에 있고, 하나 끝낼 때마다 상으로 소시지 하나예요.",
	["Cada lunes, tres retos chiquitos con su salchicha de premio. Tu avance sale arriba, en esta página."] = "매주 월요일, 소시지 상이 걸린 작은 도전 세 개. 진행도는 이 페이지 위에 나와요.",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "썬더 블러프의 고원은 저마다 쓰임이 있어요. 장로와 드루이드의 고원, 정령의 고원, 사냥꾼의 고원.",
	["Cada misión que terminas te hace más fuerte."] = "퀘스트를 하나 끝낼 때마다 더 강해져요.",
	["Cada muelle con cuánto falta para que llegue su barco o zepelín."] = "부두마다 배나 비행선이 도착하기까지 남은 시간.",
	["Cada muelle con cuánto falta para que llegue."] = "부두마다 도착까지 남은 시간.",
	["Cada nivel"] = "레벨마다",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "환영 설정의 각 단계를 끝까지 스크롤할 수 있어, 닫았다가 다시 열 필요가 없습니다.",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "프리셋마다 이미 아는 주문으로 클릭을 채웁니다. 나중에 치유 페이지에서 원하는 대로 바꾸세요.",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "도전 하나에 1점입니다. Forever 출시 시점의 도전 수: %d. 캐릭터마다 최대 사용 가능: %d.",
	["Cada semana guardo una copia de tus ajustes y perfiles. En Ajustes > Estilo y sonido, en «Respaldos», vuelves a una con un clic."] = "매주 설정과 프로필을 복사해 둬요. 설정 > 스타일과 소리의 '백업'에서 클릭 한 번으로 되돌릴 수 있어요.",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "새 버전마다 늑대 인트로와 이런 업데이트 노트로 맞이합니다.",
	["Cada vez que aprendes uno de los principales de tu clase te digo en corto para qué sirve y cuándo usarlo."] = "직업의 주요 주문을 배울 때마다 어디에 쓰는지, 언제 쓰는지 짧게 알려 줘요.",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "게임에 들어올 때마다 늑대와 달의 인트로가 반겨 줍니다. 클릭하거나 Esc로 건너뜁니다.",
	["Cada vez: %s."] = "매번: %s.",
	["Cada zona con lobos y cuántos hay en cada guarida. En el mapa del mundo también sale."] = "늑대가 있는 지역마다 굴별로 몇 마리인지. 세계 지도에도 나와요.",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "지도의 모든 아이콘이 화면에서 정확한 크기로, 가장자리까지 선명하게 보입니다.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "케언 블러드후프는 썬더 블러프에서 다스리지만, 그림토템의 마가사는 겉보기만큼 그를 좋아하지 않아요.",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "케언 블러드후프는 하이잘 산에서 스랄과 함께 군단에 맞서 싸웠어요.",
	["Caja para escribir con el estilo"] = "스타일을 입힌 입력창",
	["Calculando"] = "계산 중",
	["Calculando la vuelta más corta…"] = "가장 짧은 순환 경로를 계산하는 중…",
	["Calidad"] = "품질",
	["Calidad de la niebla"] = "안개 품질",
	["Calidad de las sombras"] = "그림자 품질",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "춤추기, 웃기, 박수 등 감정 표현의 음성을 끕니다.",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "사냥꾼 고양이가 하품하는 소리 같은 소환수 소리를 끕니다.",
	["Calma, que la cacería no se va a ningún lado. Come algo, repara y, si es mucho, la manada te echa la mano."] = "진정해요, 사냥은 어디 안 가요. 뭐 좀 먹고, 수리하고, 벅차면 무리가 도와줄 거예요.",
	["Cambia a «Todo» para ver su botín completo."] = "모든 전리품을 보려면 «전체»로 바꾸세요.",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "이 지역의 Alfa 지도로 바꿉니다. 온 세상을 확대할 수 있는 한 지도에 마커와 함께 보여 줍니다.",
	["Cambia de plano cuando está lleno, «¿Quién tiene...?» y los festejos de la manada."] = "붐빌 때 레이어 바꾸기, '누가 ... 있나요?', 무리의 축하.",
	["Cambia el modo limpio del mapa"] = "지도 깔끔 모드 전환",
	["Cambia lo que quieras: se guarda al momento."] = "원하는 대로 바꾸세요. 바로 저장됩니다.",
	["Cambiar"] = "변경",
	["Cambiar de forma te quita lentitudes y raíces: úsalo para escapar."] = "변신하면 감속과 이동 불가 효과가 풀립니다. 도망칠 때 쓰세요.",
	["Cambiar de plano"] = "레이어 바꾸기",
	["Cambiar de plano si está lleno"] = "붐빌 때 레이어 바꾸기",
	["Cambiar de plano: te pasa al de un lobo de la manada con su guarida abierta"] = "레이어 바꾸기: 굴을 연 무리 늑대의 레이어로 옮겨요",
	["Cambiar el tamaño"] = "크기 조절",
	["Cambiar esta meta"] = "이 목표 변경",
	["Cambiar guía"] = "가이드 변경",
	["Cambiar la meta"] = "목표 변경",
	["Cambiar nombre..."] = "이름 바꾸기...",
	["Cambiar o borrar"] = "변경 또는 삭제",
	["Cambias de actitud según la pelea sin perder ira."] = "전투 상황에 따라 분노를 잃지 않고 태세를 바꿉니다.",
	["Cambias de actitud sin perder ira."] = "분노를 잃지 않고 태세를 바꿉니다.",
	["Cambias de actitud sin perder ira: puedes pasar a defensiva cuando se complica."] = "분노를 잃지 않고 태세를 바꿉니다. 상황이 어려워지면 방어 태세로 바꿀 수 있습니다.",
	["Cambias vida por maná. Úsalo y luego recupera tu vida comiendo."] = "생명력을 마나로 바꿔요. 쓰고 나서 먹어서 생명력을 채우세요.",
	["Cambiaste %d ajustes aquí. Volver a ponerlos al entrar está apagado (Avanzado)."] = "여기서 설정 %d개를 바꿨습니다. 접속할 때 다시 적용하기는 꺼져 있습니다(고급).",
	["Camina"] = "걷기",
	["Camina por el agua: espérenlo en tierra y atráiganlo con un ataque a distancia."] = "물속을 걸어 다닙니다. 땅에서 기다렸다가 원거리 공격으로 끌어오세요.",
	["Caminar"] = "걷기",
	["Camino al 60"] = "60까지의 길",
	["Camisa"] = "속옷",
	["Campana"] = "종",
	["Campo de visión"] = "시야각",
	["Canal oculto: %s (%s, número %s, intentos %d)"] = "숨은 채널: %s(%s, 번호 %s, 시도 %d회)",
	["Cancelar"] = "취소",
	["Cantidad: %d"] = "수량: %d",
	["Capas de Alfa: elige qué se ve en el mapa"] = "Alfa 레이어: 지도에 표시할 것 선택",
	["Capas del mapa"] = "지도 레이어",
	["Capas en la lupa del mapa del juego"] = "게임 지도 돋보기의 레이어",
	["Capturas"] = "낚은 것",
	["Capturas: %d de %d"] = "낚은 수: %d / %d",
	["Carbón cálido y el naranja de las brasas, como la manada junto al fuego."] = "따뜻한 숯과 불씨의 주황, 모닥불 곁의 무리처럼.",
	["Carcaj"] = "화살통",
	["Carcajs"] = "화살통",
	["Cargando los datos…"] = "데이터를 불러오는 중…",
	["Cargando tus cartas..."] = "우편을 불러오는 중...",
	["Cargando…"] = "불러오는 중…",
	["Cargar en actitud defensiva."] = "방어 태세에서 돌진.",
	["Cargar en actitud defensiva: empiezas cada pelea sin cambiar de actitud."] = "방어 태세에서 돌진: 태세를 바꾸지 않고 모든 전투를 시작합니다.",
	["Cargar te da más ira al empezar: la pelea arranca a tu favor."] = "돌진으로 시작할 때 분노를 더 얻어 유리하게 전투를 시작합니다.",
	["Carrete"] = "릴",
	["Casa de subastas"] = "경매장",
	["Casi no te queda espacio"] = "공간이 거의 없어요",
	["Casi todo Alfa está apagado"] = "Alfa가 거의 다 꺼져 있어요",
	["Casilla de bolsa vacía"] = "빈 가방 칸",
	["Categorías"] = "분류",
	["Caza %d horas"] = "%d시간 사냥하기",
	["Caza limpio y no te alejes de la manada."] = "깔끔하게 사냥하고 무리에서 멀어지지 마요.",
	["Cazador"] = "사냥꾼",
	["Cazador de bancos"] = "물고기 떼 사냥꾼",
	["Cazar en manada"] = "무리 사냥",
	["Cazar juntos"] = "같이 사냥하기",
	["Caíste %d veces, pero saliste de pie."] = "%d번 쓰러졌지만, 두 발로 걸어 나왔어요.",
	["Caíste %d veces, pero siempre te levantaste."] = "%d번 쓰러졌지만 늘 다시 일어났어요.",
	["Caíste %d vez, pero te levantaste."] = "%d번 쓰러졌지만 다시 일어났어요.",
	["Caíste una vez, pero saliste de pie."] = "한 번 쓰러졌지만, 두 발로 걸어 나왔어요.",
	["Caña de pescar"] = "낚싯대",
	["Caña viajera"] = "여행하는 낚싯대",
	["Cañas y cebos"] = "낚싯대와 미끼",
	["Cebo de %d minutos"] = "%d분 미끼",
	["Cebo preferido"] = "선호 미끼",
	["Cebo: %s"] = "미끼: %s",
	["Cebos"] = "미끼",
	["Cecina dura"] = "질긴 육포",
	["Celestes"] = "하늘족",
	["Cenarius, el señor del bosque, es hijo de Malorne, el Ciervo Blanco. Los druidas de la Alianza y de la Horda lo honran por igual."] = "숲의 군주 세나리우스는 흰 수사슴 말로른의 아들이에요. 얼라이언스와 호드의 드루이드 모두 똑같이 그를 기려요.",
	["Ceniza"] = "재",
	["Central"] = "가운데",
	["Centrar en mí"] = "내 위치로",
	["Cerca de Gnomeregan verás gnomos leprosos: los que se quedaron atrás cuando la radiación llenó su ciudad."] = "놈리건 근처에서는 나병 노움을 볼 수 있어요. 도시에 방사능이 찼을 때 남겨진 이들이에요.",
	["Cerca de la entrada hay un gong: tocarlo trae oleadas de arañas y luego un jefe."] = "입구 근처에 징이 있습니다. 울리면 거미 무리가 몰려온 뒤 우두머리가 나옵니다.",
	["Cerca de ti"] = "내 근처",
	["Cerca de ti: %s"] = "내 근처: %s",
	["Cerca de ti: %s."] = "주변: %s.",
	["Cerca del suelo, la cámara gira sobre tu personaje en lugar de chocar."] = "땅 가까이에서는 카메라가 부딪히는 대신 캐릭터 주위를 돕니다.",
	["Cerrada"] = "닫힘",
	["Cerrada: hiciste otra que la excluye"] = "닫힘: 이 퀘스트를 막는 다른 퀘스트를 했습니다",
	["Cerrada: nadie te pide entrar. Ábrela para echarle la mano a la manada."] = "닫힘: 아무도 들어오겠다고 하지 않아요. 열어서 무리를 도와주세요.",
	["Cerrar"] = "닫기",
