	["Cerraste tu guarida."] = "굴을 닫았어요.",
	["Cerrotajo es el primer pueblo orco grande que encuentras en Durotar; desde ahí se cuida el camino entre el Valle de los Retos y Orgrimmar."] = "칼바위 언덕은 듀로타에서 처음 만나는 큰 오크 마을이에요. 그곳에서 시험의 골짜기와 오그리마 사이의 길을 지켜요.",
	["Chamán"] = "주술사",
	["Chatarra"] = "잡동사니",
	["Chispas, humo, polvo y efectos de hechizos."] = "불꽃, 연기, 먼지, 주문 효과.",
	["Chocar con el agua"] = "물과 충돌",
	["Choque sagrado: daño instantáneo, cada vez que esté listo."] = "신성 충격: 즉시 피해. 준비될 때마다 쓰세요.",
	["Choque: daño instantáneo."] = "충격: 즉시 피해.",
	["Choques de la cámara"] = "카메라 충돌",
	["Chuleta de cordero"] = "양고기 토막",
	["Ciega a un enemigo un rato. Útil para salir de una pelea mala."] = "한동안 적의 눈을 멀게 해요. 불리한 전투에서 빠져나갈 때 유용해요.",
	["Cielo y clima"] = "하늘과 날씨",
	["Cien al cesto"] = "바구니에 백 마리",
	["Cierra la ventana de talentos y hechizos del juego y vuelve a aplicar"] = "게임의 특성 및 주문 창을 닫고 다시 적용하세요",
	["Cierra misiones de esta zona"] = "이 지역 퀘스트 마무리",
	["Cierra una pestaña para abrir esta guía."] = "이 가이드를 열려면 탭 하나를 닫으세요.",
	["Cierra una pestaña para abrir otra."] = "다른 것을 열려면 탭 하나를 닫으세요.",
	["Cierra una pestaña para abrir tu plan."] = "계획을 열려면 탭 하나를 닫으세요.",
	["Cierra una pestaña para abrir tu ruta."] = "경로를 열려면 탭 하나를 닫으세요.",
	["Cincuenta. Casi en la cima, y yo contigo."] = "쉰. 거의 정상이고, 난 당신 곁에 있어요.",
	["Cintura"] = "허리",
	["Circuito de %s"] = "%s 순회",
	["Circuito de la zona"] = "지역 순회",
	["Citas de la manada"] = "무리 약속",
	["Citas de la manada, «¿Quién va?», raros con reloj y notas en tu mapa."] = "무리 약속, '누가 가요?', 희귀 몹 타이머, 지도 위 메모.",
	["Ciudad"] = "마을",
	["Ciudad Manitas, dentro de Forjaz, es el barrio de los gnomos: ruido, vapor e inventos por todos lados."] = "아이언포지 안의 땜장이 마을은 노움 구역이에요. 어디나 소음, 증기, 발명품이에요.",
	["Clase"] = "직업",
	["Clases (27): llegar a nivel 25, 45 y 60 con cada una de las 9 clases."] = "직업 (27): 9개 직업 각각으로 25, 45, 60레벨 달성.",
	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "오른쪽 클릭(또는 Shift+클릭): 그곳에 마커. Ctrl+클릭: 저장하지 않고 화살표와 경로로 안내합니다.",
	["Clic derecho en la misión, en tu registro o en el rastreador: «Ver la cadena completa». Te digo cuáles hiciste y el premio del final."] = "퀘스트 목록이나 추적기에서 퀘스트를 오른쪽 클릭: '연계 퀘스트 전체 보기'. 어떤 걸 했는지와 최종 보상을 알려 줘요.",
	["Clic derecho en su retrato o en su nombre del chat y elige «Invitar al clan». A tu hermandad le llega con un clic."] = "초상화나 채팅 이름을 오른쪽 클릭해서 「클랜에 초대」를 고르세요. 길드 초대는 클릭 한 번이에요.",
	["Clic derecho en un jugador (su retrato, su nombre en el chat o tu grupo) y elige tu hermandad: la invitación le llega sin escribir su nombre. Para una comunidad, Alfa te deja el nombre listo para pegar en la ventana del juego."] = "플레이어(초상화, 대화창의 이름 또는 파티)를 우클릭하고 길드를 고르세요. 이름을 입력하지 않아도 초대가 전달됩니다. 커뮤니티는 Alfa가 게임 창에 붙여 넣을 이름을 준비해 줍니다.",
	["Clic derecho en un jugador y «Invitar al clan»: eliges tu hermandad o tu comunidad y la invitación le llega sin escribir su nombre."] = "플레이어를 우클릭하고 '길드 또는 커뮤니티에 초대'를 누르세요. 길드나 커뮤니티를 고르면 이름을 입력하지 않아도 초대가 전달됩니다.",
	["Clic derecho: dejarla sin acción."] = "오른쪽 클릭: 동작 없음으로 두기.",
	["Clic derecho: opciones de esta guía"] = "오른쪽 클릭: 이 가이드 옵션",
	["Clic derecho: reiniciar, quitar o llevar a Mis planes."] = "오른쪽 클릭: 다시 시작, 삭제, 내 계획으로 보내기.",
	["Clic en Llévame: la flecha te lleva"] = "길 안내 클릭: 화살표가 안내합니다",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "마커 클릭: 정보 카드(변경, 공유, 삭제, 따라가기). Shift+클릭: 바로 따라가기. 다른 핀 오른쪽 클릭: 따라가거나 마커로 저장.",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "칸을 클릭해 마우스 아래 파티원에게 할 동작을 고르세요. 오른쪽 클릭하면 동작이 비워집니다. 변경 사항은 전투가 끝난 뒤 적용됩니다.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "하나를 클릭하면 Alfa 지도가 그곳으로 이동합니다. «계속»은 화살표와 경로를 켭니다.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "하나를 클릭하면 Alfa 지도가 그곳으로 이동합니다. «계속»은 화살표와 경로를 켜고, 발자국은 Alfa를 쓰는 사람과 공유합니다.",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "하나를 클릭하면 지도가 그곳으로 이동합니다. 지도 오른쪽 클릭: 새 마커.",
	["Clic o Esc para saltar"] = "클릭 또는 Esc로 건너뛰기",
