	["Clic: abre su página con sus misiones, jefes y entrada."] = "클릭: 퀘스트, 우두머리, 입구가 있는 페이지를 엽니다.",
	["Clic: abre tu plan para verlo o cambiarlo."] = "클릭: 계획을 열어 보거나 바꿉니다.",
