	["Clic: resalta lo que lleva."] = "클릭: 든 것을 강조합니다.",
	["Clic: seguir con la flecha"] = "클릭: 화살표로 따라가기",
	["Clic: un consejo. Clic derecho: mis opciones."] = "클릭: 조언. 오른쪽 클릭: 내 옵션.",
	["Clic: un consejo. Clic derecho: mis opciones. Arrástrame para moverme."] = "클릭: 조언. 오른쪽 클릭: 내 옵션. 끌어서 저를 옮기세요.",
	["Clic: un consejo. Clic derecho: «¿En qué te ayudo?» y mis opciones."] = "클릭: 조언. 오른쪽 클릭: 「무엇을 도와줄까?」와 내 설정.",
	["Clic: un consejo. Clic derecho: «¿En qué te ayudo?» y mis opciones. Arrástrame para moverme."] = "클릭: 조언. 오른쪽 클릭: 「무엇을 도와줄까?」와 내 설정. 끌어서 옮길 수 있어요.",
	["Clic: ver su diario en Alfa"] = "클릭: Alfa 도감 보기",
	["Clic: volver a ponerlo."] = "클릭: 다시 입히기.",
	["Clima"] = "날씨",
	["Clásico WoW"] = "WoW 클래식",
	["Clásico, el arte pintado del juego"] = "클래식, 게임의 그림 지도",
	["Cobra tus %d misiones listas"] = "완료한 퀘스트 %d개 제출",
	["Cobre, estaño, hierro, mitril y torio: así sube un minero, con plata y oro de vez en cuando."] = "구리, 주석, 철, 미스릴, 토륨. 광부는 이렇게 성장하고, 가끔 은과 금도 나와요.",
	["Cocina"] = "요리",
	["Cocina %d"] = "요리 %d",
	["Cocina %d/%d"] = "요리 %d/%d",
	["Cocina 10 lotes desde tu cola de cocina."] = "요리 대기열에서 10번 요리하세요.",
	["Cocina 100 piezas de pescado."] = "생선 요리 100개를 만드세요.",
	["Cocina junto al agua"] = "물가의 요리",
	["Cocina va de la mano con Pesca: tú pescas y tú cocinas."] = "요리는 낚시와 짝꿍이에요. 직접 낚고 직접 요리해요.",
	["Cocinando %d de %s"] = "요리 중 %d개: %s",
	["Cocinar el siguiente lote"] = "다음 묶음 요리",
	["Codorniz asada"] = "구운 메추라기",
	["Cofre"] = "상자",
	["Cofres, baúles y almejas que se abren."] = "열 수 있는 상자, 사물함, 조개입니다.",
	["Coleccionables"] = "수집품",
	["Coleccionista del agua"] = "물의 수집가",
