	["Color de clase"] = "직업 색상",
	["Colores de clase en los marcos"] = "프레임에 직업 색상",
	["Colores de clase en los marcos, un cuadro de información más útil, el probador mejorado, la siguiente parada en los vuelos y sin voces de error. Cada una se apaga abajo cuando quieras."] = "프레임에 직업 색상, 더 유용한 툴팁, 개선된 미리보기 창, 비행 중 다음 경유지, 오류 음성 끄기. 각각 아래에서 언제든 끌 수 있습니다.",
	["Colores para daltonismo"] = "색맹 친화 색상",
	["Columnas"] = "열 수",
	["Comando"] = "명령어",
	["Comandos de Ruta:"] = "경로 명령어:",
	["Combate"] = "전투",
	["Combate feral"] = "야성",
	["Combate feral para subir"] = "레벨업용 야성",
	["Combate para subir"] = "레벨업용 전투",
	["Combustión: tus hechizos de fuego hacen más críticos un rato."] = "발화: 잠시 화염 주문의 치명타가 늘어납니다.",
	["Combínala con Encantamiento para desencantar lo que coses y no uses."] = "마법부여와 함께 배우면 만든 옷 중 안 쓰는 걸 마력 추출할 수 있어요.",
	["Combínala con Herboristería: así recoges tú lo que necesitas."] = "약초 채집과 함께 배우세요. 필요한 걸 직접 모을 수 있어요.",
	["Combínala con Minería: casi todo lo que fabricas lleva metal."] = "채광과 함께 배우세요. 만드는 거의 모든 것에 금속이 들어가요.",
	["Combínalo con Sastrería: la tela te da objetos verdes para desencantar."] = "재봉술과 함께 배우세요. 천으로 만든 녹색 아이템을 마력 추출할 수 있어요.",
	["Come y bebe entre peleas: recuperas vida y maná mucho más rápido."] = "전투 사이에 먹고 마셔요. 생명력과 마나가 훨씬 빨리 회복돼요.",
	["Comentario"] = "의견",
	["Comentarios de la zona"] = "지역 이야기",
	["Comentarios del momento"] = "그때그때 한마디",
	["Comerciante"] = "상인",
	["Comerciante:"] = "상인:",
	["Comerciantes"] = "상인",
	["Comerciantes y viajes"] = "상인과 이동",
	["Comercio"] = "거래",
	["Comercio te dice qué vale más en la subasta que con el comerciante, y cuánto pedir."] = "거래에서 상인보다 경매장에서 더 비싼 것과 얼마를 받을지 알려 줘요.",
	["Comida que da aguante o fuerza extra, y comes mientras descansas."] = "체력이나 힘을 추가로 주는 음식으로, 쉬는 동안 먹습니다.",
	["Comida y agua"] = "음식과 물",
