	["Opcional"] = "선택",
	["Opcional: cómo la llamas"] = "선택: 부를 이름",
	["Opciones avanzadas"] = "고급 설정",
	["Orcos"] = "오크",
	["Orden"] = "순서",
	["Ordenar"] = "정렬",
	["Ordenar de derecha a izquierda"] = "오른쪽에서 왼쪽으로 정렬",
	["Ordenar por lo que aportó"] = "기여순",
	["Ordenar por nombre"] = "이름순",
	["Orgrim Martillo Maldito murió peleando junto a Thrall durante la liberación de un campo de internamiento."] = "오그림 둠해머는 수용소 해방 때 스랄과 함께 싸우다 죽었어요.",
	["Orgrim Martillo Maldito tomó el mando de la Horda y desarmó el Consejo de la Sombra de Gul'dan."] = "오그림 둠해머는 호드의 지휘권을 잡고 굴단의 어둠의 의회를 해체했어요.",
	["Orgrimmar"] = "오그리마",
	["Orgrimmar está tallada en un cañón, y cada pueblo de la Horda tiene su propio valle dentro de la ciudad."] = "오그리마는 협곡을 깎아 만들었고, 호드의 종족마다 도시 안에 자기 골짜기가 있어요.",
	["Orgrimmar lleva el nombre de Orgrim Martillo Maldito, el jefe de guerra que liberó a Thrall y le dejó su armadura y su martillo."] = "오그리마는 스랄을 해방하고 갑옷과 망치를 물려준 대족장 오그림 둠해머의 이름을 땄어요.",
	["Orillas de sombra difuminadas, como la luz de verdad."] = "실제 빛처럼 흐려진 그림자 가장자리.",
	["Oro"] = "골드",
	["Oro de hoy"] = "오늘의 골드",
	["Oro neto por sesión"] = "세션별 순수익 골드",
	["Oro para la montura"] = "탈것용 골드",
	["Oscurecer las orillas"] = "가장자리 어둡게",
	["Oso"] = "곰 변신",
	["Otra captura"] = "다른 낚은 것",
	["Otra cosa"] = "다른 이야기",
