	["Otras opciones"] = "기타 옵션",
	["Otras tierras"] = "다른 땅",
	["Otro"] = "기타",
	["Otro (%s)"] = "기타 (%s)",
	["Otro addon de bolsas está activo"] = "다른 가방 애드온이 켜져 있음",
	["Otro addon de pesca está activo"] = "다른 낚시 애드온 활성화됨",
	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "다른 낚시 애드온이 활성화되어 있습니다. 서로 충돌하지 않도록 Alfa 낚시는 일시 정지됩니다. 애드온 목록에서 둘 중 하나를 끄세요.",
	["Otro dato"] = "하나 더",
	["Otro golpe fuerte para tu rotación."] = "순환에 넣을 또 하나의 강한 공격.",
	["Otro golpe fuerte."] = "또 하나의 강한 공격.",
	["Otro trofeo para la manada. ¡Auuu!"] = "무리의 트로피가 또 하나. 아우우!",
	["Otros"] = "기타",
	["Otros addons pueden poner puntos de ruta"] = "다른 애드온의 경유지 설정 허용",
	["Otros caminos"] = "다른 길",
	["Otros jugadores"] = "다른 플레이어",
	["Oye, ¿a la tuya también le gustan las salchichas?"] = "저기, 당신 리아도 소시지 좋아해요?",
	["PNJ"] = "NPC",
	["PNJ %d"] = "NPC %d",
	["Paciencia de lobo"] = "늑대의 인내",
	["Paciencia: lo que se busca con calma, se encuentra."] = "인내해요. 차분히 찾으면 찾아져요.",
	["Paisaje"] = "풍경",
	["Paisaje de la manada"] = "무리의 풍경",
	["Paisaje y gráficos"] = "풍경과 그래픽",
	["Palabras de ánimo"] = "응원의 말",
	["Paladín"] = "성기사",
	["Pan de especias de Mulgore"] = "멀고어 향신료 빵",
	["Pan de maíz húmedo"] = "촉촉한 옥수수빵",
	["Pan de plátano suave"] = "부드러운 바나나빵",
	["Pan recién horneado"] = "갓 구운 빵",
	["Panel de estadísticas"] = "능력치 창",
	["Pantalla de película para capturas y paseos. Solo cambia cómo se ve: no da más FPS."] = "스크린샷과 구경을 위한 영화 같은 화면. 보이는 모습만 바꾸며 FPS는 오르지 않습니다.",
	["Pantalla gris al morir"] = "죽으면 회색 화면",
	["Pantalla limpia"] = "깔끔한 화면",
	["Pantalla limpia: solo lo esencial"] = "깔끔한 화면: 꼭 필요한 것만",
	["Para abandonar"] = "포기 대상",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "지도 키로 열려면 아래의 «지도 키로 Alfa 지도 열기»를 켜세요.",
	["Para adoptar, tu nivel debe pasar el suyo por 10 o más."] = "맡으려면 내 레벨이 상대보다 10 이상 높아야 해요.",
	["Para alguien de tu hermandad, agrega su rango."] = "같은 길드원이면 길드 등급을 추가합니다.",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "바람추적자 썬더란의 전설 검을 만들려면 화산 심장부의 가르와 남작 게돈이 떨어뜨리는 속박 두 개가 필요해요.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Alfa는 아이템마다 세 가지 방법을 비교합니다: 상인에게 팔기, 경매장에 올리기, 다른 것으로 바꾸기(아는 제조법이나 마력 추출로).",
	["Para cambiar de plano con la manada, primero deja que te vea en el mapa (ajustes de La Jauría)."] = "무리와 레이어를 바꾸려면 먼저 지도에서 나를 보이게 하세요(La Jauría 설정).",
	["Para capturas y paseos. No da más FPS."] = "스크린샷과 구경용. FPS는 오르지 않습니다.",
	["Para cerrar tu rato con todo cobrado"] = "보상을 모두 챙기며 마무리",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "군단을 막으려고 말퓨리온과 동료들이 영원의 샘을 파괴했어요. 그 폭발로 칼림도어의 중심이 가라앉았어요.",
	["Para comprar espacio, habla con un banquero."] = "공간을 사려면 은행원과 대화하세요.",
	["Para conservar"] = "남겨 둘 것",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "동부 왕국에서 칼림도어로 가려면 저습지의 메네실 항구에서 배를 타세요.",
	["Para depositar, habla con un banquero."] = "보관하려면 은행원과 대화하세요.",
	["Para empezar"] = "시작하려면",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "마법부여를 하려면 룬 마법막대가 필요하고, 차차 더 좋은 걸로 바꿔요.",
	["Para entregar"] = "제출할 것",
	["Para gastar"] = "사용 가능",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "%s님을 %s에 초대하려면: '길드 및 커뮤니티'를 열고 %s을(를) 고른 뒤 '구성원 초대'를 누르고 입력하세요: %s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "저습지에서 아라시 고원으로 가려면 탄돌 교각을 건너요. 하지만 검은무쇠를 조심하세요.",
	["Para las recetas de %s."] = "%s의 제조법용.",
	["Para leer mejor"] = "읽기 편하게",
	["Para llamar a la manada, deja que te vean en el mapa (La Jauría)."] = "무리를 부르려면 지도에 나를 보이게 하세요 (La Jauría).",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "태양샘에 닿으려고 아서스의 스컬지가 쿠엘탈라스와 수도 실버문을 휩쓸었어요.",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "고른 조건에 이 스타일의 빌드가 없어 Alfa가 가장 가까운 것을 씁니다.",
	["Para marcarlo, clic derecho en su retrato y elige la calavera."] = "표시하려면 초상화를 오른쪽 클릭하고 해골을 고르세요.",
	["Para mi nivel (±3)"] = "내 레벨용 (±3)",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "토륨을 캐려면 운고로 분화구와 여명의 설원에 광맥이 많아요.",
	["Para mí"] = "나에게 맞는 것",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "충돌하지 않도록 그 애드온이 켜져 있는 동안 Alfa는 가방을 바꾸지 않습니다. 그래도 여기에서 Alfa 창을 열 수 있습니다.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "실수로 옮기지 않도록. 잠그지 않으면 원하는 곳으로 끌어 옮길 수 있습니다.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "파티가 두 번 보이지 않게 합니다. 전투 중이 아닐 때 바뀝니다.",
	["Para proponer una cita, deja que la manada te vea en el mapa."] = "약속을 제안하려면 무리가 지도에서 당신을 볼 수 있게 해 주세요.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "서로 충돌하지 않도록 Alfa는 단축키를 가져가지 않고 설정도 바꾸지 않습니다. 애드온 목록(캐릭터 선택 화면)에서 둘 중 하나를 끄고 UI를 다시 불러오세요. Alfa를 남기면 다른 애드온에서 쓰던 키를 알아서 가져옵니다.",
	["Para que no dejes botín tirado por falta de espacio."] = "공간이 부족해 전리품을 두고 가는 일이 없도록 합니다.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "왼쪽 클릭으로 대상을 지정하고 싶은 분을 위한 설정입니다. 그 클릭의 치유 주문은 가운데 버튼으로 옮겨지고, 프리셋이 다시 적용됩니다.",
	["Para recoger ahora"] = "지금 받을 것",
	["Para subir de nivel"] = "레벨 업까지",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "혼자 레벨업할 땐 암흑 피해가 큰 도움이 돼요. 지속 피해 주문이 대신 일해 줘요.",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "낮은 레벨 천이 필요하면 서부 몰락지대의 데피아즈가 리넨과 양모를 잔뜩 떨어뜨려요.",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "엘프 검 쿠엘세라를 단련하려면 땅에 내려놓고 오닉시아가 그 위에 불을 뿜게 해야 해요.",
	["Para ti"] = "추천",
	["Para ti ahora"] = "지금 나를 위해",
	["Para tu %s"] = "내 %s",
	["Para tu habilidad conviene pescar en: %s."] = "내 숙련도에 좋은 낚시터: %s.",
	["Para tu nivel"] = "내 레벨용",
	["Para tu nivel (%d)"] = "내 레벨용 (%d)",
	["Para tu nivel ahora"] = "지금 내 레벨에 맞음",
	["Para tu personaje de nivel %d"] = "%d레벨 캐릭터를 위해",
	["Para vender"] = "팔 것",
	["Para vender, habla con un comerciante."] = "팔려면 상인과 대화하세요.",
	["Para ver cuánto procesador usa cada parte, escribe /console scriptProfile 1 y luego /reload. Hace el juego un poco más lento: cuando termines, /console scriptProfile 0 y /reload."] = "각 부분의 CPU 사용량을 보려면 /console scriptProfile 1 을 입력하고 /reload 하세요. 게임이 조금 느려져요. 끝나면 /console scriptProfile 0 하고 /reload.",
	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "무리의 굴을 보려면 지도에 나를 보이게 하세요.",
	["Para ver y romper los tótems enemigos."] = "적 토템을 보고 부수기 위해.",
	["Para verlas mejor"] = "더 잘 보이게",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "다시 쌓으려면 여관이나 마을에서 쉬세요(또는 접속을 종료하세요).",
	["Para: %s."] = "용도: %s.",
	["Parada"] = "무기 막기",
	["Parada %d de %d"] = "경유지 %d/%d",
	["Parar"] = "무기 막기",
	["Paras más golpes de otros guerreros y pícaros."] = "다른 전사와 도적의 공격을 더 많이 막아 냅니다.",
	["Paras más golpes."] = "무기 막기가 늘어납니다.",
	["Paras más golpes: recibes menos daño desde el principio."] = "무기 막기가 늘어 처음부터 받는 피해가 줄어듭니다.",
	["Paras un poco más."] = "무기 막기가 조금 늘어납니다.",
	["Paraste un golpe: el contraataque está listo."] = "공격을 무기 막기로 막았습니다. 반격을 쓸 수 있습니다.",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "공격을 무기 막기로 막았습니다. 반격을 쓸 수 있고 적의 무장을 해제합니다.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "공격을 무기로 막았습니다. 반격으로 적을 움직이지 못하게 합니다.",
	["Partes de Alfa apagadas"] = "꺼진 Alfa 부분",
	["Partes de Alfa de otra versión"] = "다른 버전의 Alfa 부분",
	["Partes de Alfa que no cargaron"] = "불러오지 못한 Alfa 부분",
	["Paré por el combate: lo demás sigue en el buzón."] = "전투 때문에 멈췄어요: 나머지는 우편함에 그대로 있어요.",
	["Pasa el ratón por cualquier cosa de Alfa y te digo para qué sirve. Pulsa tu tecla otra vez para terminar."] = "Alfa의 아무거나 위에 마우스를 올리면 무엇에 쓰는지 알려 줄게요. 끝내려면 키를 다시 누르세요.",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "아군에게 마우스를 올리고 클릭해서 치유하세요.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "파티원에게 마우스를 올리고 클릭하세요: 왼쪽 클릭은 %s, 오른쪽 클릭은 %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "질병을 퍼뜨립니다. 직업이 해제할 수 있으면 해제하세요.",
	["Pasa tu build a un amigo o usa el que te pasen."] = "친구에게 빌드를 보내거나 받은 빌드를 쓰세요.",
	["Pasar solo al siguiente paso"] = "다음 단계로 자동 진행",
	["Pasas tu vida a tu demonio para curarlo."] = "내 생명력을 악마에게 흘려 치유해요.",
