	["Pesca en los bancos de peces que flotan en el agua: dan más que pescar en cualquier lado."] = "물 위에 떠 있는 물고기 떼에서 낚시하세요. 아무 데서나 낚는 것보다 더 많이 나와요.",
	["Pesca en los bancos de peces que flotan en el agua: dan más y a veces sorpresas."] = "물 위에 떠 있는 물고기 떼에서 낚시하세요. 더 많이 나오고 가끔 깜짝 선물도 있어요.",
