	["Pide ayuda con %s."] = "%s 상대로 도움을 청해요.",
	["Pide ayuda con un élite o un raro: los lobos de tu zona reciben tu lugar y te avisa quién viene."] = "정예나 희귀 몹을 상대로 도움을 청하세요. 지역의 늑대들이 위치를 받고 누가 오는지 알려 줘요.",
	["Pide ayuda donde está."] = "있는 곳에서 도움을 청해요.",
