	["Piezas de cuero pesado que te enseñe tu instructor."] = "전문가가 가르쳐 주는 두꺼운 가죽 제품.",
	["Piezas de hierro y de acero que te enseñe tu instructor."] = "전문가가 가르쳐 주는 철과 강철 제품.",
	["Piezas de mitril: lo que tu instructor te enseña con barras de mitril."] = "미스릴 제품: 전문가가 미스릴 주괴로 가르쳐 주는 것.",
	["Piezas de torio: lo que tu instructor te enseña con barras de torio."] = "토륨 제품: 전문가가 토륨 주괴로 가르쳐 주는 것.",
	["Pinta del color de la clase el fondo del nombre en tu marco y en el del objetivo cuando es un jugador."] = "내 프레임과, 플레이어일 때의 대상 프레임에서 이름 배경을 직업 색상으로 칠합니다.",
	["Pizarra"] = "슬레이트",
