	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "어떤 특성을 왜 찍을지, 로테이션 도우미, 파티 피해량.",
	["Qué tan definidas se ven las sombras del mundo y de los personajes."] = "세상과 캐릭터의 그림자가 얼마나 또렷한지.",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Alfa가 고르는 퀘스트의 난이도 한도입니다(항상 지금 받을 수 있는 것 중에서).",
	["Qué tan grande escribe Lya en su globo. También con clic derecho sobre ella."] = "리아가 말풍선에 쓰는 글자 크기. 리아를 오른쪽 클릭해도 돼요.",
	["Qué tan grande se ve Lya."] = "Lya가 보이는 크기.",
	["Qué tan grande se ve cada casilla."] = "각 칸의 크기입니다.",
	["Qué tan grandes salen las que vienen después, comparadas con el ícono principal."] = "다음 기술이 큰 아이콘에 비해 얼마나 크게 나올지.",
	["Qué tan rápido se acerca y aleja la cámara."] = "카메라가 가까워지고 멀어지는 속도.",
	["Qué tanto se ve el ícono mientras no peleas."] = "전투 중이 아닐 때 아이콘이 보이는 정도.",
	["Qué te gustaría que Alfa hiciera, o hiciera mejor, y para qué te serviría."] = "Alfa가 해 주었으면 하는 일, 또는 더 잘했으면 하는 일과 그게 어떤 도움이 될지.",
