	["Revisar sola al entrar a una mazmorra"] = "던전에 들어가면 자동으로 점검",
	["Revisión rápida"] = "빠른 점검",
	["Revive a tu mascota caída. Úsalo fuera de combate."] = "쓰러진 야수를 되살려요. 전투 중이 아닐 때 쓰세요.",
	["Revive a un aliado caído. Úsalo fuera de combate."] = "쓰러진 아군을 되살려요. 전투 중이 아닐 때 쓰세요.",
	["Revive a un aliado en pleno combate. Tarda en volver a estar lista."] = "전투 중에 아군을 되살려요. 다시 쓰려면 시간이 걸려요.",
	["Revivir"] = "되살리기",
	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "야수의 왕 렉사르는 곰 미샤와 함께 잊혀진 땅의 길을 돌아다녀요.",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "반은 오크, 반은 오우거인 렉사르는 듀로타 건국을 도운 야수의 왕이에요. 곰 미샤가 늘 곁에 있어요.",
	["Reír"] = "웃기",
	["Ritmo: %s XP por hora; subes de nivel en %s."] = "속도: 시간당 경험치 %s, %s 후 레벨 업.",
	["Roba al enemigo sin que se dé cuenta. Hazlo en sigilo antes de atacar."] = "적이 모르게 훔쳐요. 공격하기 전에 은신 상태에서 하세요.",
	["Roble"] = "참나무",
	["Rocal es el gran bastión de la Horda en el sur de los Reinos del Este."] = "스토나드는 동부 왕국 남쪽에 있는 호드의 큰 거점이에요.",
	["Rocío de gloria de la mañana"] = "나팔꽃 이슬",
	["Rojo"] = "빨간색",
	["Rosa"] = "분홍",
	["Rueda abajo"] = "휠 아래로",
	["Rueda arriba"] = "휠 위로",
	["Rueda del ratón: acercar o alejar donde está el cursor. Arrastrar: mover el mapa (al soltar rápido sigue un poco). Doble clic: acercar."] = "마우스 휠: 커서 위치에서 확대/축소. 끌기: 지도 이동(빨리 놓으면 조금 더 미끄러집니다). 더블 클릭: 확대.",
	["Rueda: zoom  ·  Arrastra: mover  ·  Clic derecho: marcador  ·  Ctrl+clic: llévame"] = "휠: 확대/축소  ·  끌기: 이동  ·  오른쪽 클릭: 마커  ·  Ctrl+클릭: 안내",
	["Rugir"] = "포효",
	["Rut'theran es el muelle al pie del árbol; de ahí un portal te sube a Darnassus."] = "루테란은 나무 아래 부두예요. 거기서 차원문을 타고 다르나서스로 올라가요.",
	["Ruta"] = "경로",
	["Ruta %d/%d: %s"] = "경로 %d/%d: %s",
	["Ruta borrada"] = "경로 삭제됨",
	["Ruta en el minimapa"] = "미니맵 경로",
	["Ruta en marcha"] = "경로 진행 중",
	["Ruta importada"] = "가져온 경로",
	["Ruta lista en %s: %s"] = "%s에 경로 준비 완료: %s",
	["Rutas propias"] = "자체 경로",
	["Saca %d para la primera maestría (%s)."] = "첫 숙련 단계까지 %d마리 낚기 (%s).",
	["Saca 15 capturas seguidas sin que se te escape ninguna."] = "한 마리도 놓치지 않고 연속 15마리를 낚으세요.",
	["Saca 25 capturas de bancos de peces."] = "물고기 떼에서 25마리를 낚으세요.",
	["Saca tu primera captura del agua."] = "물에서 첫 물고기를 낚아 올리세요.",
	["Saca una captura en Tuercespina durante el concurso de pesca."] = "낚시 대회 동안 가시덤불 골짜기에서 한 마리를 낚으세요.",
	["Sacarla"] = "빼기",
	["Sacerdote"] = "사제",
	["Sagrado"] = "신성",
	["Sagrado para subir"] = "레벨업용 신성",
	["Sal a explorar"] = "탐험하러 가요",
	["Sal de combate y vuelve a intentarlo."] = "전투가 끝난 뒤 다시 시도하세요.",
	["Sal de tu grupo primero: el juego te pasa a la guarida de quien te invita."] = "먼저 파티를 나가세요. 게임은 초대한 사람의 굴로 옮겨 줘요.",
	["Sal de tu grupo primero: el juego te pasa al plano de quien te invita."] = "먼저 파티를 떠나세요. 게임은 초대한 사람의 레이어로 옮겨요.",
	["Salchichas que le diste"] = "준 소시지",
	["Sale de tu registro. Para hacerla otra vez tendrías que volver a pedirla."] = "퀘스트 목록에서 사라져요. 다시 하려면 다시 받아야 해요.",
	["Sale en aguas abiertas; los datos del juego no dicen dónde. Tu diario lo anota cuando lo saques."] = "탁 트인 물에서 나옵니다. 게임 데이터에는 위치가 없습니다. 낚으면 도감에 기록됩니다.",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "퀘스트 목록에서 사라집니다. 다시 하려면 퀘스트를 다시 받아야 합니다.",
	["Salidas de zona"] = "지역 출구",
	["Salir del grupo"] = "파티 나가기",
	["Salir del modo limpio"] = "깔끔 모드 끝내기",
	["Saltar"] = "건너뛰기",
	["Saltar la charla de una sola opción"] = "선택지가 하나뿐인 대화 건너뛰기",
	["Saltar las misiones grises"] = "회색 퀘스트 건너뛰기",
	["Saltarla"] = "건너뛰기",
	["Salud"] = "생명력",
	["Salud cada 5 s"] = "5초당 생명력",
	["Saludar"] = "손 흔들기",
	["Saludos al entrar"] = "접속할 때 인사",
	["Saludos y diálogos de los PNJ"] = "NPC 인사와 대사",
	["Sanación"] = "치유량",
	["Sanador"] = "치유 전담",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "13레벨부터 강한 출혈. 깊은 상처에 필요합니다.",
	["Sangrado fuerte; abre Heridas profundas."] = "강한 출혈. 깊은 상처를 엽니다.",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "냉혈: 다음 마무리 기술이 반드시 치명타로 들어갑니다.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "낙스라마스의 서리고룡 사피론은 스컬지가 일으키기 전에는 푸른용이었어요.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "살게라스는 판테온의 위대한 수호자였어요. 오랫동안 악마와 싸우다 창조물은 구할 수 없다고 결론 내리고 불타는 군단을 세웠어요.",
	["Sastrería"] = "재봉술",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "재봉술은 던전에서 나오는 재료로 옷을 만들고, 마법부여는 쓰지 않는 것을 분해해 장비를 강화합니다.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "재봉술과 마법부여: 장비를 항상 최신으로.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "카엘 다로우 섬의 스칼로맨스는 스컬지가 강령술을 가르치는 학교예요. 원래는 바로브 가문의 집이었어요.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "«표시한 것 포기»로 포기하며, 확인을 묻습니다.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "%d레벨에 열립니다. %d레벨 남았습니다. 그동안 경로를 따라가세요.",
	["Se abre al salir de combate."] = "전투가 끝나면 열립니다.",
	["Se abre al terminar %s."] = "%s 완료 후 열립니다.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "B로 엽니다. 보기 방식(모두 함께, 분류별, 가방별)을 고르고, 이름이나 레벨로 검색하고, 가방 막대에서 가방을 끌어 교체하세요.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "오늘, La Jauría, 근처 찾기, 백과사전에서 «…»로 잘리던 글자가 사라졌습니다.",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "«Alfa_Builds 애드온이 차단되었습니다…» 경고는 이제 없습니다. 특성 창, 클릭 시전, 유산 창은 이제 게임이 직접 열고, 마법책에서도 주문이 문제없이 시전됩니다.",
	["Se acabó tu XP descansada"] = "휴식 경험치가 다 떨어졌습니다",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "자신을 가속하고 번개를 씁니다. 차단하세요.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "자신을 가속합니다. 가능하면 차단하세요.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "정신 집중 발동: 다음 주문이 비용 없이 나갑니다.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "정신 집중 발동: 신비한 화살이 비용 없이 나갑니다.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "어둠의 무아지경 발동: 어둠의 화살이 즉시 시전됩니다.",
	["Se agregó el sonido %d a tu lista."] = "소리 %d을(를) 목록에 추가했습니다.",
	["Se aplica al salir de combate."] = "전투가 끝나면 적용됩니다.",
	["Se aprende con %s"] = "%s에게서 배움",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "이 캐릭터의 던전 진행 상황을 삭제합니다. 되돌릴 수 없습니다.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "이 캐릭터의 저장된 세션을 삭제합니다. 현재 세션은 계속 기록됩니다.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "이 캐릭터의 세션, 지역, 아이템 기록을 삭제합니다. 되돌릴 수 없습니다.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "모든 캐릭터의 마커 %d개를 삭제합니다. 되돌릴 수 없습니다.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "이 캐릭터의 %s 처치 기록, 완료 횟수, 기록된 전리품을 삭제합니다.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "이 서버와 진영의 저장된 경매장 가격을 삭제합니다. 제조법은 그대로 남습니다.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "저장된 모든 전투가 지워지며, 게임 측정기 창에서도 지워집니다.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "이 캐릭터의 세션, 도감, 업적, 목표를 지웁니다. 낚시 숙련도는 그대로입니다.",
	["Se carga al salir de combate"] = "전투가 끝나면 불러옵니다",
	["Se cerró el buzón antes de terminar."] = "끝나기 전에 우편함이 닫혔어요.",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "가격을 받기 전에 경매장이 닫혔습니다. 나중에 다시 시도하세요.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "블리자드 클릭 시전 창이 닫혔습니다. 다시 열려면 «클릭 시전 열기»를 누르세요.",
	["Se cumple al llegar a ese nivel."] = "그 레벨에 도달하면 달성됩니다.",
	["Se cura a sí mismo: interrumpe su curación."] = "자신을 치유합니다. 치유를 차단하세요.",
	["Se cura comiendo: mátenlo rápido."] = "먹으면서 자신을 치유합니다. 빨리 처치하세요.",
	["Se cura: interrúmpelo."] = "자신을 치유합니다. 차단하세요.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "%s의 모든 우두머리가 끝낸 것처럼 공개됩니다. 실수였다면 여기에서 진행도를 지울 수 있습니다.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "은행을 닫아 중지: %d개 보관, %d개 남음.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "전투가 시작되어 중지: %d개 보관, %d개 남음.",
	["Se enciende cuando el enemigo esquiva: pega fuerte y no se puede esquivar. Úsalo en cuanto brille."] = "적이 회피하면 활성화돼요. 강하게 때리고 회피할 수 없어요. 빛나면 바로 쓰세요.",
	["Se enciende tras bloquear, esquivar o parar. Barato y con mucha amenaza: el favorito del tanque."] = "막기, 회피, 무기 막기 후에 활성화돼요. 싸고 위협이 높아 방어 전담이 좋아해요.",
	["Se enfurece al final: guarden su mejor daño."] = "마지막에 격노합니다. 가장 강한 공격을 아껴 두세요.",
	["Se enfurece con poca vida: termínenlo rápido."] = "생명력이 낮으면 격노합니다. 빨리 마무리하세요.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "시간이 지날수록 분노해 더 세게 때립니다. 빨리 처치하세요.",
	["Se entrega con %s"] = "제출: %s",
	["Se entrega dentro"] = "안에서 제출",
	["Se escapó"] = "놓쳤어요",
	["Se fabrica"] = "제작",
	["Se marcan como chatarra"] = "잡동사니로 표시됨",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "멧돼지 스테이크가 먹고 싶네요. 그냥 그렇다고요.",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "물속에서 싸웁니다. 호흡 막대를 보고 필요하면 숨을 쉬러 올라오세요.",
	["Se pesca"] = "낚시",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "보호막을 두르고 기절시킵니다. 나머지 둘부터 처치하세요.",
	["Se puede al salir de combate."] = "전투가 끝나면 할 수 있습니다.",
	["Se puede anunciar al salir de combate."] = "전투가 끝나면 알릴 수 있습니다.",
	["Se puede enviar ahora: %s"] = "지금 보낼 수 있음: %s",
	["Se pueden conseguir"] = "얻을 수 있음",
	["Se pusieron %d ajustes. Algunas cosas se ven completas al recargar."] = "설정 %d개를 적용했어요. 어떤 것은 다시 불러오면 완전히 보여요.",
	["Se pusieron %d de %d opciones"] = "옵션 %d/%d개 적용됨",
	["Se queda en el modo limpio."] = "깔끔 모드를 유지합니다.",
	["Se quita %s de tu lista de compras."] = "%s을(를) 장보기 목록에서 지웠어요.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "목록에서 지웁니다. 다시 필요하면 문자열을 다시 가져오세요.",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "채집하며 기록한 지점과 채집 횟수를 지웁니다. 기본 제공 데이터베이스는 남습니다. 되돌릴 수 없습니다.",
	["Se quitan todas las metas. Tus objetos no se tocan."] = "목표를 모두 지워요. 아이템은 건드리지 않아요.",
	["Se quitó el sonido %d de tu lista."] = "소리 %d을(를) 목록에서 뺐습니다.",
	["Se saltan (no están en tu árbol): %s."] = "건너뜀(내 트리에 없음): %s.",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "방 가장자리로 순간이동합니다. 근접이라면 따라가세요.",
	["Se toma dentro de la mazmorra: ahí la verás."] = "던전 안에서 받습니다. 안에서 보입니다.",
	["Se ve completo al recargar."] = "다시 불러오면 완전히 보여요.",
	["Se ve después de reiniciar los gráficos."] = "그래픽을 다시 시작하면 보입니다.",
	["Se vende ahora"] = "지금 판매",
	["Se vende en"] = "판매처",
	["Se vende en %s cada uno."] = "개당 %s에 팔립니다.",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "무력화가 상대를 묶을 수 있어 놓치지 않습니다.",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "무력화가 상대를 묶을 수 있어, 도망가서 동료를 데려오는 적이 없습니다.",
	["Secundaria"] = "보조",
	["Secundaria [mano]"] = "보조장비",
	["Secundario: no cuenta en tus dos"] = "보조: 두 개에 포함되지 않아요",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "피의 갈증: 가장 강한 공격. 준비될 때마다 쓰세요.",
	["Seguimiento"] = "따라가기",
	["Seguir"] = "따라가기",
	["Seguir (flecha y ruta)"] = "따라가기 (화살표와 경로)",
	["Seguir a %s"] = "%s 님 따라가기",
	["Seguir con %s"] = "계속: %s",
	["Seguir el terreno"] = "지형 따라가기",
	["Seguir esta guía"] = "이 가이드 따라가기",
	["Seguir esta ruta"] = "이 경로 따라가기",
	["Seguir este build"] = "이 빌드 따라가기",
	["Seguir este plan"] = "이 계획 따라가기",
	["Seguir jugando"] = "계속 플레이",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "계속을 누르면 가이드와 화살표가 나오고, 잘 보이도록 이 창이 닫힙니다.",
	["Seguir por aquí"] = "이쪽으로 가기",
	["Seguir ruta"] = "경로 따라가기",
	["Seguir sola con la siguiente guía"] = "다음 가이드로 자동 진행",
	["Seguir un build de %s"] = "%s 빌드 따라가기",
	["Segundos junto a la barra"] = "바 옆에 초 표시",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "전설에 따르면 가시멧돼지는 위대한 멧돼지 반신 아가마간의 피에서 태어났어요. 그래서 거대한 가시덤불 속에 살아요.",
	["Seleccionar objetivo"] = "대상 지정",
	["Seleccionar para copiar"] = "선택해서 복사",
	["Seleccionar todo"] = "모두 선택",
	["Seleccionarlo"] = "대상 선택",
	["Sello"] = "문장",
	["Semilla de Tuercespina"] = "가시덤불 씨앗",
	["Semilla de arce"] = "단풍나무 씨앗",
	["Semilla de carpe"] = "서어나무 씨앗",
	["Semilla de fresno"] = "물푸레나무 씨앗",
	["Semilla de palo de hierro"] = "무쇠나무 씨앗",
	["Sencillo"] = "간단",
	["Sencillo: solo Hoy, Ruta, Mapa, Bolsas y Lya a la vista, y menos avisos. Completo: todo Alfa. Lo demás sigue funcionando."] = "간단: 오늘, 경로, 지도, 가방, 리아만 보이고 알림이 줄어요. 전체: Alfa 전부. 나머지는 계속 작동해요.",
	["Sepia"] = "세피아",
	["Servicio"] = "서비스",
	["Servicios"] = "시설",
	["Servicios en el minimapa"] = "미니맵에 시설",
	["Será una mejora más adelante"] = "나중에 향상이 됨",
	["Sesiones anteriores"] = "이전 세션",
	["Sesiones que guarda el diario"] = "일지에 저장할 세션 수",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "이 캐릭터의 세션, 도감, 업적, 목표. 되돌릴 수 없습니다.",
	["Sesión de pesca nueva."] = "새 낚시 세션.",
	["Señalar"] = "가리키기",
	["Señor de las aguas"] = "물의 군주",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "La Jauría의 창립자 Toxic이 근처에 있으면 Alfa가 알려 줘서 인사할 수 있어요.",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "잘 버티고 있다면 남는 분노로 영웅의 일격을 써서 위협 수준을 더 쌓으세요.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "일이 틀어지면 사라지는 기술로 전투에서 빠져나오세요. 너무 늦기 전에 쓰세요.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "무리의 누군가가 빌드를 주면 가져오세요. Alfa가 포인트 하나하나 안내합니다.",
	["Si alguien de tu grupo también trae Alfa, nuestras Lyas se saludan al juntarse y a veces platican. Es poquito y nunca en combate. Se apaga en mi página: «Lya y su manada»."] = "파티에 Alfa를 쓰는 사람이 있으면 우리 리아들이 만나서 인사하고 가끔 수다를 떨어요. 아주 조금, 전투 중엔 절대 안 해요. 제 페이지의 '리아와 리아의 무리'에서 끌 수 있어요.",
	["Si alguien de tu grupo también trae Alfa, sus Lyas se saludan y a veces platican. Poquito y nunca en combate."] = "파티에 Alfa를 쓰는 사람이 있으면 서로의 리아가 인사하고 가끔 수다를 떨어요. 아주 조금, 전투 중엔 절대 안 해요.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "도망치는 적은 죄수를 더 데려올 수 있습니다. 감속 기술로 막으세요.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "여관에서 소시지를 보면 하나만… 아니 두 개 남겨 줘요.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "거대한 승강기로 내려가 보면 왜 그런 이름인지 알게 돼요. 수백 개의 바위 기둥이 있거든요.",
	["Si casi todo lo que vas a entregar está en el pueblo de tu piedra y estás lejos, Lya te lo dice."] = "제출할 퀘스트가 거의 다 귀환석 마을에 있고 당신이 멀리 있으면, 리아가 알려 줘요.",
	["Si cierras tres veces el mismo tipo de consejo, Lya te pregunta si ya no quieres que te lo diga."] = "같은 종류의 조언을 세 번 닫으면, 리아가 더는 말하지 말지 물어봐요.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "이맘때 여관에 호박이 보이면 할로윈 축제예요. 여관주인이 «사탕 안 주면 장난칠 거야»에 사탕을 주고, 가끔 변장 의상도 줘요.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "이맘때 등불과 불꽃놀이가 보이면 달의 축제예요. 세상 곳곳의 장로를 찾아가면 저마다 주화를 줘요.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "2월에 도시에서 향수 냄새가 나면 «온누리에 사랑을»이에요. 사람들이 선물을 나눠 주고, 경비병도 선물을 받아요.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "뼈다귀를 찾으면 제 거예요. 약속이죠?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "무두질을 한다면 랩터, 코도, 고양잇과 짐승이 가득한 지역에서 가죽이 끝없이 나와요.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "사거리 밖에 있으면 프레임이 흐리게 보입니다.",
	["Si estás en combate, espera a que termine."] = "전투 중이면 전투가 끝날 때까지 기다려요.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "남을 위해 만들 땐 정직하게 받으세요. 다시 찾아오고 추천해 줘요.",
	["Si hay fiesta te lo digo al entrar. Y según la hora y la zona te cuento lo que pasa por ahí."] = "축제가 있으면 접속할 때 알려 줘요. 시간과 지역에 따라 주변에서 무슨 일이 있는지도 얘기해요.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "오늘 힘들면 내일은 될 거예요. 저는 여전히 곁에 있어요.",
	["Si juegas sin grupo, la ventana se esconde."] = "파티 없이 플레이하면 창이 숨겨집니다.",
	["Si la abandonas, pierdes la cadena: después sigue “%s”."] = "포기하면 연계 퀘스트가 끊겨요. 다음 퀘스트: «%s».",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "전투가 불리하면 소멸하고 다시 시작하세요.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "보상에 선택지가 여러 개면 직접 고르세요.",
	["Si la terminas"] = "끝내면",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "생명력이 절반 아래로 떨어지고 치유가 따라오지 못하면 최후의 저항을 쓰세요.",
	["Si le dices «Ya no» a un consejo, sale aquí para que puedas devolverlo cuando quieras."] = "조언에 '그만'이라고 하면 여기에 나와서, 언제든 다시 돌려놓을 수 있어요.",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "농장 닭에게 닭 감정 표현을 여러 번 하면 가끔 도움을 청해요... 그리고 이야기는 애완동물로 끝나요.",
	["Si levantas algo que se puede regalar y le sirve a un lobo conectado, Alfa te lo dice con «Regalárselo»."] = "선물할 수 있고 접속한 늑대에게 쓸모 있는 걸 주우면 Alfa가 '선물하기'로 알려 줘요.",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "내구도가 0%가 되면 망가져서 능력치가 사라집니다. 되도록 빨리 대장장이나 수리 상인에게 수리하세요.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "같은 진영 다른 종족과 확고한 동맹이 되면 그 탈것을 팔아 줘요. 오크에게 코도, 인간에게 밤표범이라니!",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "은빛 여명회 장신구를 끼고 있으면 역병지대 언데드가 돌을 떨어뜨려요. 평판과 증표로 바꿀 수 있어요.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "받은 것이 장비보다 좋으면 전투가 끝난 뒤 착용합니다.",
	["Si moviste los avisos y ya no los encuentras."] = "알림을 옮겼다가 찾을 수 없을 때 쓰세요.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "자주 죽는다면 '안정형' 스타일로 바꾸세요.",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "조용히 있고 싶으면 오른쪽 클릭으로 잠시 저를 조용히 시켜요.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "드루이드가 아니면 악령의 숲에서 나무구렁 굴을 지나 달의 숲에 가요.",
	["Si no eres tanque: con cuánta amenaza se pone amarilla."] = "방어 전담이 아니면: 위협이 얼마일 때 노랗게 될지.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "열린 가이드가 없으면 내 레벨에 추천하는 가이드를 엽니다.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "%s에서 길을 잃으면 당신은 지도를 읽고, 저는 흔적을 따라갈게요.",
	["Si peleas de lejos, quédate lejos de ella."] = "원거리라면 그녀에게서 떨어져 있으세요.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "혼자서 더 빨리 처치하고 싶다면 초기화할 골드가 생겼을 때 무기 전문으로 바꾸세요.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "원하면 Alfa를 쓰는 늑대들의 게임 지도에 내 캐릭터가 나타나고, 내 지도에도 그들이 나타납니다. 누가 어디 근처에 있는지 보이고, 클릭 한 번이면 화살표가 안내합니다. WoW 안의 캐릭터 위치일 뿐, 실제 위치는 절대 아닙니다. 파티는 항상 보입니다.",
	["Si sigues el consejo"] = "조언을 따르면",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "원수 윈저의 연계 퀘스트를 따라가면 스톰윈드에서 프레스터 부인의 정체를 밝혀내요.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "가라앉은 사원 이야기를 따라가면 늪에서 녹색용 이타리우스가 기다려요.",
	["Si sigues los consejos"] = "조언을 따르면",
	["Si sigues los consejos ganas %s"] = "조언을 따르면 %s 획득",
	["Si sueltan poco, no te desesperes. Pasa en toda buena caza."] = "조금밖에 안 나와도 실망 마요. 좋은 사냥엔 늘 있는 일이에요.",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "적이 다가오면 근접 공격을 쓰고 다시 거리를 벌리세요.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "생명력이 많이 떨어지면 방어 태세로 바꾸세요. 분노는 사라지지 않습니다.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "파티에 초대받으면 게임 버튼으로 수락하세요. 잠시 후 게임이 그 굴로 옮겨 줘요.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su plano al rato."] = "파티에 초대받으면 게임 버튼으로 수락하세요. 곧 그 사람 레이어로 옮겨져요.",
	["Si te llega equipo mejor que lo que llevas, te aviso con «Ponte esto» y un botón para ponértelo. Solo con tu clic, y nunca en combate."] = "지금 입은 것보다 좋은 장비를 얻으면 '이거 입어요'와 착용 버튼으로 알려 줘요. 클릭할 때만, 전투 중에는 절대 안 해요.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "붕대를 감다가 맞으면 끊겨요. 조금 떨어진 다음 쓰세요.",
	["Si te quedas sin lanzar"] = "던지지 않고 있으면",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "고기 한 조각 남으면, 여기 기쁘게 받아 줄 배가 있어요.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "시간이 부족하거나, 함께할 사람이나 도와줄 사람이 없어도 여정에서 Alfa와 Lya에게 기댈 수 있습니다.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "낚싯대에 미끼가 없으면 던지기 전에 키가 가진 것 중 최고(또는 선호 미끼)를 답니다.",
	["Si tu clase lo puede quitar, su marco se pinta del color del perjuicio y sale su ícono arriba a la derecha. Pasa el ratón y te digo con qué clic se quita; si ningún clic lo hace, elígelo en «Tus clics»."] = "내 직업이 해제할 수 있으면 틀이 그 약화 효과의 색이 되고 오른쪽 위에 아이콘이 나와요. 마우스를 올리면 어떤 클릭으로 해제하는지 알려 줘요. 그런 클릭이 없으면 '내 클릭'에서 고르세요.",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "대상이 플레이어이면 배경이 우호도 색 대신 그 직업 색상이 됩니다.",
	["Si tu plano se llena de cazadores, Lya te propone pasarte al de un lobo de la manada con su guarida abierta. Una vez cada 15 minutos."] = "내 레이어에 사냥꾼이 가득하면, 리아가 굴을 연 무리 늑대의 레이어로 옮기자고 해요. 15분에 한 번.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "등급이 허락하면 길드가 내고 나머지는 내 돈으로 냅니다.",
	["Si tú o tus personajes pueden"] = "나나 내 캐릭터가 할 수 있으면",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "언젠가 골드를 많이 벌면 어디에 쓸지 이미 알아요. 소시지요.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "적이 쫓아오면 도망치지 말고 방어 전담 쪽으로 가세요.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "적이 나에게 오면 방어 전담에게 데려가세요. 멀리 도망치지 마세요.",
	["Si un lobo de tu hermandad busca un objeto que llevas, Alfa le dice cuántos tienes. Solo eso y solo cuando pregunta."] = "길드 늑대가 내가 가진 아이템을 찾으면 Alfa가 몇 개 있는지 알려 줘요. 그것만, 물어볼 때만.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "같은 걸 파밍하는 플레이어로 붐비면 지역을 옮기세요. 그게 더 이득이에요.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "몬스터가 회피하면 바로 제압을 쓰세요(Alfa가 알려 줍니다).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "퀘스트가 어려우면 대화창에서 도움을 청해요. 무리와 함께라면 모든 게 가벼워요.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "경매가 팔리지 않으면 보증금을 잃어요. 터무니없는 가격은 매기지 마세요.",
	["Si vendes todo al comerciante"] = "모두 상인에게 팔면",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "다른 늑대를 보면 제 대신 인사해 줘요.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "골드샤이어나 멀고어에 알록달록한 천막이 보이면 다크문 축제가 온 거예요. 게임, 상품, 그리고 모아서 한 벌을 만드는 카드가 있어요.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "마법사와 여행한다면 수도로 가는 차원문을 부탁하세요. 길을 많이 아껴요.",
	["Siempre"] = "항상",
	["Siempre con cebo"] = "항상 미끼 달기",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "항상: 모든 퀘스트의 이야기와 새 지역마다 사실 하나를 들려줍니다. 가끔: 읽지 않고 받은 퀘스트의 이야기를, 매번은 아니고요. 요청할 때만: 오른쪽 클릭 후 «여기에 대해 들려줘». 이야기는 어느 쪽이든 저장됩니다.",
	["Siete días de caza contigo. Esto ya es costumbre, y me encanta."] = "함께 사냥한 지 7일. 이제 습관이 됐고, 난 그게 너무 좋아요.",
	["Sigilo"] = "은신",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "은신과 매복: 싸울 때를 직접 고르고 원할 때 사라집니다.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "대분리 수 세기 뒤, 비전 마법을 놓지 않은 명가가 추방됐어요. 그들은 바다를 건너 쿠엘탈라스를 세웠어요. 그들이 하이 엘프예요.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "수 세기 뒤 용아귀 오크들은 악마의 영혼으로 알렉스트라자를 가두고 호드를 위한 전투 용을 길렀어요.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "여전히 곁에 있지만 다음 시각까지 말하지 않습니다: %s.",
	["Sigue a tu lado, pero no habla por un rato."] = "여전히 곁에 있지만 잠시 말하지 않습니다.",
	["Sigue con los pasos de la guía"] = "가이드 단계대로 계속",
	["Sigue donde ibas"] = "이어서 하기",
	["Sigue la flecha."] = "화살표를 따라가세요.",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "화살표를 따라가세요. 경유지는 NPC별로 묶어 가장 짧은 순서입니다.",
	["Sigue subiendo: %d de %d"] = "계속 올리기: %d / %d",
	["Sigue tu guía"] = "가이드 따라가기",
	["Sigue: %s"] = "다음: %s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "다음: %s. 전투 전에 공략을 읽으세요.",
	["Sigues a %s"] = "%s 따라가는 중",
	["Sigues con tu equipo de pesca."] = "아직 낚시 장비를 입고 있습니다.",
	["Siguiendo"] = "따라가는 중",
	["Siguiendo a %s."] = "%s 님을 따라가는 중.",
	["Siguiendo el rastro"] = "흔적을 따라가는 중",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "%s 님의 흔적을 따라가는 중. 화살표가 그 위치까지 안내합니다.",
	["Siguiendo tu ruta de %s"] = "%s 경로 따라가는 중",
	["Siguiente"] = "다음",
	["Siguiente lugar"] = "다음 장소",
	["Siguiente parada:"] = "다음 경유지:",
	["Siguiente paso de la guía"] = "가이드 다음 단계",
	["Siguiente rango: %s"] = "다음 단계: %s",
	["Siguiente: %s (%d de %d)"] = "다음: %s (%d / %d)",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "추가한 소리를 파일 번호(FileDataID)로 음소거합니다: /alfa silenciar <번호>, 빼려면 /alfa silenciar quitar <번호>.",
	["Silenciar 1 hora"] = "1시간 동안 조용히",
	["Silenciar sonidos"] = "소리 음소거",
	["Silenciar un sonido por su número (FileDataID)"] = "번호(FileDataID)로 소리 음소거",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "실리더스는 안퀴라즈의 관문이에요. 그곳에서 실리시드와 퀴라지가 고대 신 쑨을 섬겨요.",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "채광이 없으면 광맥이, 약초채집이 없으면 약초가, 낚시가 없으면 물고기 떼가 보이지 않습니다. 보물은 항상 보입니다.",
	["Sin Pesca"] = "낚시 없음",
	["Sin XP descansada"] = "휴식 경험치 없음",
	["Sin acción"] = "동작 없음",
	["Sin activar"] = "꺼짐",
	["Sin aprender"] = "배우지 않음",
	["Sin aullido"] = "울음소리 끔",
	["Sin bloqueos y más claro"] = "차단 없이, 더 알기 쉽게",
	["Sin cadena"] = "연계 없음",
	["Sin cambiar de forma."] = "변신하지 않은 상태입니다.",
	["Sin cambios"] = "변화 없음",
	["Sin consejos para este jefe: vayan con calma y escuchen al tanque."] = "이 우두머리에 대한 팁이 없어요. 천천히, 방어 전담 말을 들으세요.",
	["Sin datos"] = "데이터 없음",
	["Sin demonio"] = "악마 없음",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "마우스를 올리지 않으면 바가 버튼을 숨기고 일어나는 일만 보여 줍니다.",
	["Sin encantar"] = "마법부여 안 됨",
	["Sin fuente conocida"] = "알려진 출처 없음",
	["Sin grupo"] = "파티 없음",
	["Sin historial todavía."] = "아직 기록이 없어요.",
	["Sin límite de tiempo"] = "시간 제한 없음",
	["Sin mascota"] = "소환수 없음",
	["Sin metas todavía"] = "아직 목표 없음",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "아직 목표가 없습니다. +를 눌러 정하세요: 물고기, 낚은 수, 시간, 가치.",
	["Sin metas todavía: ábrelo y agrégale una."] = "아직 목표가 없습니다. 열어서 하나 추가하세요.",
	["Sin munición"] = "탄약 없음",
	["Sin objeto"] = "아이템 없음",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "다른 캐릭터 없이 한 캐릭터는 29점까지 얻을 수 있습니다: 레벨업 3, 전문 기술 6, PvP 12, 모험 2, 던전과 공격대 6. 나머지는 다른 직업을 키워서 얻습니다.",
	["Sin precio todavía: escanea la subasta."] = "아직 가격 없음: 경매장을 스캔하세요.",
	["Sin precios"] = "가격 없음",
	["Sin precios todavía"] = "아직 가격 없음",
	["Sin profesión"] = "전문 기술 없음",
	["Sin sello"] = "문장 없음",
	["Sin tecla"] = "키 없음",
	["Sin tener una tecla abajo: lo prendes o lo apagas con su atajo, o aquí."] = "키를 누르고 있지 않아도 돼요. 단축키나 여기서 켜고 꺼요.",
	["Sin tinte"] = "색조 없음",
	["Sin ubicación"] = "위치 없음",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "지금은 위치 없음: 인스턴스 안이거나 지도 밖",
	["Sin veneno"] = "독 없음",
	["Sin zona"] = "지역 없음",
	["Sobre Lya"] = "Lya 소개",
	["Sobre tu compañero, este clic %s."] = "아군에게 이 클릭: %s.",
	["Solo %s"] = "%s 전용",
	["Solo al acabarse"] = "다 떨어졌을 때만",
	["Solo al moverte"] = "움직일 때만",
	["Solo buffs"] = "강화 효과만",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Alfa를 쓰고 공유에 동의한 사람과만 공유합니다. 결정은 내가 합니다.",
	["Solo cuando estás en grupo"] = "파티에 있을 때만",
	["Solo cuando te llame"] = "부를 때만",
	["Solo el botín que me sirve"] = "내가 쓸 수 있는 전리품만",
	["Solo ellos: tú no la tienes."] = "그들만 있어요. 나는 없어요.",
	["Solo en una fiesta del año"] = "연례 축제 기간에만",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "warcraft.wiki.gg와 Icy Veins에만 있음: 보상마다 필요한 점수(15, 25, 40, 55). 트리 단계별 비용은 어떤 출처에도 없습니다. 유산 창에서 확인하세요.",
	["Solo encontré %d misiones que te sirvan ahora."] = "지금 나에게 맞는 퀘스트를 %d개밖에 찾지 못했습니다.",
	["Solo hay que llevar el recado. ¡Fácil, como pedirme una salchicha!"] = "소식만 전하면 돼요. 저한테 소시지 달라는 것만큼 쉬워요!",
	["Solo importantes"] = "중요한 것만",
	["Solo la entrada"] = "입구만",
	["Solo las misiones de tu ruta"] = "경로의 퀘스트만",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "받을 수 있는 것만: 내 진영, 종족, 직업, 레벨에 맞고 아직 하지 않은 것.",
	["Solo lo de mi papel"] = "내 역할만",
	["Solo lo esencial a la vista. Las barras y retratos se esconden al terminar el combate."] = "꼭 필요한 것만 보여요. 행동 단축바와 초상화는 전투가 끝나면 숨어요.",
	["Solo lo esencial a la vista. Pulsa tu tecla otra vez para ver todo."] = "꼭 필요한 것만 보여요. 키를 다시 누르면 전부 보여요.",
	["Solo lo esencial a la vista: Hoy, Ruta, Mapa, Bolsas y Lya, y menos avisos. Lo demás sigue ahí cuando lo busques."] = "꼭 필요한 것만 표시: 오늘, 경로, 지도, 가방, 리아, 그리고 알림은 적게. 나머지는 찾으면 그대로 있어요.",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "내 직업이 쓸 수 있고 내 전문화에 맞는 것만.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "지금 내 캐릭터가 쓸 수 있는 것만: 직업, 방어구, 무기, 레벨, 전문 기술.",
	["Solo lo que ya puedes recolectar"] = "지금 채집할 수 있는 것만",
	["Solo los de la zona donde estás."] = "지금 있는 지역의 것만.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "내 전문 기술에 해당하는 것만, 세계 지도와 미니맵에.",
	["Solo los graves"] = "위험만",
	["Solo los que me apuntan a mí"] = "나를 노리는 것만",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "경험치 퀘스트만, 주변에서 가장 좋은 것으로 세 차례에 나눠서.",
	["Solo para %s."] = "%s 전용.",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "보기만 하는 화면입니다. 현재 단계는 바뀌지 않습니다. 현재 단계를 마치면 Alfa가 알아서 넘어갑니다.",
	["Solo peleas de al menos"] = "최소 전투 시간",
	["Solo pide tela: guarda la que te sale de los enemigos y sube mientras viajas."] = "천만 필요해요. 적이 떨어뜨린 천을 모아 여행하며 올리세요.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "주 전문 기술은 한 번에 두 개까지만 배울 수 있고, 보조 전문 기술은 제한이 없습니다. 도시의 상급자에게 배웁니다.",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "초대할 수 있는 곳만 표시되며, Alfa가 누구를 초대했는지 대화창에 알려 줍니다. La Jauría > 초대에서 끌 수 있습니다.",
	["Solo se admite la versión 1 de la cadena de escala."] = "척도 문자열은 버전 1만 지원합니다.",
	["Solo si falta"] = "없을 때만",
	["Solo si le pido"] = "요청할 때만",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "HDR 모니터와 Windows HDR(설정 > 디스플레이)이 켜져 있어야만 작동합니다. 아니면 꺼 두세요. 색이 바래 보입니다.",
	["Solo su atajo"] = "단축키로만",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "그래픽만 바꿉니다. 카메라, 마우스, 인터페이스는 절대 건드리지 않습니다. «되돌리기»는 마지막으로 적용한 프리셋 전의 값으로 돌아갑니다.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "내 파티와 Alfa를 쓰며 공유에 동의한 사람만.",
	["Solo tú"] = "나만",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "나, 파티, 마커, 가이드의 다음 단계만.",
	["Solo él ve tu nivel, tu zona y tu misión de ahora."] = "그 늑대만 내 레벨, 지역, 지금 퀘스트를 봐요.",
	["Sombra"] = "암흑",
	["Sombra para subir"] = "레벨업용 암흑",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "모서리, 주름, 사물 아래의 부드러운 그늘. 모든 것에 입체감을 줍니다.",
	["Sombras"] = "그림자",
	["Sombras con bordes más finos. Usa más memoria de video."] = "가장자리가 더 섬세한 그림자. 비디오 메모리를 더 씁니다.",
	["Sombras suaves"] = "부드러운 그림자",
	["Son %s más que venderlo todo al comerciante."] = "모두 상인에게 파는 것보다 %s 더 많습니다.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "계정 점수입니다. 어느 캐릭터로든 유산 도전(Forever 업적)으로 얻고, 각 캐릭터는 자기 트리에 따로 씁니다.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "함께 싸우는 드워프 셋입니다. 하나는 멀리서 쏘고, 하나는 아주 빠르고, 하나는 방패로 몸을 지킵니다. 하나씩 처치하세요.",
	["Sonido"] = "소리",
	["Sonido con el juego en segundo plano"] = "게임이 백그라운드일 때 소리",
	["Sonido de los avisos"] = "알림 소리",
	["Sonido en los avisos urgentes"] = "긴급 알림 소리",
	["Sonido suave"] = "부드러운 소리",
	["Sonido y avisos"] = "소리와 알림",
	["Sonidos de gestos"] = "감정 표현 소리",
	["Sonidos de mascotas"] = "소환수 소리",
	["Sonidos en tu lista (%d): %s"] = "내 목록의 소리 (%d): %s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "부드러운 게임 소리: 음성이나 반복되는 소리 없음.",
	["Sorpresa"] = "깜짝 선물",
	["Sorpresas y cofres"] = "깜짝 선물과 상자",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "나는 알파의 믿음직한 늑대 리아예요. 함께 다니며 장소마다 이야기를 들려주고 Alfa의 모든 걸 도와요. 그리고 소시지를 정말 좋아해요.",
	["Spot aquí"] = "여기 파밍 장소",
	["Spot de farmeo"] = "파밍 장소",
	["Spot de farmeo de %s"] = "%s의 파밍 장소",
	["Spots de farmeo"] = "파밍 장소",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "스트롬의 후계자 스트롬가드는 간신히 버티고 있어요. 트롤, 오우거, 비밀결사단이 폐허를 두고 싸워요.",
	["Su arpón envenena: quita el veneno si puedes."] = "작살에 독이 있습니다. 가능하면 독을 해제하세요.",
	["Su botín está por descubrir"] = "전리품 미발견",
	["Su electricidad salta de un jugador a otro: sepárense."] = "전기가 플레이어 사이를 튀어 다닙니다. 흩어지세요.",
	["Su ficha"] = "정보 보기",
	["Su final no alcanzó a guardarse."] = "결말이 저장되지 못했습니다.",
	["Su grupo está lleno o no puede invitar."] = "파티가 가득 찼거나 초대할 수 없어요.",
	["Su guarida ya no está abierta."] = "굴이 더는 열려 있지 않아요.",
	["Su mordida envenena: quita el veneno si puedes."] = "물면 독에 걸립니다. 가능하면 독을 해제하세요.",
	["Su nombre ya está en el correo: pon %s y envíalo."] = "이름은 이미 우편에 들어 있어요. %s을(를) 넣고 보내세요.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "골드와 보상은 이미 내 것입니다. 제출만 하면 됩니다.",
	["Su plano está lleno de gente. Si le abres tu guarida, Alfa lo invita a tu grupo y sale solo al llegar."] = "그쪽 레이어가 붐벼요. 굴을 열면 Alfa가 파티에 초대하고, 도착하면 떠나요.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "번개가 플레이어에서 플레이어로 튀어 다닙니다. 모두 붙어 서 있지 마세요.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "번개가 플레이어 사이를 튀어 다닙니다. 조금씩 흩어지세요.",
	["Suave"] = "부드럽게",
	["Subasta"] = "경매",
	["Subasta:"] = "경매:",
	["Subastador"] = "경매인",
	["Subastadores"] = "경매인",
	["Subastar"] = "경매",
	["Subastar %d"] = "경매 %d",
	["Sube %d nivel"] = "레벨 %d 올리기",
	["Sube %d niveles"] = "레벨 %d 올리기",
	["Sube al nivel"] = "레벨 달성",
	["Sube al nivel %d"] = "%d레벨 달성",
	["Sube al nivel %d: te falta %d%%"] = "%d레벨: %d%% 남음",
	["Sube al nivel %d: te faltan %s de experiencia"] = "%d레벨: 경험치 %s 남음",
	["Sube hasta %d con los pasos de abajo."] = "아래 단계대로 %d까지 올리세요.",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "효과음을 키우고 음악과 배경음을 줄여 찰방 소리가 들리게 합니다. 끝나면 모두 원래대로 돌아갑니다.",
	["Sube tu profesión o junta sus materiales donde más hay."] = "전문 기술을 올리거나 재료가 가장 많은 곳에서 모으세요.",
	["Sube tus oficios con lo que tienes cerca."] = "가까운 것으로 전문 기술을 올리세요.",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "아드레날린 촉진: 기력이 훨씬 빨리 회복됩니다.",
	["Subir"] = "위로",
	["Subir %s"] = "%s 레벨",
	["Subir %s a %d"] = "%s 숙련도 올리기: %d",
	["Subir cocina y pesca juntas"] = "요리와 낚시 함께 올리기",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "방어 전담으로 레벨업: 무기 전문보다 느리지만 거의 죽지 않고, 몬스터 여러 마리를 한꺼번에 끌며, 어떤 던전이든 방어 전담을 할 준비가 됩니다.",
	["Subir de nivel"] = "레벨 올리기",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "레벨업, 전문 기술, 골드 벌기, 던전: 두 번 클릭하면 Alfa가 안내합니다.",
	["Subir de nivel, profesiones, oro o mazmorras."] = "레벨업, 전문 기술, 골드, 던전.",
	["Subir el sonido al pescar"] = "낚시 중 소리 키우기",
	["Subir rápido"] = "빠른 레벨 업",
	["Subir solo"] = "혼자 레벨업",
	["Subir una profesión"] = "전문 기술 숙련도 올리기",
	["Succionar vida: daño con el tiempo que te cura."] = "생명력 착취: 생명력을 회복시키는 지속 피해.",
	["Suelta"] = "떨어뜨림",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "지금 던진 것을 거두고 장비나 미끼 없이 다시 던집니다.",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "커서에 들고 있는 것을 내려놓고 다시 시도하세요.",
	["Suelta una carta que empieza una misión: revisa su botín."] = "퀘스트를 시작하는 편지를 떨어뜨립니다. 전리품을 확인하세요.",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "앞쪽 문을 여는 열쇠를 떨어뜨립니다. 누군가 꼭 주워야 합니다.",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "주변에 질병 구름을 뿜습니다. 질병을 해제하세요.",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "주변에 불의 고리를 퍼뜨립니다. 원거리라면 떨어져 있으세요.",
	["Suena ahora, aunque el aullido esté apagado."] = "울음소리가 꺼져 있어도 지금 재생합니다.",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "소시지 산 꿈을 꿔요... 그 꼭대기에 행복한 제가 있어요.",
	["Sugerida para ti: %s"] = "추천: %s",
	["Sugerir la piedra de hogar"] = "귀환석 제안하기",
	["Sugerir qué guardar"] = "은행에 맡길 것 추천",
	["Sugerir qué vender"] = "팔 것 추천",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "직업에 맞는 Alfa 우선순위로 제안합니다. 끄면 게임이 Alfa가 읽을 수 있는 제안을 줄 때 블리자드 전투 보조를 씁니다. 전투 중에는 Forever가 이를 숨기므로 Alfa 것을 씁니다.",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "설퍼라스는 라그나로스의 망치예요. 그 눈으로 가장 용감한 이들이 전설 무기를 만들 수 있어요.",
	["Suma tus sesiones de hoy con este personaje."] = "이 캐릭터의 오늘 세션을 합산합니다.",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "«이 아이템 얻기»를 현재 계획(또는 새 계획)에 추가합니다.",
	["Supervivencia"] = "생존",
	["Supervivencia para subir"] = "레벨업용 생존",
	["Sus antojos y salchichas"] = "먹고 싶은 것과 소시지",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "어둠의 화살이 아주 아픕니다. 차단하세요.",
	["Sus cariñitos"] = "리아의 다정한 말",
	["Sus consejos"] = "Lya의 조언",
	["Sus consejos te esperan en Alfa."] = "Alfa에서 공략을 확인하세요.",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "우두머리, 전리품, 퀘스트, 가는 방법.",
	["Sus misiones dan"] = "퀘스트 보상",
	["Sus rayos saltan entre jugadores: sepárense."] = "번개가 플레이어 사이를 튀어 다닙니다. 흩어지세요.",
	["Susurrar"] = "귓속말",
	["Sutileza"] = "잠행",
	["Sutileza para subir"] = "레벨업용 잠행",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "실바나스는 알레리아와 베리사 윈드러너의 자매였어요. 지금은 단호하게 포세이큰을 이끌어요.",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "실바나스는 언더시티 왕실 지구에서 바리마트라스를 곁에 두고 손님을 맞아요.",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "실바나스에게는 자매가 둘 있어요. 어둠의 문 너머로 간 알레리아와, 마법사 로닌과 결혼한 베리사예요.",
	["Sábado"] = "토요일",
	["Sí"] = "예",
	["Sí, que la manada me vea"] = "예, 무리가 나를 보게 할게요",
	["Sí, que me vean"] = "예, 보게 할게요",
	["Sí, sígueme diciendo"] = "네, 계속 알려 줘요",
	["Sí, ya la hice"] = "네, 해 봤어요",
	["Sí: Alfa, Clásico WoW o Cristal, con tu color. También puede vestir el chat, el minimapa y las barras."] = "네: Alfa, 클래식 WoW, 크리스털에 원하는 색으로. 채팅, 미니맵, 바도 꾸밀 수 있어요.",
	["Sí: con /alfa limpia, o con tu tecla de pantalla limpia, escondo el chat, el minimapa y lo demás que elijas. Otra vez y vuelve todo."] = "네. /alfa limpia나 깔끔한 화면 키로 대화창, 미니맵, 고른 것들을 숨겨요. 한 번 더 하면 다 돌아와요.",
	["Sí: con el modo foco, en mazmorras y en combate me hago chiquita y me callo. Al terminar vuelvo. Está en mis ajustes."] = "네. 집중 모드면 던전과 전투 중에는 작고 조용해져요. 끝나면 돌아와요. 내 설정에 있어요.",
	["Sí: en Ajustes > Estilo y sonido elige «Sencillo» en «Cómo ves Alfa». Dejo a la vista solo lo esencial y te aviso menos."] = "네. 설정 > 스타일과 소리의 'Alfa를 보는 방식'에서 '간단'을 고르세요. 꼭 필요한 것만 보여 주고 알림도 줄일게요.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya» y otra a «Lo que te ofrece Lya», que hace lo de su botón."] = "네: 게임 단축키의 Alfa 항목에서 「리아에게 묻기」에 키 하나, 리아 버튼과 같은 일을 하는 「리아의 제안」에 또 하나를 지정하세요.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya»."] = "네: 게임 단축키 설정의 Alfa 항목에서 「리아에게 묻기」에 키를 지정하세요.",
	["Sí: en «Mentor», pulsa «Adoptar» junto a un lobo 10 niveles menor. Si acepta, ves cómo va y te aviso si se atora."] = "네. '멘토'에서 10레벨 낮은 늑대 옆의 '맡기'를 누르세요. 수락하면 어떻게 지내는지 보고, 막히면 알려 줄게요.",
	["Sí: escribe /alfa nota y tu texto, o usa «Nota aquí» en La Jauría. Sale en tu mapa donde estás; un clic y la flecha te lleva."] = "네: /alfa nota와 내용을 입력하거나 La Jauría의 '여기 메모'를 쓰세요. 서 있는 곳에 지도 메모가 생기고, 클릭하면 화살표가 안내해요.",
	["Sí: sale «[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo. Solo, te sale a ti."] = "네: 파티 채팅에 「[퀘스트] 반납 가능」과 「퀘스트 완료!」가 나와요. 혼자일 때는 나만 봐요.",
	["Símbolo de reyes"] = "왕의 징표",
	["Tabardo"] = "휘장",
	["Talentos"] = "특성",
	["Talentos de %s"] = "%s 특성",
	["Talentos te dice cuál sigue."] = "다음 순서는 특성에서 알려 줍니다.",
	["Talentos y combate"] = "특성과 전투",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "특성: 지금 찍을 것과 내 빌드 (/alfa builds aplicar | equipo | compartir)",
	["Tamaño"] = "크기",
	["Tamaño de la barra"] = "바 크기",
	["Tamaño de las casillas"] = "칸 크기",
	["Tamaño de las que siguen"] = "다음 기술 크기",
	["Tamaño de lo que atraviesa"] = "통과하는 사물 크기",
	["Tamaño de su letra"] = "글자 크기",
	["Tamaño del ícono"] = "아이콘 크기",
	["Tamaño en el mapa"] = "지도 크기",
	["Tamaño en el minimapa"] = "미니맵 크기",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "/alfa dps로도 열 수 있습니다. 전투 중에 계속 보이도록 Esc로 닫히지 않습니다.",
	["También con /alfa limpia."] = "/alfa limpia로도 돼요.",
	["También cuando el juego hace brillar otra habilidad"] = "게임이 다른 기술을 빛나게 할 때도",
	["También dentro de cuevas, criptas y edificios."] = "동굴, 납골당, 건물 안에서도.",
	["También el de venenos, sangrados y efectos que duran."] = "독, 출혈, 지속 효과의 피해도.",
	["También en el minimapa"] = "미니맵에도",
	["También en montura"] = "탈것을 탄 상태에서도",
	["También está en el menú de opciones del juego."] = "게임 설정 메뉴에도 있습니다.",
	["También fuera de combate"] = "전투 중이 아닐 때도",
	["También las de las mascotas de enemigos."] = "적 소환수의 것도.",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "가이드에 없는 퀘스트도 처리합니다(가이드 퀘스트는 \"가이드 퀘스트 수락\"이 맡습니다). 회색 퀘스트는 받지 않고, 골드, 화폐, 전문 기술 재료가 필요한 퀘스트는 제출하지 않으며, 보상이 여러 개면 직접 고릅니다. 직접 하려면 Shift를 누르고 있으세요.",
	["También las que no son de tu guía"] = "가이드에 없는 퀘스트도",
	["También tu foco"] = "주시 대상도",
	["Tanque"] = "방어 전담",
	["Tanque de amenaza"] = "위협 수준 방어 전담",
	["Tanque de escudo"] = "방패 방어 전담",
	["Tanque en apuros"] = "위기의 방어 전담",
	["Tanque muralla"] = "철벽 방어 전담",
	["Tanqueas"] = "방어 전담",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "던홀드의 인간 소녀 타레사 폭스턴은 스랄의 친구였고, 그의 탈출을 도왔어요.",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "레벨 업 시 새 기술 카드",
	["Tauren"] = "타우렌",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "%s 님에게 메시지가 담긴 귓속말을 열었습니다. 확인하고 Enter를 눌러 보내세요.",
	["Te acompaña"] = "함께해요",
	["Te avisa al momento de %s."] = "%s 기술을 쓸 때를 바로 알려 줍니다.",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "기술이 빛나는 것처럼 지금 내 직업이 활용할 것이 있으면 알려 줍니다.",
	["Te aviso con «Regalárselo»: abre el comercio si está a tu lado o te deja su nombre en el correo. Necesitan compartir su clase y nivel."] = "'선물하기'로 알려 줄게요. 옆에 있으면 거래 창을 열고, 아니면 우편에 이름을 넣어 줘요. 상대가 직업과 레벨을 공유해야 해요.",
	["Te conviertes en felino: mucho daño cuerpo a cuerpo y puedes acechar."] = "표범으로 변해요. 근접 피해가 크고 숨어 다닐 수 있어요.",
	["Te conviertes en foca: nadas rápido y respiras bajo el agua."] = "바다표범으로 변해요. 빠르게 헤엄치고 물속에서 숨 쉴 수 있어요.",
	["Te conviertes en guepardo y corres más rápido. Solo al aire libre."] = "치타로 변해 더 빨리 달려요. 야외에서만.",
	["Te conviertes en lobo y corres más rápido. ¡Como yo!"] = "늑대로 변해 더 빨리 달려요. 저처럼요!",
	["Te conviertes en oso: más armadura y más vida. Para tanquear y aguantar."] = "곰으로 변해요. 방어도와 생명력이 늘어요. 방어 전담과 버티기용.",
	["Te cura toda la vida a cambio de tu maná. Guárdalo para una emergencia."] = "마나를 대가로 생명력을 모두 회복해요. 위급할 때를 위해 아껴 두세요.",
	["Te da %s."] = "얻는 것: %s.",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "반복하지 않고 짧은 조언과 응원을 건넵니다. 각 대사는 최대 세 번까지 나옵니다. 클릭하면 조언을 하나 받고, 오른쪽 클릭하면 옵션을 엽니다.",
	["Te da ira a cambio de un poco de vida. Úsala para empezar una pelea con ira."] = "생명력을 조금 써서 분노를 얻어요. 분노를 갖고 전투를 시작할 때 쓰세요.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "전투력을 줍니다. 모든 공격이 더 세집니다. 전사는 방패 막기 수치도 올라갑니다.",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "La Jauría의 올인원 애드온 Alfa에 오신 것을 환영합니다.",
	["Te dice qué comprar a tu nivel y te lleva al vendedor de comida más cercano. El agua, solo si usas maná."] = "내 레벨에 맞는 살 것을 알려 주고 가장 가까운 음식 상인에게 데려가요. 물은 마나를 쓸 때만.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "곧 망가질 장비를 알려 줘서 제때 수리할 수 있게 합니다.",
	["Te enseña %s."] = "배우는 것: %s.",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "낚시와 숙련 단계를 가르칩니다. 기본 낚싯대도 팝니다.",
	["Te falta"] = "없음",
	["Te falta %s"] = "%s 필요",
	["Te falta 1 nivel para el 60"] = "60까지 1레벨 남음",
	["Te falta 1 nivel para tomarla."] = "받으려면 1레벨 더 필요합니다.",
	["Te falta 1 paso"] = "1단계 남음",
	["Te falta 1 rincón."] = "남은 구석 1곳.",
	["Te falta Aspecto del halcón: más poder a distancia."] = "매의 상 없음: 원거리 전투력 증가.",
	["Te falta Aura de disparo certero: más poder a distancia para tu grupo."] = "정조준 오라 없음: 파티의 원거리 전투력이 오릅니다.",
	["Te falta Bendición de poderío: más poder de ataque."] = "힘의 축복 없음: 전투력 증가.",
	["Te falta Escudo de relámpagos."] = "번개 보호막 없음.",
	["Te falta Escudo sagrado: bloqueas más."] = "신성한 방패 없음: 방패 막기 증가.",
	["Te falta Espinas."] = "가시 없음.",
	["Te falta Fuego interior: más armadura."] = "내면의 열정 없음: 방어도 증가.",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "전투의 외침 없음: 나와 파티의 전투력 증가.",
	["Te falta Intelecto Arcano: más maná."] = "신비한 지능 없음: 마나 증가.",
	["Te falta Marca de lo Salvaje."] = "야생의 징표 없음.",
	["Te falta Palabra de poder: entereza: más vida."] = "신의 권능: 인내 없음. 생명력 증가.",
	["Te falta aprender la receta."] = "요리법을 아직 배우지 않았습니다.",
	["Te falta el tótem de Fuerza de la tierra: más fuerza."] = "대지력 토템 없음: 힘이 오릅니다.",
	["Te falta este vuelo: háblale al maestro de vuelo para aprenderlo."] = "이 비행 경로가 없어요. 비행 조련사와 대화해서 배우세요.",
	["Te falta ira: Enfurecer te la da."] = "분노 부족: 격노로 분노를 얻으세요.",
	["Te falta ira: Ira sangrienta te la da gratis."] = "분노가 부족합니다. 피의 분노로 공짜로 얻으세요.",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "분노 부족: 이 기술은 공격을 받을 때 분노를 줍니다.",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "어둠의 형상 없음: 암흑 피해가 늘고 받는 피해가 줄어듭니다.",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "달빛야수 변신 없음: 주문 피해가 늘어납니다.",
	["Te falta la profesión"] = "전문 기술 필요",
	["Te falta reputación"] = "평판 부족",
	["Te falta tu armadura demoníaca."] = "악마의 갑옷이 없습니다.",
	["Te falta tu armadura: ponte una."] = "갑옷 주문이 없습니다. 하나 거세요.",
	["Te falta un aspecto: el del halcón da más poder a distancia."] = "상 없음: 매의 상은 원거리 전투력을 높입니다.",
	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "상 없음: 원숭이의 상은 회피를 돕습니다.",
	["Te falta una bendición: Poderío da más poder de ataque."] = "축복 없음: 힘의 축복은 전투력을 높입니다.",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "축복 없음: 지혜의 축복은 마나를 돌려줍니다.",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "축복 없음: 성역의 축복은 받는 피해를 줄입니다.",
	["Te faltan %d de %d materiales"] = "재료 %d/%d개 부족",
	["Te faltan %d niveles para tomarla."] = "받으려면 %d레벨 더 필요합니다.",
	["Te faltan %d pasos"] = "%d단계 남음",
	["Te faltan %d rincones."] = "남은 구석 %d곳.",
	["Te faltan %s"] = "부족: %s",
	["Te faltan %s XP para el nivel %d"] = "%s 경험치 더 얻으면 %d레벨",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "현재 속도로 경험치 %s을(를) 더 얻으면 %d레벨이 됩니다.",
	["Te faltan %s de experiencia para el nivel %d"] = "경험치 %s 남음 (%d레벨까지)",
	["Te faltan %s niveles para el %d"] = "%s레벨 남음 (%d까지)",
	["Te faltan ingredientes para el siguiente lote."] = "다음 묶음에 필요한 재료가 부족합니다.",
	["Te faltan ingredientes."] = "재료가 부족합니다.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "%d레벨까지 레벨이 부족합니다. 가이드가 표시해 두고, 경로를 따라 계속 레벨을 올리면 됩니다.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "레벨이 부족합니다. 10레벨부터 레벨마다 포인트를 1개씩 얻습니다.",
	["Te haces el muerto y los enemigos te olvidan. Tu mejor salida si algo sale mal."] = "죽은 척하면 적들이 나를 잊어요. 일이 꼬였을 때 최고의 탈출법이에요.",
	["Te la da %s, en %s."] = "퀘스트 제공: %s(%s).",
	["Te la da %s."] = "퀘스트 제공: %s.",
	["Te la dio %s"] = "준 사람: %s",
	["Te la dio %s · Se entrega con %s"] = "준 사람: %s · 제출: %s",
	["Te la dio y la recibe %s"] = "주고 받는 사람: %s",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "지금 받을 수 있는 경로의 퀘스트로 안내합니다.",
	["Te lleva al Claro de la Luna, un lugar tranquilo para entrenar."] = "수련하기 좋은 조용한 곳, 달의 숲으로 데려가요.",
	["Te llevo a %s"] = "안내 중: %s",
	["Te llevo a entregarlas todas en el mejor orden."] = "가장 좋은 순서로 모두 반납하러 데려갈게요.",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "가장 좋은 출처로 안내합니다. 탈것에는 레벨, 탈것 숙련, 골드가 필요하다는 점을 기억하세요.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "제출할 NPC에게 차례로 안내하고, 이어지는 퀘스트도 받습니다.",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "사냥하는 하루를 세어 둬요: 퀘스트, 레벨, 골드, 희귀 몹, 시간. /alfa lya dia를 입력하면 알려 줄게요.",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "이번 주 사냥과 최고의 날을 세어 둬요. /alfa lya semana를 입력하면 알려 줄게요.",
	["Te lo da un PNJ"] = "NPC가 줌",
	["Te lo enseña cualquier instructor de este oficio en las ciudades. Puedes tener dos oficios principales; Cocina y Primeros auxilios no cuentan."] = "도시에 있는 이 전문 기술 전문가 누구에게서나 배워요. 주 전문 기술은 두 개까지, 요리와 응급치료는 포함되지 않아요.",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "어느 낚시 전문가든 가르쳐 줍니다. 배우기 전에는 숙련도가 한계를 넘지 않습니다.",
	["Te lo enseña tu entrenador."] = "상급자에게서 배울 수 있습니다.",
	["Te lo enseñan desde el nivel %d."] = "%d레벨부터 배울 수 있어요.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "진심으로 부탁할게요. 제 앞에서 늑대 가죽은 절대 벗기지 말아 줘요, 네?",
	["Te los enseña tu entrenador."] = "상급자에게서 배울 수 있습니다.",
	["Te presento a Lya"] = "리아를 소개할게요",
	["Te pusiste «%s»: %d piezas."] = "'%s' 착용: %d부위.",
	["Te queda 1 casilla libre."] = "빈 칸이 1개 남았어요.",
	["Te queda 1 espacio"] = "빈 칸 1개 남음",
	["Te queda 1."] = "1개 남았어요.",
	["Te queda muy poco maná: Estimular lo recupera."] = "마나가 거의 없습니다. 정신 자극으로 회복하세요.",
	["Te queda muy poco maná: Evocación lo recupera."] = "마나가 거의 없습니다. 환기로 회복하세요.",
	["Te queda poca XP descansada"] = "휴식 경험치가 얼마 남지 않았습니다",
	["Te queda poca agua"] = "물이 얼마 없어요",
	["Te queda poca comida"] = "음식이 얼마 없어요",
	["Te queda poca comida y agua"] = "음식과 물이 얼마 없어요",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "마나는 적고 생명력은 넉넉합니다. 생명력을 마나로 바꾸세요.",
	["Te queda poco maná: cambia vida por maná."] = "마나가 부족합니다. 생명력을 마나로 바꾸세요.",
	["Te queda poco maná: usa tu varita."] = "마나가 적습니다. 마법봉을 쓰세요.",
	["Te quedan %d casillas libres."] = "빈 칸이 %d개 남았어요.",
	["Te quedan %d de %d espacios"] = "빈 칸 %d/%d개 남음",
	["Te quedan %d espacios en las bolsas. Vende lo gris o guarda en el banco."] = "가방 칸이 %d개 남았어요. 회색 아이템을 팔거나 은행에 맡기세요.",
	["Te quedan %d."] = "%d개 남았어요.",
	["Te quedaste sin agua"] = "물이 다 떨어졌어요",
	["Te quedaste sin comida"] = "음식이 다 떨어졌어요",
	["Te quedaste sin comida ni agua"] = "음식과 물이 다 떨어졌어요",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "시간에 맞춰 인사하고, 지역 이야기를 하고, 가끔은 뼈다귀를 물고 앉아 조르기도 해요.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "분노가 남고 적이 여럿입니다. 다음 공격이 둘을 칩니다.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "분노가 남습니다. 다음 공격에 쓰세요.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "분노가 남습니다. 다음 공격이 더 강해집니다.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "아주 가까이 있는 뒤쪽 단계의 목표를 제안합니다.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "지금 쓸 기술과 다음 기술을 추천합니다. 추천만 할 뿐, 대신 누르지는 않습니다.",
	["Te teletransporta a tu ciudad. Necesitas una runa de teletransporte."] = "내 도시로 순간이동해요. 순간이동의 룬이 필요해요.",
	["Te teletransportas unos metros hacia adelante. Para escapar de raíces y aturdimientos."] = "몇 미터 앞으로 순간이동해요. 이동 불가와 기절에서 벗어나요.",
	["Te vuelve inmune un rato. Úsalo para salvarte o para escapar."] = "한동안 무적이 돼요. 살아남거나 도망칠 때 쓰세요.",
	["Te vuelves invisible al caminar. Acércate sin que te vean y elige cómo empezar."] = "걷는 동안 투명해져요. 들키지 않고 다가가 시작 방법을 고르세요.",
	["Tecla del modo pesca"] = "낚시 모드 키",
	["Tecla fija para pescar"] = "고정 낚시 키",
	["Tecla grande"] = "큰 키 표시",
	["Tecla para abrir o cerrar el modo"] = "모드 열기/닫기 키",
	["Tecla para volver a lanzar"] = "다시 던지기 키",
	["Tecla y modo pesca"] = "키와 낚시 모드",
	["Tela"] = "천",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "텔드랏실은 너무 커서 가지 사이에 언덕, 호수, 동굴이 있어요.",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "텔드랏실은 나이트 엘프가 용의 축복 없이 심은 세계수예요. 그래서 불멸을 주지 않았어요.",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "텔드랏실은 불멸을 되찾으려고 심었지만 용의 축복이 없었어요. 뭔가 잘못돼 있어요.",
	["Teldrassil siempre tiene una luz suave, como si el árbol mismo nos cuidara."] = "텔드랏실은 늘 부드러운 빛이 있어요. 나무가 우리를 지켜 주는 것처럼요.",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "생명력 물약을 항상 준비해 두세요. 이 빌드는 실수를 용서하지 않습니다.",
	["Tenga o no"] = "보유 여부 무관",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "배고파요… 가방에 있는 것 좀 나눠 줄래요?",
	["Tengo muchas misiones a medias, ¿qué hago?"] = "하다 만 퀘스트가 많아, 어떻게 해?",
	["Tengo poco tiempo, ¿qué hago?"] = "시간이 별로 없는데 뭘 할까요?",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "로데론의 왕 테레나스 메네실은 왕국들을 로데론 동맹으로 묶었어요. 몇 년 뒤 친아들 아서스가 왕좌에서 그를 죽였어요.",
	["Termina la configuración para usar Alfa (2 minutos)."] = "Alfa를 쓰려면 설정을 마치세요(2분).",
	["Terminada"] = "완료",
	["Terminado: cumpliste todas sus metas."] = "완료: 모든 목표를 달성했습니다.",
	["Terminar"] = "마치기",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "군주 발탈락 연계 퀘스트를 끝내는 것도 유산 도전이에요.",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "퀘스트 %d개를 완료했습니다. 제출하고 이어지는 퀘스트를 받으세요.",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "퀘스트 1개를 완료했습니다. 제출하고 이어지는 퀘스트를 받으세요.",
	["Terminaste esta guía."] = "이 가이드를 끝냈습니다.",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "이 가이드를 완료했습니다. 계속 레벨을 올리려면 다음 가이드를 고르세요.",
	["Termínala antes de entregarla."] = "제출하기 전에 완료하세요.",
	["Terreno, como el minimapa"] = "지형(미니맵처럼)",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "지형: 확대하면 산, 강, 색조가 있는 미니맵의 실제 땅이 보입니다. 클래식: 게임의 그림 지도만.",
	["Tesoro"] = "보물",
	["Tesoro de la manada: %s"] = "무리의 보물: %s",
	["Tesoros"] = "보물",
	["Tesoros en el mapa"] = "지도에 보물",
	["Tesoros en el minimapa"] = "미니맵에 보물",
	["Texto de combate flotante"] = "전투 상황 알림",
	["Texto sobre tu personaje"] = "캐릭터 위 글자",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Alfa 창의 글자와 상자가 더 잘 정렬됩니다.",
	["Texturas del mundo"] = "월드 텍스처",
	["Texturas del suelo"] = "지면 텍스처",
	["Texturas proyectadas"] = "투사 텍스처",
	["Texturas y nitidez"] = "텍스처와 선명도",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "대지의 공주 테라드라스는 테라제인의 딸이에요. 세나리우스의 아들 자에타르를 사랑했고, 그 자식인 켄타우로스가 결국 그를 죽였어요.",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "테라모어는 제이나 프라우드무어가 로데론이 무너지기 전에 떠난 인간들과 함께 세웠어요.",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "스랄은 자유로운 오크들이 인간의 수용소에서 멀리 떨어져 새로 시작할 수 있도록 이 붉고 메마른 땅을 골랐어요.",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "스랄은 가장 유명한 주술사예요. 정령이 누구보다 그에게 응답해요.",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "스랄은 대족장으로서 오그리마에서 호드를 다스리며 평화를 바라보고 있어요.",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "스랄은 그롬 헬스크림과 오그림 둠해머의 도움으로 수용소의 오크들을 해방했어요.",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "스랄은 듀로탄과 드라카의 아들로 드레노어에서 태어났어요. 아에델라스 블랙무어가 갓난아기인 그를 찾아 노예라는 뜻의 «스랄»이라 불렀어요.",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "스랄은 오크가 악마에게 타락하기 전의 명예를 되찾길 바라요.",
	["Tiempo"] = "시간",
	["Tiempo de juego por sesión"] = "세션별 플레이 시간",
	["Tiempo hasta que pica"] = "입질까지 걸린 시간",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "두 번 클릭 사이의 최대 시간입니다. 더블 클릭으로 던져지지 않으면 늘리세요.",
	["Tiempo pescando"] = "낚시한 시간",
	["Tiempo: %s"] = "시간: %s",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "따로 진행하는 네 구역이 있습니다: 묘지, 도서관, 무기고, 대성당 순으로 쉬운 곳부터 어려운 곳까지입니다.",
	["Tienes"] = "보유",
	["Tienes %d"] = "%d개 보유",
	["Tienes %d  ·  en %s"] = "보유 %d  ·  %s",
	["Tienes %d casillas libres"] = "빈칸 %d칸",
	["Tienes %d de %d"] = "보유: %d / %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "은행 가방 칸 %d/%d개를 보유했습니다.",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "가방 칸 %d/%d개 보유. 다음 칸은 %s이며, 산 뒤 가방을 넣으세요.",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "%d개가 켜져 있습니다. 바꾸고 싶으면 아래에서 각 기능과 설명을 보세요.",
	["Tienes %d misiones listas"] = "완료한 퀘스트 %d개",
	["Tienes %d misiones listas para entregar"] = "제출할 수 있는 퀘스트 %d개",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "제출할 퀘스트가 %d개 있어요. 한 경로로 묶을까요?",
	["Tienes %d para gastar"] = "사용 가능: %d",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "가방에 더 좋은 낚시 장비가 %d개 있습니다.",
	["Tienes %d puntos de talento: empieza por %s"] = "특성 포인트 %d개: %s부터 찍으세요",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "포인트 %d개가 %s 계열 밖에 있습니다. Alfa는 특성을 절대 초기화하지 않습니다. 이 빌드를 따르려면 직업 상급자에게서 특성을 초기화하세요. Alfa가 클릭 한 번으로 다시 찍어 줍니다. 아니면 지금 찍은 계열의 빌드를 고르세요.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "남은 포인트가 %d개지만 %s의 다음 특성이 내 트리에 없습니다(패치로 바뀌었을 수 있습니다). 게임 창에서 직접 찍거나 다른 스타일을 시도하세요.",
	["Tienes %s de %s"] = "보유: %s / %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "검색으로 얻은 가격이 %s개 있습니다. 모든 가격을 알려면 경매장에서 스캔하세요.",
	["Tienes 1 misión lista para entregar"] = "제출할 수 있는 퀘스트 1개",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "연계 점수 5점이고 파티 중입니다. 출혈 효과가 더 큽니다.",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "연계 점수 5점: 가장 강한 마무리 기술.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "연계 점수 5점: 강하게 물어뜯으세요.",
	["Tienes 6 guías abiertas"] = "가이드 6개가 열려 있음",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "설정 > 편의 기능 > 소셜에서 «길드 초대 거절»이 켜져 있습니다. 초대를 받으려면 끄세요.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "특성 창에 확정하지 않은 변경 사항이 있습니다. 적용하기 전에 취소됩니다.",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "게임의 특성 창에 저장하지 않은 변경 사항이 있습니다. 먼저 그곳에서 저장하거나 되돌리세요",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "\"내 경로의 퀘스트만\"이 켜져 있어 경로의 퀘스트만 수락합니다.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "분노가 있습니다. 다음 전투 전에 쓰세요. 나와 파티의 전투력이 올라갑니다.",
	["Tienes habilidades nuevas"] = "새 기술이 있습니다",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "아직 배우지 않은 기술이 있어요(%d). 배우면 더 강해져요.",
	["Tienes la %s, %d versiones atrás."] = "현재 %s, %d버전 뒤처짐.",
	["Tienes la %s."] = "현재 %s.",
	["Tienes más rangos de los que pide tu build."] = "빌드가 요구하는 것보다 단계가 많습니다.",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "«%s» 적용 중입니다. 창을 열어 거리, 풀, 안개, 물, 카메라, 이름표, 필터를 하나하나 다듬으세요.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "계획 밖에 포인트가 있습니다. Alfa는 빼지 않고 추가만 합니다.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "가이드 6개가 열려 있습니다. 하나를 닫고 다시 시도하세요.",
	["Tienes todo %s"] = "%s 모두 보유",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "드루이드의 성소 달의 숲으로 가는 주문이 있어요.",
	["Tienes un punto de talento: %s"] = "특성 포인트 1개: %s",
	["Tienes una misión de clase"] = "직업 퀘스트가 있습니다",
	["Tinte de color"] = "색조",
	["Tipo"] = "종류",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "티리온 폴드링은 목숨을 구해 준 오크 에이트리그를 감싸다 백은의 손에서 쫓겨났어요. 지금 에이트리그는 오그리마에서 스랄의 조언자예요.",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "기사단에서 쫓겨난 성기사 티리온 폴드링은 이 땅의 오두막에서 홀로 살아요.",
	["Toca %s."] = "이제 %s 차례예요.",
	["Toca ahora"] = "지금 차례",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "스위치를 눌러 넣거나 빼세요. 직접 고른 것이 필터보다 우선합니다.",
	["Toca una tarjeta para prenderla o apagarla. Las encendidas llevan el borde de color."] = "카드를 눌러 켜거나 끄세요. 켜진 카드는 테두리에 색이 있어요.",
	["Toca «Seleccionarlo» otra vez, o usa el botón de raros."] = "「대상 선택」을 한 번 더 누르거나 희귀 몹 버튼을 쓰세요.",
	["Tocando a la puerta de la %s"] = "%s 문을 두드리는 중",
	["Toda calidad"] = "모든 품질",
	["Toda fuente"] = "모든 출처",
	["Toda la cuenta"] = "계정 전체",
	["Toda ranura"] = "모든 부위",
	["Todas"] = "전체",
	["Todas (%d)"] = "모두 (%d)",
	["Todas las calidades"] = "모든 품질",
	["Todas las guías de profesiones"] = "모든 전문 기술 가이드",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "지역과 레벨별 모든 가이드와 Alfa가 추천하는 가이드.",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "모든 애완동물: 얻는 곳, 가격, 없는 것.",
	["Todas las mazmorras"] = "모든 던전",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "이 가이드의 모든 목표, 메모, 단계를 다른 창에서.",
	["Todas las misiones"] = "모든 퀘스트",
	["Todas las misiones de aquí en el mejor orden, con la flecha."] = "이 근처 모든 퀘스트를 최적 순서로, 화살표와 함께.",
	["Todas las misiones de la zona en el mejor orden."] = "지역의 모든 퀘스트를 최적 순서로.",
	["Todas las misiones de tu zona (las que llevas y las que puedes tomar) en el mejor orden, como una guía."] = "내 지역 모든 퀘스트(가진 것과 받을 수 있는 것)를 최적 순서로, 가이드처럼.",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Lya가 저장해 둔 모든 퀘스트를 지역별로, 전체 이야기와 함께. /alfa historias로도 열 수 있습니다.",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "모든 탈것: 각각 얻는 방법, 요구 사항, 보유 여부.",
	["Todas las profesiones"] = "모든 전문 기술",
	["Todas las páginas de Alfa a la vista: mazmorras, talentos, combate, oficios, la manada y más."] = "Alfa의 모든 페이지 표시: 던전, 특성, 전투, 전문 기술, 무리 등.",
	["Todas las secciones"] = "모든 섹션",
	["Todas las teclas de Alfa en un lugar"] = "Alfa의 모든 단축키를 한곳에",
	["Todas las teclas de Alfa en un lugar, para cambiarlas ahí mismo. También con /alfa teclas."] = "Alfa의 모든 단축키를 한곳에서 바로 바꿔요. /alfa teclas로도 돼요.",
	["Todas las zonas"] = "모든 지역",
	["Todas las zonas y razas"] = "모든 지역과 종족",
	["Todavía es pronto"] = "아직 이릅니다",
	["Todavía nada en esta sesión"] = "이번 세션에 아직 없음",
	["Todavía no"] = "아직",
	["Todavía no cambias de guarida"] = "아직 굴이 바뀌지 않았어요",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "아직 이 프리셋의 주문을 모릅니다. 배우면 채워집니다.",
	["Todavía no conozco tus recetas"] = "아직 내 제조법을 모릅니다",
	["Todavía no es para ti"] = "아직 나에게 맞지 않음",
	["Todavía no escribimos nada en tu historia. ¡Vamos a hacer algo grande!"] = "아직 당신의 이야기에 아무것도 안 적었어요. 뭔가 큰 걸 해 봐요!",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "아직 길드에 속해 있지 않습니다. La Jauría 페이지에서 무리에 합류하는 방법을 볼 수 있습니다.",
	["Todavía no has pescado nada en esta sesión"] = "이번 세션에 아직 낚은 것이 없습니다",
	["Todavía no hay ayuda de rotación para ti"] = "아직 내 직업용 로테이션 도우미가 없음",
	["Todavía no hay datos de este personaje"] = "아직 이 캐릭터의 데이터가 없음",
	["Todavía no hay datos para esta gráfica."] = "아직 이 그래프에 표시할 데이터가 없습니다.",
	["Todavía no hay foto de este banco"] = "아직 이 은행의 기록이 없음",
	["Todavía no hay guías para tu camino"] = "아직 길에 맞는 가이드가 없어요",
	["Todavía no hay peleas"] = "아직 전투 기록 없음",
	["Todavía no hay progreso"] = "아직 진행도 없음",
	["Todavía no hay una pelea anterior"] = "아직 이전 전투 없음",
	["Todavía no hay una pelea que anunciar."] = "아직 알릴 전투가 없습니다.",
	["Todavía no hay una pelea que resumir."] = "아직 요약할 전투가 없어요.",
	["Todavía no lo pescas"] = "아직 낚지 않음",
	["Todavía no lo recolectas"] = "아직 채집하지 않음",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "아직 물에서 낚아 올리지 않았어요. 낚으면 몇 마리, 언제, 어디서인지 여기서 볼 수 있습니다.",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "아직 %s에서 낚시하지 않았습니다. 여기서 낚은 것은 지역별로 기록됩니다.",
	["Todavía no puedes conseguirlo: %s."] = "아직 얻을 수 없음: %s.",
	["Todavía no recolectas nada"] = "아직 채집한 것 없음",
	["Todavía no sabes pescar"] = "아직 낚시를 배우지 않았습니다",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "아직 받을 수 없습니다. 열리면 Alfa가 받습니다.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "아직 따라가는 가이드가 없습니다. 하나를 고르면 Alfa가 화살표와 경로로 한 단계씩 안내합니다.",
	["Todavía no te alcanza."] = "아직 돈이 부족합니다.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "사용자 지정 척도가 아직 없습니다. 위에 척도 문자열을 붙여 넣으세요.",
	["Todavía no tienes marcadores"] = "아직 마커가 없음",
	["Todavía no tienes rutas propias"] = "아직 나만의 경로가 없음",
	["Todavía no tienes talentos para compartir."] = "아직 공유할 특성이 없습니다.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "아직 열린 가이드가 없습니다. 하나를 고르면 Alfa가 어디로 가고, 무엇을 하고, 누구와 대화할지 단계별로 안내합니다.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "분화구에는 아직 티탄의 수정탑이 서 있고, 색색의 수정으로 작동해요.",
	["Todo"] = "모두",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "아제로스 전체를 한 화면에: 휠로 확대하고, 끌어서 이동하고, 오른쪽 클릭으로 마커를 놓으세요.",
	["Todo a la mano"] = "모든 것을 손쉽게",
	["Todo a la vista otra vez"] = "다시 전부 보이기",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "모두 안전한 최대치로. 강력한 그래픽 카드가 필요합니다.",
	["Todo bien (lo más gastado: %d%%)"] = "모두 양호 (가장 닳은 것: %d%%)",
	["Todo como estaba antes de Alfa"] = "모두 Alfa 이전처럼",
	["Todo con tu estilo"] = "모두 내 스타일로",
	["Todo el juego, aunque no lo tengas"] = "게임 전체, 내게 없는 것까지",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "게임 전체, 내게 없는 것까지: 아이템, NPC, 퀘스트, 지역, 희귀.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "없는 것까지 게임 전체: 아이템, 탈것, 애완동물, NPC, 퀘스트, 지역, 희귀 몹.",
	["Todo el texto de Alfa un poco más grande, en cada ventana. Se suma al tamaño de Ajustes > Apariencia."] = "모든 창에서 Alfa 글자가 조금 커져요. 설정 > 모양의 크기에 더해져요.",
	["Todo en orden"] = "이상 없음",
	["Todo en orden: nada choca con Alfa."] = "모두 괜찮아요. Alfa와 충돌하는 게 없어요.",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "퀘스트를 주거나 받는 NPC와 대화하면 Alfa가 이 모든 것을 자동으로 합니다. Shift를 누르고 있으면 그때 직접 합니다.",
	["Todo junto"] = "모두 함께",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "모두 함께는 모든 칸을 제자리에 보여 주고, 분류별은 장비, 소비용품, 퀘스트 아이템, 재료로 묶고, 가방별은 가방마다 블록으로 나눕니다.",
	["Todo listo"] = "준비 완료",
	["Todo lo de Alfa, explicado por Lya y a un clic"] = "리아가 설명하는 Alfa의 모든 것, 클릭 한 번",
	["Todo lo que hay en Alfa"] = "Alfa에 있는 모든 것",
	["Todo lo que no sea equipo"] = "장비가 아닌 모든 것",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "지도에 그리는 모든 것을 한곳에서. Alfa의 다른 모듈이 추가한 것도 여기에 나옵니다.",
	["Todo nivel"] = "모든 레벨",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "모든 아이템, NPC, 퀘스트, 지역, 희귀를 얻는 곳과 «안내 시작»까지.",
	["Todo oficio"] = "모든 역할",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "모든 것을 피해에: 치명타, 출혈, 아주 잦은 제압. 엄청나게 빨리 처치하지만 추가 방어가 없으니, 여럿이 몰려오면 도망치세요.",
	["Todo subtipo"] = "모든 하위 종류",
	["Todo tipo"] = "모든 종류",
	["Todos"] = "전체",
	["Todos llegan a %s"] = "모두 이어지는 곳: %s",
	["Todos los avisos de Alfa los dice Lya, también los de al entrar y el de hechizos nuevos, con letra más grande que cambias con su clic derecho."] = "Alfa의 모든 알림을 리아가 말해요. 접속할 때와 새 주문 알림도요. 더 큰 글자는 리아를 오른쪽 클릭해 바꿔요.",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "그 종류 전체 또는 하나만(예: 구리만) 고릅니다. 괄호 안은 현재 지역에 있는 개수입니다.",
	["Todos los materiales"] = "모든 재료",
	["Todos los niveles"] = "모든 레벨",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "모든 아이템, NPC, 퀘스트, 지역, 희귀를 내게 없는 것까지: 누가 어떤 확률로 떨어뜨리는지, 누가 어디서 파는지, 어떤 퀘스트가 주는지, 가는 방법.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "없는 것까지 모든 아이템, 탈것, 애완동물, NPC, 퀘스트, 지역, 희귀 몹: 누가 얼마의 확률로 떨어뜨리는지, 누가 어디서 파는지, 어떤 퀘스트가 주는지, 어떻게 가는지.",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "모든 성기사는 알렉산드로스 모그레인의 검, 파멸의 인도자를 꿈꿔요.",
	["Todos los pasos"] = "모든 단계",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "이 가이드의 모든 단계입니다. 단계를 클릭하면 볼 수 있습니다.",
	["Todos los pasos de la guía en la ventana de guía."] = "가이드 창에서 가이드의 모든 단계를 봅니다.",
	["Todos los que callaste"] = "끈 조언 전부",
	["Todos los tipos"] = "모든 종류",
	["Todos tus personajes"] = "모든 캐릭터",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "포인트를 이미 모두 썼고 일부는 이 빌드 밖에 있습니다. 이 빌드로 바꾸려면 직업 상급자에게 특성을 초기화하세요. 그다음 Alfa가 클릭 한 번으로 적용해 줍니다.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "전체: 가벼운 경고도 표시합니다. 위험만: 나를 죽일 수 있는 것만 표시합니다.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "게임의 자동 전리품 획득이 꺼져 있어도 낚시 전리품을 바로 챙깁니다.",
	["Toma el dinero y los objetos de tus cartas, una por una. Las de pago contra entrega y las de un MJ se quedan para que las abras tú."] = "우편의 돈과 물품을 하나씩 받아요. 대금 청구 우편과 GM 우편은 직접 열도록 남겨 둬요.",
	["Toma las de tu ruta que tienes cerca"] = "근처의 경로 퀘스트 받기",
	["Toma las mejores de cerca que ya puedes hacer."] = "근처에서 지금 할 수 있는 최고의 퀘스트를 받으세요.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "이 근처 최고의 퀘스트를 받고 나중에 한꺼번에 끝내세요.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "자동 전리품 획득이 켜져 있으면 전리품을 한 번에 모두 챙깁니다.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "근처에서 퀘스트를 몇 개 받으면 Alfa가 가장 짧은 길로 함께 끝냅니다.",
	["Tomando tus cartas..."] = "우편 받는 중...",
	["Tomar %s"] = "받기: %s",
	["Tomar el vuelo de tu ruta"] = "경로의 비행 이용",
	["Tomar la mejor recompensa"] = "가장 좋은 보상 받기",
	["Tomar todo"] = "모두 받기",
	["Tomarla"] = "받기",
	["Tomarla, completarla o entregarla."] = "받기, 완료하기, 제출하기.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "같은 묶음의 다른 퀘스트를 받아서 이 퀘스트는 열리지 않습니다.",
	["Top %d de %s"] = "상위 %d: %s",
	["Top de daño"] = "피해 순위",
	["Tope por personaje"] = "캐릭터당 최대",
	["Torre de zepelines de %s"] = "%s 비행선 탑",
	["Tortura mental: daño constante y frena al enemigo."] = "정신의 채찍: 꾸준한 피해, 적을 느리게 합니다.",
	["Total"] = "합계",
	["Tramo %d de %d: %s."] = "%d/%d구간: %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "덫, 비상용 근접 공격, 높은 민첩성: 가장 잡기 어려운 사냥꾼입니다.",
	["Tranquila, aquí nadie se queda atrás."] = "걱정 마요, 여기선 아무도 뒤처지지 않아요.",
	["Tranquilo"] = "안정형",
	["Transformar"] = "제작",
	["Transformar %d"] = "제작 %d",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "철을 금으로 변환하는 건 진짜 있어요. 모든 연금술사의 꿈이죠.",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "수락이나 제출 후, 가이드가 하지 않는 퀘스트만 있는 NPC라면 창을 닫습니다.",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "세 망치의 전쟁 뒤 와일드해머는 그림 바톨로, 다시 동부 내륙지로 떠났고, 검은무쇠는 검은바위 산으로 갔어요.",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "2차 대전쟁 뒤 오크를 수용소에 가두는 데 엄청난 돈이 들었어요. 그 세금이 얼라이언스를 갈라놓는 데 한몫했어요.",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "트롤 전쟁 뒤 옛 아라소르는 일곱 왕국으로 나뉘었어요: 로데론, 스톰윈드, 길니어스, 알터랙, 스트롬가드, 쿨 티라스, 달라란.",
	["Tratado"] = "성서",
	["Treinta. La manada habla de ti."] = "서른. 무리가 당신 얘기를 해요.",
	["Tres caminos para cada objeto"] = "아이템마다 세 가지 방법",
	["Tres estilos y el lobo"] = "스타일 3가지와 늑대",
	["Tres pasos y listo"] = "세 단계면 끝",
	["Tres pasos: tus clics, dónde van tus marcos y una prueba."] = "세 단계: 클릭 설정, 프레임 위치, 테스트.",
	["Trescientos puntos. Eres maestro de tu oficio."] = "300점. 당신은 이 기술의 대가예요.",
	["Trilineal"] = "삼선형",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "톱니항은 중립 고블린 항구예요. 골드만 있으면 누구든 받아 주고, 배는 무법항까지 가요.",
	["Trofeo"] = "전리품",
	["Trofeos y concurso"] = "전리품과 대회",
	["Trols"] = "트롤",
	["Trueno"] = "천둥",
	["Tu Alfa ya está configurada. Revisa o cambia cualquier respuesta cuando quieras."] = "내 Alfa 설정이 끝났습니다. 언제든 답을 확인하거나 바꿀 수 있습니다.",
	["Tu Grito de batalla llega a todo el grupo y dura más."] = "전투의 외침이 파티 전체에 닿고 더 오래 지속됩니다.",
	["Tu abisario aguanta los golpes por ti: deja que empiece la pelea."] = "공허방랑자가 대신 공격을 받아 줍니다. 공허방랑자가 먼저 싸움을 시작하게 하세요.",
	["Tu abisario: un demonio que aguanta golpes por ti. Perfecto para ir solo."] = "보이드워커: 나 대신 공격을 받는 악마. 혼자 다니기에 딱이에요.",
	["Tu anuncio ya está en el tablón de la manada. Se quita solo en una hora."] = "글이 무리 게시판에 올라갔어요. 한 시간 뒤 저절로 사라져요.",
	["Tu aprendiz no gana experiencia desde hace 20 minutos. ¿Le echas la mano?"] = "제자가 20분째 경험치를 못 얻고 있어요. 도와줄래요?",
	["Tu aprendiz: %s"] = "내 제자: %s",
	["Tu arma a veces da golpes extra. De lo mejor para armas lentas."] = "무기가 가끔 추가로 공격해요. 느린 무기에 가장 좋은 것 중 하나예요.",
	["Tu arma no tiene encantamiento: Lengua de fuego."] = "무기에 마법부여 없음: 불꽃의 무기.",
	["Tu arma no tiene encantamiento: Muerdepiedras."] = "무기에 마법부여 없음: 대지의 무기.",
	["Tu arma no tiene encantamiento: Viento furioso."] = "무기에 마법부여 없음: 질풍의 무기.",
	["Tu arma no usa munición."] = "무기에 탄약이 필요 없습니다.",
	["Tu arma pega con fuego. Buena para armas lentas."] = "무기가 불로 공격해요. 느린 무기에 좋아요.",
	["Tu arma secundaria pega más."] = "보조장비 무기가 더 세게 때립니다.",
	["Tu armadura ya no aguanta mucho (%d%%). ¿Vamos a reparar?"] = "방어구가 오래 못 버텨요(%d%%). 수리하러 갈까요?",
	["Tu avance arriba, el paso en una tarjeta, los dos siguientes a la vista y los botones abajo."] = "위에는 진행도, 카드에는 현재 단계, 다음 두 단계도 보이고 버튼은 아래에 있습니다.",
	["Tu avance de misiones con tu grupo"] = "파티와 함께하는 퀘스트 진행 상황",
	["Tu ayuda de rotación está lista"] = "로테이션 도우미 준비 완료",
	["Tu banco"] = "내 은행",
	["Tu banco está completo"] = "은행 칸을 모두 샀음",
	["Tu banco y lo que llevas"] = "내 은행과 소지품",
	["Tu banco ya tiene todas sus casillas."] = "은행 칸을 이미 모두 샀습니다.",
	["Tu barra de %s está vacía"] = "%s 단축바가 비어 있습니다",
	["Tu barra se llena al salir de combate."] = "전투가 끝나면 단축바를 채웁니다.",
	["Tu botón de emergencia."] = "비상 버튼입니다.",
	["Tu buff"] = "내 강화 효과",
	["Tu build"] = "내 빌드",
	["Tu camino"] = "내 길",
	["Tu camino [mapa]"] = "내 경로",
	["Tu camino en el mapa y un aullido nuevo"] = "지도 위 나의 길, 그리고 새로운 울음",
	["Tu camino: %d tramos, %s. Escribe arriba para ir a otro lugar."] = "내 경로: %d구간, %s. 다른 곳에 가려면 위에 입력하세요.",
	["Tu caña tiene cebo: %s más."] = "낚싯대에 미끼가 있습니다: %s 남음.",
	["Tu cita con la manada"] = "무리와의 약속",
	["Tu cita, %s"] = "내 약속, %s",
	["Tu clase la gana con esta cadena de misiones."] = "이 연계 퀘스트로 내 직업이 얻습니다.",
	["Tu clase no lo usa: guárdalo para otro personaje o súbelo a la subasta."] = "내 직업은 이걸 쓰지 않아요. 다른 캐릭터에게 주거나 경매장에 올리세요.",
	["Tu clase no necesita recordatorio"] = "내 직업은 알림이 필요 없습니다",
	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "내 직업에는 반응 기술이 없습니다. 원하면 게임이 내 기술을 빛나게 할 때 Alfa가 알려 줍니다(아래 알림에서).",
	["Tu clase todavía no tiene uno propio: Alfa usa el más parecido."] = "내 직업 전용은 아직 없어 Alfa가 가장 비슷한 것을 씁니다.",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "이 클라이언트는 애드온으로 특성을 바꿀 수 없습니다. 게임의 특성 창(N 키)을 쓰세요.",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "이 클라이언트에는 우두머리 타임라인이 없습니다.",
	["Tu cliente no trae el medidor de daño del juego."] = "내 클라이언트에는 게임의 피해 측정기가 없습니다.",
	["Tu cliente no trae la ayuda de combate de Blizzard."] = "이 클라이언트에는 블리자드 전투 보조가 없습니다.",
	["Tu cola"] = "내 대기열",
	["Tu cola de cocina está vacía"] = "요리 대기열이 비어 있습니다",
	["Tu color de acento"] = "내 강조 색",
	["Tu compañera"] = "나의 동료",
	["Tu compañera de caza"] = "사냥 동료",
	["Tu compañera en Alfa. Lleva el nombre de una gran perrita, en su memoria."] = "Alfa의 동료. 멋진 강아지를 기억하며 그 이름을 이어받았어요.",
	["Tu configuración como texto: guárdalo de respaldo o pásaselo a la manada."] = "내 설정을 글로: 백업으로 보관하거나 무리에게 전해 줘요.",
	["Tu configuración de Alfa"] = "내 Alfa 설정",
	["Tu configuración quedó guardada como «%s»."] = "설정을 «%s» 프로필로 저장했어요.",
	["Tu corcel vil: una montura propia de brujo. ¡Felicidades!"] = "지옥마: 흑마법사만의 탈것이에요. 축하해요!",
	["Tu correo"] = "내 우편",
	["Tu cuerpo"] = "내 시체",
	["Tu cuerpo está a %s, como %s corriendo."] = "시체가 %s 떨어져 있어요. 걸어서 약 %s.",
	["Tu cuerpo quedó dentro de %s: corre a su entrada."] = "시체가 %s 안에 있어요. 입구로 달려가세요.",
	["Tu curación"] = "내 치유",
	["Tu curación básica. Úsala entre peleas o cuando estés herido."] = "기본 치유예요. 전투 사이나 다쳤을 때 쓰세요.",
	["Tu curación fuerte. Úsala entre peleas o cuando alguien está muy herido."] = "강력한 치유예요. 전투 사이나 누가 크게 다쳤을 때 쓰세요.",
	["Tu curación más fuerte. Es lenta: empiézala antes de que sea tarde."] = "가장 강력한 치유예요. 느리니까 너무 늦기 전에 시작하세요.",
	["Tu daño"] = "내 피해",
	["Tu demonio"] = "내 악마",
	["Tu demonio es más fuerte y tú más resistente: el brujo más seguro."] = "악마는 더 강해지고 나는 더 튼튼해집니다. 가장 안전한 흑마법사입니다.",
	["Tu destino"] = "내 목적지",
	["Tu destino y tus marcadores ya no desaparecen cuando hay muchos pines."] = "핀이 많아도 목적지와 마커가 사라지지 않습니다.",
	["Tu diario"] = "내 일지",
	["Tu diario de mazmorras"] = "내 던전 도감",
	["Tu día con la manada: el plan, lo urgente y tu clase."] = "무리와 함께하는 하루: 계획, 급한 일, 내 직업.",
	["Tu día de caza"] = "오늘의 사냥",
	["Tu día de caza: Lya cuenta tus misiones, niveles, oro y raros del día. Pídeselo con /alfa lya dia."] = "오늘의 사냥: 리아가 그날의 퀘스트, 레벨, 골드, 희귀 몹을 세어요. /alfa lya dia로 물어보세요.",
	["Tu elección"] = "내 선택",
	["Tu entrenador de clase tiene algo para ti."] = "직업 상급자에게 배울 것이 있습니다.",
	["Tu entrenador de equitación"] = "내 탈것 조련사",
	["Tu entrenador tiene algo nuevo para ti"] = "상급자에게 새로 배울 것이 있습니다",
	["Tu entrenador: %s (%s)."] = "내 상급자: %s (%s).",
	["Tu entrenador: %s."] = "내 상급자: %s.",
	["Tu equipo está al %d %%: repara antes de entrar"] = "장비 내구도 %d %%: 들어가기 전에 수리하세요",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "장비 내구도가 %d%%예요. 다음 전투 전에 수리하는 게 좋아요.",
	["Tu equipo está por romperse"] = "장비가 곧 망가져요",
	["Tu equipo se está gastando"] = "장비가 닳고 있습니다",
	["Tu equipo ya va en %d %%: cuídalo."] = "장비 내구도가 벌써 %d %%예요. 잘 챙기세요.",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "장비, 가방, 수련 모두 문제없습니다.",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "보호막은 든든하지만, 아군에게 한동안 약화된 영혼을 남겨요. 바로 다시 걸 수 없어요.",
	["Tu especialización"] = "내 전문화",
	["Tu estilo"] = "내 스타일",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "내 스타일(Alfa, WoW 클래식, 유리), 강조 색, 울음소리.",
	["Tu estilo, el color de acento, el aullido, leer mejor y tus atajos."] = "내 스타일, 강조 색, 울음소리, 읽기 편하게, 단축키.",
	["Tu estilo: %s"] = "내 스타일: %s",
	["Tu facción (%s)"] = "내 진영 (%s)",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "치타 변신은 날쌘 고양이지만... 달리기 시합이라면 저도 쉽게 지지 않아요.",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "당신 종족은 비전 마법을 믿지 않아요. 아즈샤라와 영원의 샘에 무슨 일이 있었는지 잘 기억하거든요.",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "당신 종족인 인간은 수천 년 전 소라딘 왕이 아라소르로 모은 부족들의 후손이에요.",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "40레벨부터 60레벨까지 가장 강한 공격입니다.",
	["Tu golpe más fuerte desde el nivel 40."] = "40레벨부터 쓰는 가장 강한 공격입니다.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "가장 강한 공격으로, 방패 막기 수치에 따라 강해집니다.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "가장 강한 공격이며 적이 받는 치유도 줄입니다.",
	["Tu golpe más fuerte."] = "가장 강한 공격입니다.",
	["Tu golpe principal contra jefes."] = "우두머리를 상대하는 주력 공격입니다.",
	["Tu golpe principal."] = "주력 공격입니다.",
	["Tu grupo"] = "내 파티",
	["Tu grupo en el mapa"] = "지도의 내 파티",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "파티나 공격대를 지도와 미니맵에 직업 색상으로 표시합니다.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "파티와 공격대의 생명력을 보여 주고 클릭 한 번으로 치유합니다. 전투 중이 아닐 때 바뀝니다.",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "파티, 길드, 친구를 지도에 표시하고 따라가기와 클랜 페이지도 제공합니다.",
	["Tu guarida a la vista"] = "내 굴 보이기",
	["Tu guarida en el rastreador y en el cuadro de los lobos, y Lya te avisa si el juego te cambia de capa."] = "추적기와 늑대 툴팁에 내 굴이 나오고, 게임이 레이어를 바꾸면 리아가 알려 줘요.",
	["Tu guarida está abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo."] = "굴이 열렸어요. 무리 중 누가 들어오고 싶어 하면 Alfa가 파티에 초대해요.",
	["Tu guía"] = "내 가이드",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "다른 퀘스트에 필요하지 않다면, 가이드는 더 이상 경험치를 주지 않는 퀘스트를 뺍니다.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "가이드가 준비되었습니다. 열어서 현재 단계를 확인하세요.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "가이드가 알아서 고르고 진행하거나, 갈림길마다 물어보게 할 수 있습니다.",
	["Tu guía te lleva a entrenar en %d pasos."] = "%d단계 뒤 가이드가 수련하러 안내합니다.",
	["Tu guía te lleva a entrenar en este paso."] = "가이드가 이 단계에서 수련하러 안내합니다.",
	["Tu guía te lleva a tomarla."] = "가이드가 퀘스트를 받으러 안내합니다.",
	["Tu guía terminó y el camino se abre"] = "가이드가 끝나고 길이 갈라집니다",
	["Tu guía y Hoy dicen lo mismo: al terminar «Desbloquear» vuelves solo a tu guía, y el final de una guía con pasos sin hacer ya no dice «terminaste»."] = "가이드와 오늘이 같은 걸 말해요. 「해금」을 끝내면 알아서 원래 가이드로 돌아가고, 안 한 단계가 남은 가이드 끝은 더 이상 「완료」라고 하지 않아요.",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "가이드가 더 이상 끝나지 않은 퀘스트를 제출하러 보내지 않습니다. 먼저 남은 목표로 안내하고, «내 퀘스트 끝내기»는 알아서 최신 상태가 됩니다.",
	["Tu guía, más lista"] = "더 똑똑한 가이드",
	["Tu hechizo principal de fuego."] = "주력 화염 주문.",
	["Tu hechizo principal."] = "주력 주문.",
	["Tu hechizo principal: daño y frena al enemigo."] = "주력 주문: 피해를 주고 적을 느리게 합니다.",
	["Tu hermandad conectada"] = "접속 중인 길드원",
	["Tu hermandad sabe tu clase y tu nivel, para que te avisen si les sale algo que te sirve."] = "길드가 내 직업과 레벨을 알아서, 나한테 쓸모 있는 게 나오면 알려 줘요.",
	["Tu hermandad se entera cuando llegas al nivel 60, consigues tu primera montura o cazas un raro."] = "60레벨이 되거나, 첫 탈것을 얻거나, 희귀를 사냥하면 길드가 알게 돼요.",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "내가 타는 시간을 길드와 파티가 받고, 나도 그들의 시간을 받습니다.",
	["Tu historia"] = "당신의 이야기",
	["Tu historia empieza pronto"] = "당신의 이야기가 곧 시작돼요",
	["Tu historia tiene una página: %s."] = "당신의 이야기는 1페이지예요: %s.",
	["Tu historial"] = "내 기록",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "초상화 테두리에 La Jauría 휘장이 표시되고, 대상도 가지고 있으면 대상에도 표시됩니다.",
	["Tu insignia en los retratos"] = "초상화의 휘장",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "설치가 섞여 있거나 불완전합니다(%s). 게임을 종료하고 Interface/AddOns의 Alfa 폴더를 모두 삭제한 뒤 CurseForge 앱이나 최신 zip(\"Source code\" 아님)으로 Alfa를 다시 설치하세요.",
	["Tu instructor más cercano: %s, en %s."] = "가장 가까운 전문가: %s, %s.",
	["Tu instructor más cercano: %s."] = "가장 가까운 전문가: %s.",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "분노는 때리고 맞을 때 차요. 돌진으로 전투를 열면 분노를 갖고 시작해요.",
	["Tu libro no tiene hechizos para aliados"] = "마법책에 아군에게 쓸 주문이 없습니다",
	["Tu lista de compras"] = "내 장보기 목록",
	["Tu lista de compras no pudo agregarlo."] = "장보기 목록에 추가하지 못했어요.",
	["Tu lista de sonidos"] = "내 소리 목록",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "소리 목록이 비어 있습니다. /alfa silenciar <번호>로 추가하세요.",
	["Tu lista de sonidos quedó vacía."] = "소리 목록이 비었습니다.",
	["Tu lista está vacía"] = "목록이 비어 있어요",
	["Tu lista ya tiene 20 metas: termina o quita alguna primero."] = "목록에 이미 목표가 20개예요. 먼저 하나를 끝내거나 지우세요.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "내 목록: 화살표로 따라가고, 파티와 공유하고, 바꾸거나 삭제하세요.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "나의 동료 암컷 늑대: 짧은 조언과 응원, 그리고 절대 나를 두고 가지 않습니다.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "나의 동료 암컷 늑대: 조언과 응원을 건넵니다. /alfa lya로도 부를 수 있습니다.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "내 위치가 더 잘 보입니다: 화살표에 고리와 부드러운 고동이 생겨 눈 위에서도 잘 보입니다.",
	["Tu manada"] = "내 무리",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "지도의 내 무리: 파티와 Alfa를 쓰며 공유하는 사람들. 화살표로 따라가고, 초대하고, 클랜을 만나 보세요.",
	["Tu manada está fuera del mapa"] = "무리가 지도 밖에 있음",
	["Tu manáfago: quita magia y bloquea hechizos enemigos."] = "지옥사냥개: 마법을 없애고 적의 주문을 봉쇄해요.",
	["Tu mapa"] = "내 지도",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "마우스 클릭 설정이 비어 있습니다. 먼저 칸 하나에 동작을 고르세요.",
	["Tu marcador"] = "내 마커",
	["Tu mascota"] = "내 소환수",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "야수는 다른 짐승에게서 기술을 배워요. 원하는 기술을 아는 짐승을 길들이면 가르쳐 줘요.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "소환수가 일의 대부분을 하고 공격도 대신 받아 줍니다. 사냥꾼으로 레벨을 올리는 가장 쉽고 안전한 방법입니다.",
	["Tu mascota tiene poca vida: cúrala."] = "소환수의 생명력이 낮습니다. 치유하세요.",
	["Tu mejor día: %d misiones"] = "최고의 하루: 퀘스트 %d개",
	["Tu mejor día: %d misiones."] = "최고의 날: 퀘스트 %d개.",
	["Tu mentor: %s"] = "내 멘토: %s",
	["Tu montura de clase"] = "내 직업 탈것",
	["Tu montura rápida (nivel 60)"] = "내 빠른 탈것 (60레벨)",
	["Tu munición"] = "내 탄약",
	["Tu nivel"] = "내 레벨",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "내 레벨, 수리, 음식과 음료, 나에게 맞는 던전 입구.",
	["Tu nota"] = "내 메모",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "대상이 회피했습니다. 제압은 회피할 수 없고 세게 때립니다. 전투 태세가 필요합니다.",
	["Tu oro"] = "내 골드",
	["Tu pantalla y tu compañera"] = "화면과 동료",
	["Tu papel"] = "내 역할",
	["Tu paso de ahora es el %d."] = "현재 단계는 %d단계입니다.",
	["Tu paso de ahora es el %d: %s."] = "현재 단계는 %d단계입니다: %s.",
	["Tu pelea"] = "내 전투",
	["Tu personaje"] = "내 캐릭터",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "똑같이 위치를 보여 주는 사람들의 지도에 내 캐릭터가 보입니다. 게임 안의 위치만, 던전 안에서는 보이지 않습니다. 다른 애드온을 쓰는 사람이 읽을 수 있는 숨은 채널로 전달됩니다.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "캐릭터가 \"마나가 부족합니다\", \"아직 준비되지 않았습니다\" 같은 말을 하지 않습니다. 빨간 글씨는 그대로 나옵니다.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "La Jauría 누구의 지도에도 내 캐릭터가 나타나지 않습니다. La Jauría 페이지에서 언제든 바꿀 수 있습니다.",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "캐릭터가 아직 채집을 하지 않습니다. 채광이나 약초채집을 배우면 Alfa가 현재 지역의 광맥이나 약초를 짧은 순환 경로로 이어 줍니다. 전문 기술 전문가에게 배울 수 있습니다.",
	["Tu pesca"] = "내 낚시",
	["Tu pesca está al máximo"] = "낚시 숙련도 최대",
	["Tu piedra de hogar te regresa a tu posada. Úsala para ahorrar caminata."] = "귀환석은 내 여관으로 데려다줘요. 걷는 시간을 아끼세요.",
	["Tu piedra de hogar y el descanso"] = "귀환석과 휴식",
	["Tu pieza más gastada: %s al %d %%."] = "가장 닳은 장비: %s, %d %%.",
	["Tu plan"] = "내 계획",
	["Tu plan de juego"] = "내 플레이 계획",
	["Tu plan está en Talentos."] = "내 계획은 특성에 있습니다.",
	["Tu plan no pudo agregarlo."] = "계획에 추가하지 못했습니다.",
	["Tu plan no tiene metas"] = "계획에 목표가 없습니다",
	["Tu plan no tiene metas todavía"] = "계획에 아직 목표가 없습니다",
	["Tu plan para %s, con tus minutos de verdad."] = "%s 계획, 실제 내 시간으로.",
	["Tu plan para %s: unos %d min por misión, %s."] = "%s 계획: 퀘스트당 약 %d분, %s.",
	["Tu plan se quedó sin paso"] = "계획에 남은 단계가 없습니다",
	["Tu plan se quedó sin paso. Seguir lo vuelve a armar con las misiones que tienes ahora."] = "계획에 남은 단계가 없습니다. 따라가기를 누르면 지금 가진 퀘스트로 다시 만듭니다.",
	["Tu plano nuevo"] = "새 레이어",
	["Tu posición en la parte de abajo del minimapa."] = "미니맵 아래쪽에 내 위치를 표시합니다.",
	["Tu posición y la del cursor bajo el mapa."] = "지도 아래에 내 위치와 커서 위치를 표시합니다.",
	["Tu primer demonio: el diablillo lanza fuego desde lejos."] = "첫 악마: 임프가 멀리서 불을 던져요.",
	["Tu primer día en Azeroth"] = "아제로스에서의 첫날",
	["Tu primer punto, en el nivel 10."] = "첫 포인트는 10레벨에 받습니다.",
	["Tu primer raro"] = "첫 희귀 몹",
	["Tu primer raro: %s"] = "첫 희귀 몹: %s",
	["Tu primer talento"] = "첫 특성",
	["Tu primera curación. Úsala entre peleas para no gastar comida."] = "첫 치유 주문이에요. 전투 사이에 써서 음식을 아끼세요.",
	["Tu primera guía"] = "첫 가이드",
	["Tu primera mazmorra"] = "첫 던전",
	["Tu primera mazmorra: %s"] = "첫 던전: %s",
	["Tu primera montura"] = "첫 탈것",
	["Tu primera montura (nivel 40)"] = "내 첫 탈것 (40레벨)",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "첫 세션은 게임을 종료하면 일지에 기록됩니다. 무리가 기다립니다. 사냥하러 가요!",
	["Tu prioridad"] = "내 우선순위",
	["Tu prioridad: %s"] = "내 우선순위: %s",
	["Tu progreso"] = "내 진행도",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "원하는 순서로 만드는 나만의 목표 목록: 아이템, 골드, 전문 기술, 장소, 퀘스트, 레벨, 메모. Alfa가 알아서 확인하고 하나씩 안내합니다.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "파티에 없을 때도 내 프레임을 표시해 클릭 한 번으로 나를 치유할 수 있습니다.",
	["Tu prueba"] = "내 테스트",
	["Tu rama: %s"] = "내 계열: %s",
	["Tu rastro"] = "내 흔적",
	["Tu ratón"] = "내 마우스",
	["Tu registro está lleno: cierra algunas misiones primero."] = "퀘스트 목록이 가득 찼습니다. 먼저 몇 개를 끝내세요.",
	["Tu registro está vacío"] = "퀘스트 목록이 비어 있음",
	["Tu reporte, listo para pegar"] = "붙여 넣을 준비가 된 보고서",
	["Tu retrato y el de tu objetivo"] = "내 초상화와 대상 초상화",
	["Tu ritmo de los últimos 15 minutos"] = "최근 15분 동안의 속도",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Alfa 경험치 추적기로 잰 최근 15분 동안의 속도입니다.",
	["Tu ruta de %d tramos."] = "내 경로: %d구간.",
	["Tu ruta de %s en %s está lista"] = "%s 경로 준비 완료: %s",
	["Tu ruta dibujada en el mapa de Alfa hasta tu destino, que late para que lo encuentres; arriba ves a qué distancia está y cuánto falta, y un clic te muestra todo el camino."] = "Alfa 지도에 목적지까지 경로를 그려 주고, 목적지는 찾기 쉽게 고동칩니다. 위쪽에서 얼마나 먼지, 얼마나 남았는지 볼 수 있고, 한 번 클릭하면 전체 경로를 보여 줍니다.",
	["Tu ruta está vacía"] = "경로가 비어 있음",
	["Tu ruta no pudo agregarlo."] = "경로에 추가하지 못했습니다.",
	["Tu ruta no tiene tramos todavía"] = "아직 경로에 구간이 없음",
	["Tu ruta pasa por ahí."] = "경로가 그곳을 지나갑니다.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "내 구간으로 Alfa가 만든 나만의 경로입니다.",
	["Tu ruta se actualizó"] = "경로가 업데이트됨",
	["Tu ruta, guía por guía"] = "가이드별 내 경로",
	["Tu ruta, paso a paso"] = "한 단계씩 따라가는 경로",
	["Tu ruta, tus misiones y tus guías (/alfa rutas ayuda)."] = "내 경로, 퀘스트, 가이드 (/alfa rutas ayuda).",
	["Tu semana de caza"] = "이번 주 사냥",
	["Tu semana se comparte con tu hermandad. Cada lobo suma; aquí nadie compite."] = "내 한 주가 길드와 공유돼요. 늑대마다 더해질 뿐, 여기선 경쟁하지 않아요.",
	["Tu semana solo la ves tú. Compártela en los ajustes de abajo para sumar con la manada."] = "내 한 주는 나만 봐요. 아래 설정에서 공유하면 무리와 합쳐져요.",
	["Tu semana: %s"] = "내 한 주: %s",
	["Tu sesión anterior (%s): %s"] = "이전 세션 (%s): %s",
	["Tu sesión anterior, %s"] = "이전 세션, %s",
	["Tu sesión de ahora"] = "현재 세션",
	["Tu sesión de pesca ya estaba vacía: la nueva empieza con tu primer lanzamiento."] = "낚시 세션이 이미 비어 있습니다. 새 세션은 첫 낚싯대 던지기부터 시작됩니다.",
	["Tu sesión, tu diario, recordatorios y tu siguiente paso, con el color de tu clase."] = "내 세션, 일지, 알림, 다음 단계를 직업 색상으로 보여 줍니다.",
	["Tu siguiente mazmorra"] = "다음 던전",
	["Tu siguiente paso"] = "다음 단계",
	["Tu siguiente paso, lo urgente y lo de tu clase, de un vistazo."] = "다음 단계, 급한 일, 내 직업에 필요한 것을 한눈에 봅니다.",
	["Tu siguiente talento"] = "다음 특성",
	["Tu spot de farmeo"] = "내 파밍 장소",
	["Tu súcubo: mucho daño y puede seducir a un enemigo para controlarlo."] = "서큐버스: 큰 피해를 주고, 적을 유혹해 조종할 수 있어요.",
	["Tu tecla de pantalla limpia"] = "내 깔끔한 화면 키",
	["Tu tecla del mapa (%s) lo abre."] = "지도 키(%s)로 엽니다.",
	["Tu tecla primero te pone la mejor caña y lo que tengas con bonificación de pesca (sombrero, guantes, botas, abalorios)."] = "키는 먼저 가장 좋은 낚싯대와 낚시 보너스가 있는 장비(모자, 장갑, 장화, 장신구)를 입힙니다.",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "내 키와 게임 설정은 그대로 남습니다. 켜면 키 하나로 낚시합니다.",
	["Tu tiempo de juego"] = "내 플레이 시간",
	["Tu tiempo y tu camino al 60"] = "내 시간과 60까지의 길",
	["Tu ventana de Alfa"] = "Alfa 창",
	["Tu vida baja: Rejuvenecimiento te cura poco a poco."] = "생명력이 줄고 있습니다. 회복으로 조금씩 치유합니다.",
	["Tu vida baja: Renovar te cura poco a poco."] = "생명력이 줄고 있습니다. 소생으로 조금씩 치유합니다.",
	["Tu vida baja: el escudo absorbe el daño."] = "생명력이 줄고 있습니다. 보호막이 피해를 흡수합니다.",
	["Tu vida está a punto de acabarse: Imposición de manos te cura entero."] = "생명력이 바닥나기 직전입니다. 신의 축복으로 완전히 치유합니다.",
	["Tu vida está baja: cúrate rápido."] = "생명력이 낮습니다. 빨리 치유하세요.",
	["Tu vida está baja: cúrate."] = "생명력이 낮습니다. 치유하세요.",
	["Tu vida está baja: róbasela al enemigo."] = "생명력이 낮습니다. 적에게서 빼앗으세요.",
	["Tu vida está muy baja: cúrate rápido."] = "생명력이 매우 낮습니다. 빨리 치유하세요.",
	["Tu vuelo en el mapa"] = "지도에 내 비행",
	["Tu zona"] = "내 지역",
	["Tu árbol"] = "내 트리",
	["Tu última pelea"] = "마지막 전투",
	["Tu última sesión: %s · %s"] = "지난 세션: %s · %s",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "마지막 스캔: %s. 최신 가격을 유지하려면 경매장에서 다시 스캔하세요.",
	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "투랄리온과 알레리아 윈드러너는 전쟁 뒤 오크의 길을 막으려고 어둠의 문을 건넜고, 돌아오지 않았어요.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "포인트 %d개가 모두 빌드대로 찍혀 있습니다. 다음은 장비입니다. 내 빌드에 맞는 능력치가 붙은 장비를 찾으세요.",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "태세는 전투, 방어, 광폭 태세예요. 그때그때 필요한 걸 고르세요.",
	["Tus ajustes de Alfa llegaron vacíos"] = "Alfa 설정이 비어 있었어요",
	["Tus ajustes pasan una prueba de guardar y recargar en cada versión, para que nunca se pierdan."] = "모든 버전에서 설정이 저장과 다시 불러오기 테스트를 거치므로 사라지지 않습니다.",
	["Tus ajustes quedaron guardados: %s."] = "설정을 저장했어요: %s.",
	["Tus ajustes volvieron a como estaban: %s. Algunas cosas se ven completas al recargar."] = "설정이 예전으로 돌아왔어요: %s. 일부는 다시 불러오기 후에 완전히 보여요.",
	["Tus ajustes vuelven a como estaban: %s. Lo de ahora queda guardado como el perfil «%s»."] = "설정이 예전으로 돌아가요: %s. 지금 설정은 '%s' 프로필로 저장돼요.",
	["Tus atajos"] = "내 단축키",
	["Tus atajos de Alfa"] = "내 Alfa 단축키",
	["Tus atajos se abren al terminar el combate."] = "단축키 창은 전투가 끝나면 열려요.",
	["Tus avisos"] = "내 알림",
	["Tus beneficios y perjuicios"] = "내 강화 효과와 약화 효과",
	["Tus bolsas"] = "내 가방",
	["Tus bolsas están casi llenas"] = "가방이 거의 가득 찼습니다",
	["Tus bolsas están llenas"] = "가방이 가득 찼습니다",
	["Tus bolsas están vacías"] = "가방이 비어 있음",
	["Tus bolsas piden auxilio (%d libres). Vende o tira lo que ya no uses."] = "가방이 살려 달래요(빈칸 %d). 안 쓰는 건 팔거나 버리세요.",
	["Tus bolsas se están llenando"] = "가방이 차고 있습니다",
	["Tus bolsas se están llenando: queda 1 casilla."] = "가방이 차고 있습니다: 1칸 남음.",
	["Tus bolsas se están llenando: quedan %d casillas."] = "가방이 차고 있습니다: %d칸 남음.",
	["Tus bolsas se llenaron: lo demás sigue en el buzón."] = "가방이 가득 찼어요: 나머지는 우편함에 그대로 있어요.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "가방과 은행을 한 창에서 보고, 각 캐릭터가 가진 것도 확인합니다.",
	["Tus builds importados"] = "가져온 빌드",
	["Tus clics"] = "내 클릭",
	["Tus clics de Curación se aplican al salir de combate."] = "치유 클릭은 전투가 끝나면 적용됩니다.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "클릭이 프리셋 설정으로 돌아갑니다. 직접 바꾼 내용은 사라집니다.",
	["Tus clics:"] = "내 클릭:",
	["Tus comodidades están listas"] = "편의 기능 준비 완료",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Alfa 지도에 파티원과 공격대원을 표시합니다.",
	["Tus conjuntos de equipo"] = "내 장비 구성",
	["Tus conjuntos:"] = "내 구성:",
	["Tus críticos de habilidades pegan todavía más."] = "기술의 치명타가 훨씬 더 세집니다.",
	["Tus críticos hacen muchísimo daño."] = "치명타가 엄청난 피해를 줍니다.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "치명타가 출혈을 일으켜, 더 빨리 처치하고 덜 고생합니다.",
	["Tus críticos sangran."] = "치명타가 출혈을 일으킵니다.",
	["Tus críticos sangran: más daño y amenaza."] = "치명타가 출혈을 일으킵니다: 피해와 위협 수준 증가.",
	["Tus curas curan más."] = "치유량이 늘어납니다.",
	["Tus datos"] = "내 데이터",
	["Tus datos guardados"] = "저장된 데이터",
	["Tus demonios llegan con misiones: diablillo, abisario, súcubo y manáfago; y más adelante, el infernal y el guardia apocalíptico."] = "악마는 퀘스트로 얻어요: 임프, 보이드워커, 서큐버스, 지옥사냥개, 그리고 나중에 지옥불정령과 파멸수호병.",
	["Tus días de caza"] = "내 사냥의 날들",
	["Tus estadísticas"] = "내 능력치",
	["Tus extras"] = "추가 기능",
	["Tus flechas de mejora no usan tu build"] = "향상 화살표가 내 빌드를 쓰지 않음",
	["Tus flechas de mejora usan tu build"] = "향상 화살표가 내 빌드를 씀",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "공격이 두 번째 적에게도 닿습니다. 두 마리가 몰려올 때 딱 좋습니다.",
	["Tus golpes hacen daño sagrado extra. Tu sello de siempre para pelear solo."] = "공격에 신성 피해가 추가돼요. 혼자 싸울 때 늘 쓰는 문장이에요.",
	["Tus golpes sagrados generan más amenaza. Préndela si vas a tanquear."] = "신성 피해가 위협을 더 만들어요. 방어 전담이라면 켜세요.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "외침이 더 멀리 닿고 더 오래 지속되어 파티 전체를 돕습니다.",
	["Tus habilidades cuestan menos ira."] = "기술의 분노 소모가 줄어듭니다.",
	["Tus habilidades de ira te curan: menos descanso."] = "분노 기술이 생명력을 회복시켜 덜 쉽니다.",
	["Tus habilidades nuevas"] = "새 기술",
	["Tus habilidades que tardan en volver, en una barra discreta con lo que les falta."] = "돌아오는 데 오래 걸리는 기술을 남은 시간과 함께 눈에 띄지 않는 막대에.",
	["Tus hechizos de daño pegan más."] = "피해 주문이 더 세집니다.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "냉기 주문이 느리게 만들어 몬스터가 거의 때리지 못합니다.",
	["Tus hechizos fallan menos."] = "주문이 덜 빗나갑니다.",
	["Tus hechizos hacen crítico más seguido."] = "주문이 더 자주 극대화됩니다.",
	["Tus herramientas de combate"] = "내 전투 도구",
	["Tus historias"] = "내 이야기",
	["Tus llaves junto a tus bolsas."] = "가방 옆에 열쇠를 표시합니다.",
	["Tus marcadores"] = "내 마커",
	["Tus marcadores en el mapa de Alfa y en el del juego."] = "Alfa 지도와 게임 지도의 내 마커.",
	["Tus marcadores también en el minimapa, cuando estás cerca."] = "가까이 있으면 미니맵에도 마커를 표시합니다.",
	["Tus marcos de combate volvieron a su lugar de siempre."] = "전투 창이 원래 자리로 돌아갔습니다.",
	["Tus marcos de combate vuelven a su lugar de siempre."] = "전투 프레임이 원래 위치로 돌아갑니다.",
	["Tus marcos de curación están apagados"] = "치유 프레임이 꺼져 있음",
	["Tus marcos están listos"] = "프레임 준비 완료",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "내 순서대로 정한 목표: 아이템, 골드, 전문 기술, 장소...",
	["Tus misiones"] = "내 퀘스트",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "진행 중인 퀘스트를 가장 짧은 길로 끝내고 제출합니다.",
	["Tus misiones aquí"] = "여기서 할 퀘스트",
	["Tus misiones en su voz"] = "리아의 목소리로 듣는 퀘스트",
	["Tus misiones grises valen la pena o no tienes ninguna."] = "회색 퀘스트가 다 가치 있거나 하나도 없어요.",
	["Tus misiones y tus viajes"] = "내 퀘스트와 여행",
	["Tus misiones, raros, mazmorras y niveles de la semana suman en «La semana de la manada» de tu hermandad."] = "이번 주 퀘스트, 희귀, 던전, 레벨이 길드의 '무리의 한 주'에 더해져요.",
	["Tus notas en el mapa"] = "지도 위 내 메모",
	["Tus notas en el mapa, donde las dejas. Un clic en la marca y la flecha te lleva."] = "남긴 곳에 표시되는 지도 위 메모. 표시를 클릭하면 화살표가 안내해요.",
	["Tus notas nuevas también salen en el mapa de los lobos de tu hermandad, y ves las suyas."] = "새 메모는 길드 늑대들의 지도에도 보이고, 그들의 메모도 보여요.",
	["Tus números"] = "내 숫자",
	["Tus oficios"] = "당신의 전문 기술",
	["Tus oficios con su paso de ahora y la guía de cada uno. La guía también se abre con /alfa comercio oficios."] = "현재 단계와 각각의 가이드가 있는 내 전문 기술. 가이드는 /alfa comercio oficios로도 열려요.",
	["Tus perfiles"] = "내 프로필",
	["Tus personajes"] = "내 캐릭터",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "경매장 가격이 오래되었습니다. 다시 스캔하세요.",
	["Tus profesiones"] = "내 전문 기술",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "다음 공격들이 다른 적 하나도 칩니다.",
	["Tus puntos"] = "내 점수",
	["Tus puntos van por otro camino"] = "포인트가 다른 방향으로 찍혀 있음",
	["Tus recargas largas"] = "내 긴 재사용 대기시간",
	["Tus recetas de pescado, la cola de cocina y la fogata."] = "생선 요리법, 요리 대기열, 모닥불.",
	["Tus recetas que dejan ganancia"] = "이득이 나는 내 제조법",
	["Tus spots de farmeo en el mapa, dorados y en su propia capa."] = "내 파밍 장소를 지도에 금색으로, 전용 레이어에.",
	["Tus spots nuevos también salen en el mapa de los lobos de tu hermandad, y ves los suyos."] = "새 파밍 장소는 길드 늑대들의 지도에도 나오고, 나도 그들 것을 봐요.",
	["Tus talentos"] = "내 특성",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "대지, 불, 물, 바람 토템은 길을 따라가며 퀘스트로 얻어요.",
	["Tuya"] = "내 것",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "티란데는 스컬지와 싸우려고 일리단을 풀어 줬고, 그의 간수 마이에브는 그걸 끝내 용서하지 않았어요.",
	["Tótem"] = "토템",
	["Tótems"] = "토템",
	["Tótems enemigos"] = "적 토템",
	["Tú"] = "나",
	["Tú no contestas: actívalo en los ajustes de abajo si quieres ayudar a la manada."] = "답하지 않고 있어요. 무리를 돕고 싶으면 아래 설정에서 켜세요.",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "공격을 받아 내며 파티를 지킵니다. 방패가 필요합니다.",
	["Tú también contestas: si alguien busca algo que llevas, Alfa le dice cuántos tienes (solo eso)."] = "나도 답해요. 누가 내가 가진 걸 찾으면 Alfa가 몇 개 있는지 알려 줘요(그것만).",
	["Ubicación de %s"] = "%s 님의 위치",
	["Ultra"] = "울트라",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "양손에 무기 하나씩과 넘치는 분노: 파티에서 가장 큰 피해를 줍니다.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "큰 양손 무기와 출혈을 일으키는 공격. 가장 쉬운 레벨업 방법입니다.",
	["Un aturdimiento cuando lo necesites."] = "필요할 때 쓰는 기절 기술입니다.",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "퀘스트를 반납할 때마다 짧게 울어요. 기본은 꺼짐.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "세션마다 Alfa를 처음 열 때 게임 자체의 늑대 울음소리.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "우두머리와 처치한 수를 알리고, 클릭 한 번으로 공략을 엽니다.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "장소, 지역, 이동 시간을 담은 짧은 알림.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "상황에 따라 켜지는 기술이 활성화되면 짧게 알립니다. 예: 적이 회피한 뒤의 제압.",
	["Un aviso cuando juntas todo lo de un material o la lista entera."] = "재료 하나나 목록 전체를 다 모으면 알림.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "새 우두머리를 처치하면 알리고, 클릭 한 번으로 전리품을 엽니다.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "알림과 가방 안의 띠로 팔 것, 남겨 둘 것, 찾아갈 상인을 알려 주고, 클릭 한 번으로 잡동사니를 표시합니다.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "재사용 대기시간 동안 아이콘 위에 은은한 어두운 덮개.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "품질 색상의 테두리: 초록, 파랑, 보라...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "추천 기술이 있는 단축바 버튼에 깜박이는 초록 테두리를 띄워 빨리 찾게 합니다.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "흑마법사는 두 명의 도움으로 나머지 파티를 던전 입구로 소환할 수 있어요.",
	["Un buzón"] = "우체통",
	["Un clic bajito cuando Lya te dice algo."] = "Lya가 말할 때 작은 딸깍 소리.",
	["Un clic te pone el conjunto (fuera de combate; en combate, al terminar). Lo que esté en el banco no se puede poner."] = "클릭 한 번이면 구성을 입어요(전투 밖, 전투 중이면 끝난 뒤). 은행에 있는 건 입을 수 없어요.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "클릭 한 번이면 나, 파티, 마커, 가이드의 다음 단계만 남습니다.",
	["Un compañero tiene %s y tú lo puedes quitar, pero ningún clic lo hace. Elige «%s» en Tus clics, en la página Curación."] = "동료에게 %s이(가) 있고 내가 해제할 수 있지만 그런 클릭이 없어요. 치유 페이지의 내 클릭에서 '%s'을(를) 고르세요.",
	["Un consejo"] = "팁",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "내 생명력과 내 직업에 가장 중요한 능력치를 보여 주는 옮길 수 있는 작은 상자입니다. 전투 중에는 게임이 일부 수치를 숨기므로 마지막으로 읽은 값이 남습니다.",
	["Un disparo instantáneo extra. Úsalo mientras corres o para rematar."] = "추가 즉시 사격. 움직이거나 마무리할 때 쓰세요.",
	["Un enemigo"] = "적 하나",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "오류, 개선 의견, 의견을 개발자에게 바로",
	["Un escudo que absorbe daño. Ponlo antes de que te peguen o en quien tanquea."] = "피해를 흡수하는 보호막. 맞기 전에, 또는 방어 전담에게 걸어 주세요.",
	["Un fondo del color de tu clase bajo tu nombre."] = "내 이름 아래에 직업 색상 배경을 깝니다.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "위협 수준이 엄청난 강력한 방패 공격입니다.",
	["Un golpe más para gastar ira."] = "분노를 쓸 공격이 하나 더 생깁니다.",
	["Un golpe nuevo y fuerte para tu barra."] = "단축바에 넣을 새롭고 강한 공격입니다.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "어려운 몬스터를 상대로 피해가 크게 늘고, 공포에서도 풀려납니다.",
	["Un grano fino de cine sobre el mundo."] = "세상 위에 고운 영화 그레인.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "영화 같은 고운 그레인. 부담이 거의 없습니다: 초당 약 14번 움직이며 보일 때만 작동합니다.",
	["Un hechizo de tus barras tiene un rango viejo"] = "단축바에 낮은 레벨 주문이 있음",
	["Un lobo de nivel %d te quiere echar la mano: ve tu nivel, tu zona y tu misión, solo él. Acepta aquí o en La Jauría."] = "%d레벨 늑대가 도와주고 싶어 해요. 그 늑대만 내 레벨, 지역, 퀘스트를 봐요. 여기나 La Jauría에서 수락하세요.",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "하나로 이어진 지도: 확대해도 조각을 붙인 듯한 모습이 더는 보이지 않고, 지형이 선이나 네모 없이 매끄럽게 이어집니다.",
	["Un mapa impecable"] = "흠잡을 데 없는 지도",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "퀘스트에 쓰이는 아이템에 금색 테두리를 표시합니다(퀘스트를 시작하는 아이템은 «!»).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "원하는 아이템: Alfa가 먼저 필요한 것까지 포함해 얻는 길을 만듭니다.",
	["Un paisaje más bonito"] = "더 아름다운 풍경",
	["Un paseíto y unas palabras. Así también se hace manada."] = "짧은 산책과 몇 마디. 이렇게도 무리가 돼요.",
	["Un pescadito asado no me caería nada mal."] = "구운 생선 한 마리면 딱 좋겠어요.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "함께하는 암컷 늑대에게 구운 생선 한 마리, 나쁘지 않겠죠?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "다음 단계들이 안내할 곳에 번호가 붙은 작은 핀을 표시합니다.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "치명타, 회피, 방어도가 조금씩 늘어납니다.",
	["Un poco de vida de vuelta después de críticos."] = "치명타 뒤에 생명력을 조금 회복합니다.",
	["Un poco más de defensa."] = "방어 숙련이 조금 늘어납니다.",
	["Un poco más de ira al cargar."] = "돌진할 때 분노가 조금 더 늘어납니다.",
	["Un punto azul abajo a la derecha si a ese compañero le falta el buff de tu clase. Se revisa fuera de combate."] = "동료에게 내 직업 강화 효과가 없으면 오른쪽 아래에 파란 점. 전투 밖에서 확인해요.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "다음 줄을 열고 조금 덜 빗나가게 하는 1포인트.",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "희귀 몹은 쓰러진 뒤 대략 30분에서 1시간 사이에 다시 나와요. 여기서 당신이나 무리가 언제 잡았는지 볼 수 있어요.",
	["Un raro: %s"] = "희귀 몹: %s",
	["Un rayo que salta entre varios enemigos."] = "여러 적 사이를 튀어 다니는 번개.",
	["Un reto de Lya para esta semana."] = "이번 주 리아의 도전이에요.",
	["Un rincón de %s que todavía no pisas."] = "아직 발을 들이지 않은 %s의 구석.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "근처 서비스, 내 지도의 마커, 지금 있는 곳, 또는 던전 입구.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "내 레벨에 맞는 퀘스트를 주는 NPC 머리 위에 느낌표를 표시합니다.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "완료한 퀘스트를 받는 NPC 머리 위에 물음표를 표시합니다.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "플레이에 필요한 모든 것을 담은 하나의 애드온: 화살표와 경로가 있는 단계별 가이드, 지도, 가방, 빌드, 클릭 치유, 채집, 던전, 낚시, 거래. 모두 같은 스타일입니다.",
	["Un solo día de precios: el historial crece con cada escaneo o búsqueda."] = "하루치 가격뿐이에요. 검색하거나 훑어볼 때마다 기록이 쌓여요.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "세게 때리는 방어 전담: 추가 방어를 조금 포기하는 대신, 피해를 많이 주는 파티를 위해 위협 수준을 많이 쌓습니다. 경험이 조금 있는 방어 전담용입니다.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "경로 페이지에서 만드는 경로에 구간을 하나 더합니다. 얻는 길은 Alfa가 고릅니다.",
	["Un tótem que atrae los golpes de los enemigos. Te da un respiro."] = "적의 공격을 끌어당기는 토템. 숨 돌릴 틈을 줘요.",
	["Un tótem que cura poco a poco a tu grupo."] = "파티를 천천히 치유하는 토템.",
	["Un tótem que hace lentos a los enemigos cercanos. Para escapar o pelear con ventaja."] = "주변 적을 느리게 하는 토템. 도망치거나 유리하게 싸울 때.",
	["Un tótem que le dispara fuego al enemigo. Ponlo al empezar."] = "적에게 불을 쏘는 토템. 시작할 때 세우세요.",
	["Un tótem que quita el miedo, el sueño y el encanto a tu grupo."] = "파티의 공포, 수면, 매혹을 없애는 토템.",
	["Un tótem que reduce el daño que recibes cuerpo a cuerpo."] = "받는 근접 피해를 줄이는 토템.",
	["Un zarpazo fuerte en forma de oso. Genera mucha amenaza."] = "곰 변신 상태의 강력한 일격. 위협을 많이 만들어요.",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Alfa 각 페이지에 리아가 설명해 주는 「?」, 그리고 리아 전용 키.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "지금 쓸 기술을 보여 주는 아이콘입니다. 보여 주기만 하고 절대 대신 누르지 않습니다.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "퀘스트 목록의 퀘스트에 아직 필요한 적과 캐릭터의 이름표에 퀘스트 아이콘을 표시합니다. 던전에서는 게임이 그 정보를 숨겨 표시되지 않습니다.",
	["Un'Goro de día: dinosaurios por todas partes. Yo me quedo atrás de ti, ¿va?"] = "낮의 운고로: 사방에 공룡이에요. 저는 뒤에 있을게요, 알았죠?",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "크게 보이는 추천 행동 하나와 클릭 몇 번이면 되는 내 길.",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "우편함 아래 막대로 우편의 돈과 물품을 클릭 한 번에 받고, 끝나면 받은 것을 보여 줘요.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "우두머리가 곧 쓸 공격과 각각 남은 시간을 보여 주는 막대입니다. 언제 움직이거나 방어할지 알 수 있습니다.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "늑대 인트로가 있는 새 9단계 환영 설정: Alfa 언어(10개)와 Alfa가 대신 해 줄 일을 하나하나 고릅니다.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "문자열 하나에 빌드 전체가 담깁니다. 복사해서 보내면 상대가 붙여 넣습니다.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "골드 금액. 가지고 있으면 달성됩니다.",
	["Una carta con objetos vence pronto"] = "물품이 든 우편이 곧 만료돼요",
	["Una categoría…"] = "분류 하나…",
	["Una cuenta de prueba no puede compartir"] = "체험판 계정은 공유할 수 없음",
	["Una curación muy rápida pero cara. Para emergencias."] = "아주 빠르지만 비싼 치유. 위급할 때용.",
	["Una curación más fuerte. Para cuando la vida baja mucho."] = "더 강한 치유. 생명력이 많이 떨어졌을 때.",
	["Una curación que salta entre tus compañeros heridos."] = "다친 친구들 사이를 튀어 다니는 치유.",
	["Una curación rápida y barata. Perfecta para mantener a todos de pie."] = "빠르고 저렴한 치유. 모두를 버티게 하는 데 딱이에요.",
	["Una curación rápida. Para cuando no hay tiempo."] = "빠른 치유. 시간이 없을 때.",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "비행, 여관, 수리, 은행, 우체통, 내 상급자를 클릭 한 번에 모은 줄.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "다음 목표를 가리키는 화면 화살표와 거리. 끄면: 갈 길은 직접 정합니다.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "가방에서 내 전문화에 향상이 되는 아이템마다 초록색 화살표를 표시합니다.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "내 직업과 레벨 기준으로 지금 착용한 것보다 좋은 장비에 초록 화살표를 표시합니다.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "연두색 띠로 오고 있는 치유량을 보여 줍니다.",
	["Una gran curación para todo el grupo mientras canalizas."] = "정신을 집중하는 동안 파티 전체를 크게 치유해요.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "내 레벨과 지역에 맞는 가이드, 또는 나만의 퀘스트 경로.",
	["Una hora de caza"] = "한 시간의 사냥",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "한 시간 사냥, 연계 퀘스트 경고, 건너뛰기 「되돌리기」, 그리고 남은 가이드 시간.",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "직업에 가장 좋은 보상(또는 가장 비싸게 팔리는 보상)에 발자국과 'Alfa 추천'을 표시해요. 대신 고르지는 않아요.",
	["Una lista de las grises que ya no valen la pena, con «Abandonar» en cada una (tú lo confirmas)."] = "더는 가치 없는 회색 퀘스트 목록. 각각 '포기' 버튼이 있어요(확인은 내가 해요).",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "저처럼 통통한 늑대는 하루 세끼... 그리고 간식이 필요해요.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "방해하지 않으면서 길에서 조언과 응원을 건네는 검은 암컷 늑대. 멋진 강아지를 기리며.",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "자기 늑대를 이렇게 잘 돌보는 늑대는 소시지를 받을 만하지 않아요?",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "목표를 마치면 퀘스트 링크가 담긴 줄, 반납할 수 있게 되면 한 줄, 반납하면 또 한 줄. 파티에서는 Alfa가 있든 없든 모두가 보고, 혼자일 때는 내 채팅에 나와요. 공격대에서는 안 나와요.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "아이콘 아래의 짧은 한 줄. 예: «죽음의 일격: 재사용 대기시간 완료». 각 줄은 4번까지 나온 뒤 조용해지며, ×를 누르면 더 일찍 끌 수 있습니다.",
	["Una línea debajo del aviso con lo que pasó."] = "알림 아래에 무슨 일이 있었는지 한 줄로 표시합니다.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "적이 그 파티원을 노리면 위쪽에 빨간 선으로 알려 줍니다.",
	["Una mano"] = "한손",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "직접 표시하는 목표(추적기나 이 목록의 완료 버튼).",
	["Una misión"] = "퀘스트",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "회색 아이템과 잡동사니로 표시한 것에 동전을 표시합니다.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "새 기술을 배울 수 있으면 가장 가까운 상급자를 메모로 알려 줍니다.",
	["Una piedra de salud para emergencias. Haz una antes de cada mazmorra."] = "위급할 때 쓰는 생명석. 던전마다 미리 만드세요.",
	["Una piedra que deja revivir al morir. Pónsela a quien cura."] = "죽은 뒤 되살아날 수 있게 해 주는 돌. 치유사에게 걸어 주세요.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "모든 모듈을 전면 점검했습니다. 60개가 넘는 수정 사항이 들어갔습니다.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "안정판을 위한 전면 점검: 파티 던전, 전투, 지도, 낚시, 특성 등에서 20개가 넘는 수정.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "경로는 구간으로 이루어진 트리입니다. 경험치, 골드, 직업 퀘스트, 재료, 아이템. 시작하려면 다음 중 하나를 고르세요:",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "경로를 만들려면 내 숙련도로 채집할 수 있는 장소가 3곳 이상 필요합니다. 아래에서 다른 종류나 자원을 고르거나 여기서 채집하세요. Alfa가 찾은 지점을 모두 기록합니다.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "내 숙련도에 맞는 최고의 장소를 도는 경로, 중간에 경험치 퀘스트 몇 개.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "하루 소시지 하나면 늑대가 행복해요. 과학이에요.",
	["Una semana de caza juntos"] = "함께한 사냥 일주일",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "20분 동안 던지지 않거나 새 세션을 시작하면 세션이 끝나고, 낚은 것과 장소가 여기에 나타납니다.",
	["Una sesión tranquila: nada nuevo que contar."] = "조용한 세션: 새로 알릴 것이 없습니다.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "키 하나로 모두: 장비, 미끼, 던지기, 낚아 올리기. 도감, 가이드, 요리, 목표, 통계까지.",
	["Una tormenta de hielo en un área. Ideal contra grupos."] = "지역에 얼음 폭풍을 내려요. 무리에 아주 좋아요.",
	["Una vuelta de recolección en tu zona"] = "내 지역의 채집 한 바퀴",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "내 숙련도로 채집할 수 있는 %d곳을 짧은 순환 경로로 잇고 지도에 그린 뒤, 화살표로 경유지를 차례로 안내합니다.",
	["Unir las capas de sombra"] = "그림자 층 잇기",
	["Unirte al grupo de tus amigos"] = "친구 파티에 참가",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "악몽의 녹색용 하나가 그늘숲의 거대한 나무 곁에 나타나요.",
	["Uno menos"] = "하나 빼기",
	["Uno más"] = "하나 더",
	["Unos %d pasos a tu ritmo"] = "내 속도로 약 %d단계",
	["Unos %s de juego a tu ritmo (%s XP por hora)."] = "내 속도로 약 %s 플레이(시간당 경험치 %s).",
	["Unos materiales: %s."] = "이 재료에 대해: %s.",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "몇몇 하이 엘프는 아직 얼라이언스와 함께해요. 동부 내륙지의 쿠엘다닐에 살아요.",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "지루한 건 나한테 맡기고 싶은 사람도, 다 직접 하고 싶은 사람도 있어요. 말해 줘요. 마음이 바뀌면 언제든 바꿀 수 있어요.",
	["Usa %s"] = "%s 사용",
	["Usa %s: tu tecla lo pone."] = "%s 사용: 키가 달아 줍니다.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "우두머리가 세게 때릴 때 방패 막기를 쓰세요.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "우두머리 전투를 시작할 때 죽음의 소원을 쓰세요.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "죽음의 소원은 쉬운 몬스터가 아니라 어려운 몬스터에게 쓰세요.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "죽음의 일격은 특히 치유 전담에게 쓰세요.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "적이 두 마리 이상 모여 있으면 휩쓸기 일격을 쓰세요.",
	["Usa Ira rabiosa para romper miedos."] = "공포를 풀려면 광전사의 격노를 쓰세요.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "복수가 빛날 때마다 쓰고, 방어구 가르기로 위협 수준을 더하세요.",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "생명력 전환으로 생명력을 대가로 마나를 회복하세요.",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "주문을 시전하는 동안 악마로 몬스터를 붙잡아 두세요.",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "심판을 쓰고 곧바로 문장을 다시 거세요.",
	["Usa el número de abajo en lugar del que detecta el juego."] = "게임이 감지한 값 대신 아래 숫자를 씁니다.",
	["Usa el número de abajo para el blanco normal."] = "기본 흰색에 아래 숫자를 씁니다.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "추천 기술 버튼에 게임 자체의 강조 효과를 씁니다.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "몬스터가 하나면 표범 변신, 여럿이 오면 곰 변신을 쓰세요.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "주력 공격으로 연계 점수를 모으고 마무리 기술에 쓰세요.",
	["Usa tu varita cuando quieras ahorrar maná."] = "마나를 아끼고 싶을 때는 마법봉을 쓰세요.",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "몬스터 두 마리가 몰려오면 군중 제어 주문을 쓰세요.",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "느리고 강한 무기를 쓰세요. 무기 강화 효과가 공격마다 들어갑니다.",
	["Usa una varita para rematar enemigos sin gastar maná."] = "마법봉으로 마나를 쓰지 않고 적을 마무리하세요.",
	["Usar"] = "사용",
	["Usar el banco de Alfa"] = "Alfa 은행 사용",
	["Usar esta"] = "이것 사용",
	["Usar esta guía"] = "이 가이드 사용",
	["Usar la base de datos incluida"] = "기본 제공 데이터베이스 사용",
	["Usar la pesca de Alfa"] = "Alfa 낚시 사용",
	["Usar la piedra"] = "귀환석 사용",
	["Usar las bolsas de Alfa"] = "Alfa 가방 사용",
	["Usar los marcos de Alfa"] = "Alfa 프레임 사용",
	["Usar los pesos de mi build"] = "내 빌드의 가중치 사용",
	["Usar mis talentos de ahora"] = "현재 특성 사용",
	["Usar siempre el mejor"] = "항상 최고 사용",
	["Usar siempre la prioridad de Alfa"] = "항상 Alfa 우선순위 사용",
	["Usar solo una flecha"] = "화살표 하나만 쓰기",
	["Usar también en los marcos de Blizzard"] = "블리자드 프레임에서도 사용",
	["Usar un perfil"] = "프로필 사용",
	["Usar una venda"] = "붕대 사용",
	["Usarlo"] = "사용",
	["Usas el perfil «%s»"] = "«%s» 프로필 사용 중",
	["Usas las bolsas del juego"] = "게임 가방 사용 중",
	["Uso: /alfa comercio precio <enlace del objeto>"] = "사용법: /alfa comercio precio <아이템 링크>",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]"] = "사용법: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa silenciar <número>, /alfa silenciar quitar <número>, /alfa silenciar borrar."] = "사용법: /alfa silenciar <번호>, /alfa silenciar quitar <번호>, /alfa silenciar borrar.",
	["Va a %s"] = "%s행",
	["Vaciar"] = "비우기",
	["Vaciar la lista"] = "목록 비우기",
	["Vacía"] = "비어 있음",
	["Vaelastrasz, un dragón rojo, está preso de Nefarian en la Guarida Alanegra. Antes de pelear contra ti, te presta su fuerza."] = "붉은용 밸라스트라즈는 검은날개 둥지에 갇힌 네파리안의 포로예요. 당신과 싸우기 전에 힘을 빌려줘요.",
	["Vale la pena: abre “%s”"] = "할 만해요: «%s» 퀘스트가 열려요",
	["Vale la pena: da %s"] = "할 만해요: %s 획득",
	["Vallefresno es un bosque precioso. Pero cuida de no enojar a sus espíritus antiguos."] = "잿빛 골짜기는 아름다운 숲이에요. 하지만 고대 정령들을 화나게 하지 않게 조심하세요.",
	["Valor de %s: llevas %s"] = "%s어치 가치: 지금까지 %s",
	["Valor de bloqueo"] = "방패 피해 흡수량",
	["Valor de lo pescado"] = "낚은 것의 가치",
	["Valor de venta"] = "상점 판매가",
	["Valor en la subasta"] = "경매장 가치",
	["Valor exacto"] = "정확한 값",
	["Vamos a %s: sigue la flecha."] = "%s(으)로 가요. 화살표를 따라가세요.",
	["Van: %s"] = "참가: %s",
	["Van: %s."] = "참가: %s.",
	["Variable del juego: %s"] = "게임 변수: %s",
	["Varimathras sirve a Sylvanas en Entrañas. Es un señor del terror, así que nadie sabe cuánto le va a durar la lealtad."] = "바리마트라스는 언더시티에서 실바나스를 섬겨요. 공포의 군주라서 그 충성이 얼마나 갈지 아무도 몰라요.",
	["Varios"] = "기타",
	["Varios enemigos cerca: Nova sagrada los golpea a todos."] = "주변에 적이 여럿: 신성한 폭발로 모두 공격합니다.",
	["Varios enemigos cerca: el cono los golpea y los frena."] = "주변에 적이 여럿: 원뿔 범위로 공격하고 느리게 합니다.",
	["Varios enemigos cerca: el tótem de magma los quema a todos."] = "주변에 적이 여럿: 용암 토템이 모두 태웁니다.",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "가까이에 적이 여럿입니다. 한꺼번에 공격하세요.",
	["Varios enemigos cerca: la ola los golpea y los frena."] = "주변에 적이 여럿: 파동으로 공격하고 느리게 합니다.",
	["Varios enemigos juntos: el huracán los golpea a todos."] = "적이 여럿 모여 있음: 허리케인으로 모두 공격합니다.",
	["Varios enemigos juntos: la ventisca los golpea a todos."] = "적이 여럿 모여 있음: 눈보라로 모두 공격합니다.",
	["Varios enemigos juntos: lluvia de fuego sobre ellos."] = "적이 여럿 모여 있음: 불의 비를 내리세요.",
	["Varios enemigos juntos: quémalos a todos a la vez."] = "적이 여럿 모여 있음: 한 번에 모두 태우세요.",
	["Varios enemigos: consagra el suelo bajo ti."] = "적이 여럿입니다. 발밑에 신성화를 쓰세요.",
	["Varios enemigos: el disparo alcanza a varios."] = "적이 여럿입니다. 사격이 여러 적을 맞힙니다.",
	["Varios enemigos: el rayo salta entre ellos."] = "적이 여럿입니다. 번개가 적 사이를 튑니다.",
	["Varios enemigos: golpéalos a todos."] = "적이 여럿입니다. 모두 공격하세요.",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "적이 여럿입니다. 공격이 적 하나를 더 칩니다.",
	["Varios misiles que no fallan. Bueno cuando el enemigo no se mueve."] = "절대 빗나가지 않는 여러 발의 화살. 적이 가만히 있을 때 좋아요.",
	["Varios puntos juntos: acércate en el mapa para verlos."] = "여러 지점이 모여 있습니다. 지도를 확대해서 확인하세요.",
	["Varita"] = "마법봉",
	["Vas en %d de %d"] = "진행: %d / %d",
	["Vas muy bien. Cada paso cuenta, aunque no lo parezca."] = "아주 잘하고 있어요. 그렇게 느껴지지 않아도 한 걸음 한 걸음이 중요해요.",
	["Vas tras %s"] = "%s 님 추적 중",
	["Ve con cuidado: la presa también muerde."] = "조심해요. 사냥감도 물어요.",
	["Ve quién de tu hermandad busca grupo y pon tu anuncio. Se quita solo en una hora."] = "길드에서 누가 파티를 찾는지 보고 글을 올려요. 한 시간 뒤 저절로 사라져요.",
	["Veces completada"] = "완료 횟수",
	["Veces completadas"] = "완료 횟수",
	["Vegetación"] = "식물",
	["Veinte. Ya te respetan en los caminos."] = "스물. 이제 길에서 다들 당신을 알아봐요.",
	["Vela sagrada"] = "성스러운 양초",
	["Velen, Kil'jaeden y Archimonde guiaban a los eredar. Los dos últimos aceptaron el poder de Sargeras; Velen huyó."] = "벨렌, 킬제덴, 아키몬드는 에레다르를 이끌었어요. 뒤의 둘은 살게라스의 힘을 받아들였고, 벨렌은 도망쳤어요.",
	["Velocidad"] = "속도",
	["Velocidad del zoom"] = "확대/축소 속도",
	["Ven a jugar con la manada, pregunta lo que quieras o cuéntanos si algo falla. Haz clic en el cuadro y cópialo con Ctrl+C (Cmd+C en Mac)."] = "무리와 함께 놀고, 뭐든 물어보거나 문제가 생기면 알려 주세요. 상자를 클릭하고 Ctrl+C(Mac은 Cmd+C)로 복사하세요.",
	["Vence a este jefe para descubrir su nombre y su botín."] = "이 우두머리를 처치하면 이름과 전리품이 공개됩니다.",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "우두머리를 처치해 떨어뜨리는 것을 보거나, 설정에서 스토리 모드를 끄세요.",
	["Vencido"] = "처치함",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "마나도 쓰지 않고 기다리지도 않고 자신을 치유하는 붕대: 모두에게 꼭 필요합니다.",
	["Vende"] = "판매",
	["Vende cañas y cebos"] = "낚싯대와 미끼 판매",
	["Vende lo gris cada vez que pases por un pueblo: es oro fácil y libera espacio."] = "마을을 지날 때마다 회색 아이템을 팔아요. 쉬운 골드에 공간도 생겨요.",
	["Vende lo gris con cualquier vendedor o tira algo que ya no uses."] = "회색 아이템을 아무 상인에게나 팔거나, 더 이상 쓰지 않는 것을 버리세요.",
	["Vende lo que no usas y junta lo que cuesta aprender a montar."] = "안 쓰는 것을 팔아 타기를 배울 돈을 모으세요.",
	["Vende los materiales en montones de 20 o de 10: así es como la gente los compra."] = "재료는 20개나 10개 묶음으로 파세요. 사람들이 그렇게 사거든요.",
	["Vende los objetos grises y lo que marcaste como basura. Nunca lo que marcaste para guardar."] = "회색 아이템과 잡동사니로 표시한 것을 팝니다. 보관으로 표시한 것은 절대 팔지 않습니다.",
	["Vende tu chatarra en este comerciante (%d)."] = "이 상인에게 잡동사니를 팔아요(%d).",
