	["Venenos y críticos: matas rápido, sobre todo atacando por la espalda."] = "독과 치명타: 특히 등 뒤에서 공격하면 빨리 처치합니다.",
	["Ventana de guía oculta. Escribe /alfa guia para volver a verla."] = "가이드 창을 숨겼습니다. /alfa guia를 입력하면 다시 나타납니다.",
