	["Viento"] = "바람",
	["Viernes"] = "금요일",
	["Villa del Lago tiene un puente roto que la gente quiere reconstruir, si alguien le echa la mano."] = "레이크샤이어에는 무너진 다리가 있어서, 누가 도와주면 주민들이 다시 짓고 싶어 해요.",
	["Villa del Lago vive con miedo de los orcos Roca Negra que bajan de las montañas, y también de los gnolls."] = "레이크샤이어는 산에서 내려오는 검은바위 오크와 놀 때문에 두려움 속에 살아요.",
	["Vincular"] = "링크",
	["Violeta"] = "보라색",
	["Visita a un banquero con ese personaje y Alfa la guardará."] = "그 캐릭터로 은행원을 찾아가면 Alfa가 기록을 저장합니다.",
	["Visita a un banquero una vez y Alfa guardará una foto para verlo desde cualquier lugar."] = "은행원을 한 번 찾아가면 Alfa가 기록을 저장해 어디서나 볼 수 있습니다.",
	["Visita a un banquero y Alfa te dirá cuánto cuesta la siguiente casilla de bolsa del banco."] = "은행원을 찾아가면 Alfa가 다음 은행 가방 칸의 가격을 알려 줍니다.",
	["Vista"] = "보기",
	["Vista Eterna es un pueblo goblin en medio de la nieve: aunque haga frío, el negocio no para."] = "눈망루 마을은 눈 한가운데의 고블린 마을이에요. 추워도 장사는 멈추지 않아요.",
	["Vista Eterna tiene casa de subastas neutral, ideal para comerciar con el otro bando."] = "눈망루 마을에는 중립 경매장이 있어서 상대 진영과 거래하기 딱이에요.",
	["Vista mínima al lanzar"] = "던질 때 최소 화면",
