	["Vuelta a entregar"] = "제출 순회",
	["Vuelta a entregar por el camino más corto, la piedra de hogar a tiempo y la mejor recompensa marcada."] = "가장 짧은 길로 퀘스트 제출 순회, 알맞은 때의 귀환석, 가장 좋은 보상 표시.",
	["Vuelta a entregar · Entrega %d de %d"] = "제출 순회 · 제출 %d/%d",
	["Vuelve al valor de fábrica del juego: %s."] = "게임 기본값으로 돌아갑니다: %s.",
	["Vuelve con /alfa guia o desde Aventura > Tu guía."] = "/alfa guia 또는 모험 > 내 가이드에서 다시 열 수 있습니다.",
	["Vuelve en %s"] = "%s 후",
	["World of Warcraft, Warcraft y Blizzard Entertainment son marcas de Blizzard Entertainment, Inc. El arte del juego y del mapa es de Blizzard. Alfa no está afiliado a Blizzard. Discord es marca de Discord Inc."] = "World of Warcraft, Warcraft, Blizzard Entertainment는 Blizzard Entertainment, Inc.의 상표입니다. 게임과 지도의 그림은 Blizzard의 것입니다. Alfa는 Blizzard와 제휴하지 않았습니다. Discord는 Discord Inc.의 상표입니다.",
	["XP"] = "경험치",
	["XP descansada: %d %% de un nivel."] = "휴식 경험치: 1레벨의 %d %%.",
	["XP descansada: %d%% de un nivel"] = "휴식 경험치: 1레벨의 %d%%",
	["XP ganada"] = "얻은 경험치",
	["XP ganada en la sesión: %s"] = "이번 세션 경험치: %s",
	["XP por hora"] = "시간당 경험치",
	["XP por hora en cada sesión"] = "세션별 시간당 경험치",
	["XP por sesión"] = "세션별 경험치",
	["XP/h"] = "경험치/시간",
	["Y %d piezas más necesitan reparación."] = "장비 %d개가 더 수리가 필요합니다.",
	["Y 1 pieza más necesita reparación."] = "장비 1개가 더 수리가 필요합니다.",
	["Y aquí estoy yo"] = "그리고 여기 제가 있어요",
	["Y la tuya tampoco se queda atrás, ¿eh?"] = "당신 애도 만만치 않네요, 그쵸?",
	["Y sin caer ni una vez. ¡Qué manada!"] = "게다가 한 번도 안 쓰러졌어요. 이게 바로 무리죠!",
	["Y una prueba nueva que juega Alfa de punta a punta antes de cada versión, para que estos errores no regresen."] = "또한 버전마다 출시 전에 Alfa를 처음부터 끝까지 플레이하는 새 테스트를 넣어, 이런 오류가 다시 생기지 않게 했습니다.",
	["Ya casi no cabe nada: %d libres. Lo gris es oro fácil con cualquier vendedor."] = "이제 거의 안 들어가요: 빈칸 %d. 회색 아이템은 어느 상인에게나 쉬운 골드예요.",
	["Ya cuidas a 3 aprendices: termina con alguno para adoptar otro."] = "이미 제자 3명을 돌보고 있어요. 다른 제자를 맡으려면 한 명을 끝내세요.",
	["Ya es de madrugada, lobo. Una misión más y a dormir, ¿sí? Azeroth sigue aquí mañana."] = "한밤중이에요, 늑대님. 퀘스트 하나만 더 하고 자요, 알았죠? 아제로스는 내일도 그대로예요.",
	["Ya es de noche. Una buena cacería antes de dormir y luego a descansar."] = "밤이에요. 자기 전에 한 번 멋지게 사냥하고 쉬어요.",
	["Ya es tu aprendiz."] = "이미 내 제자예요.",
	["Ya está en tu registro"] = "이미 퀘스트 목록에 있음",
	["Ya está seleccionada: cópiala con Ctrl+C (Cmd+C en Mac) y pégala donde importes escalas, o compártela."] = "선택되어 있습니다. Ctrl+C(Mac은 Cmd+C)로 복사한 뒤 척도를 가져오는 곳에 붙여 넣거나 공유하세요.",
	["Ya estás en esa guarida."] = "이미 그 굴에 있어요.",
	["Ya estás tocando a una puerta. Espera tantito."] = "이미 문을 두드리고 있어요. 잠깐만 기다리세요.",
	["Ya hay %d calladas."] = "이미 끈 알림: %d개.",
	["Ya hay 1 callada."] = "이미 끈 알림: 1개.",
	["Ya la completaste"] = "이미 완료했습니다",
	["Ya la habías hecho"] = "이전에 완료함",
	["Ya la hice"] = "완료했어요",
	["Ya la hice antes"] = "전에 해 봤어요",
	["Ya la hiciste"] = "이미 함",
	["Ya la hiciste."] = "이미 했습니다.",
	["Ya la sabes"] = "이미 배움",
	["Ya la superaste"] = "이미 레벨이 높음",
	["Ya la terminaste: entrégala dentro de la mazmorra."] = "완료했습니다. 던전 안에서 제출하세요.",
	["Ya la tienes"] = "보유 중",
	["Ya la tienes: entrégala a %s."] = "이미 받았습니다. %s에게 완료하세요.",
	["Ya la tienes: tu guía te lleva a entregarla."] = "이미 받았습니다. 가이드가 완료하러 안내합니다.",
	["Ya le preguntaste a la manada hace poco. Te aviso si alguien abre su guarida."] = "방금 무리에게 물어봤어요. 누가 굴을 열면 알려 줄게요.",
	["Ya llamaste a la manada hace un momento. Espera un poco."] = "방금 무리를 불렀어요. 조금 기다려요.",
	["Ya llegaste"] = "도착했습니다",
	["Ya llevas %d de sus misiones: te llevo a la entrada."] = "이미 퀘스트 %d개를 받았습니다. 입구로 안내합니다.",
	["Ya llevas 1 de sus misiones: te llevo a la entrada."] = "이미 퀘스트 1개를 받았습니다. 입구로 안내합니다.",
	["Ya llevas puesto «%s»."] = "이미 '%s'을(를) 입고 있어요.",
	["Ya lo tienes"] = "이미 있음",
	["Ya no"] = "그만",
	["Ya no aplica"] = "더 이상 해당 없음",
	["Ya no da XP"] = "더 이상 경험치 없음",
	["Ya no da experiencia"] = "더 이상 경험치를 주지 않음",
	["Ya no eres aprendiz"] = "이제 수습이 아니에요",
	["Ya no está en esa guarida."] = "더는 그 굴에 없어요.",
	["Ya no está en tu registro"] = "더 이상 퀘스트 목록에 없음",
	["Ya no está sobre un cuadro negro: la acompañan una sombra suave y una elipse del color de tu estilo."] = "이제 검은 상자 위에 있지 않습니다. 부드러운 그림자와 내 스타일 색의 타원이 함께합니다.",
	["Ya no hay nada más que aprender. ¡Qué orgullo!"] = "더 배울 게 없어요. 정말 자랑스러워요!",
	["Ya no queda nada por hacer aquí. Elige qué sigue y la manada va contigo."] = "여기서 더 할 일이 없어요. 다음 할 일을 고르면 무리가 함께해요.",
	["Ya no se consigue"] = "더 이상 얻을 수 없음",
	["Ya no se consiguen"] = "더 이상 얻을 수 없음",
	["Ya no se puede deshacer"] = "이제 되돌릴 수 없어요",
	["Ya no te dan casi experiencia y no abren nada que valga la pena. Abandónalas para tener espacio en tu registro."] = "경험치를 거의 안 주고 쓸 만한 걸 열어 주지도 않아요. 퀘스트 목록에 자리를 만들려면 포기하세요.",
	["Ya no te queda ninguna casilla libre."] = "빈 칸이 하나도 없어요.",
	["Ya puedes aprender el rango %s"] = "이제 %s 단계를 배울 수 있습니다",
	["Ya puedes entregarla."] = "이제 제출할 수 있습니다.",
	["Ya puedes hacer venenos. Ponlos en tus armas: suman mucho daño."] = "이제 독을 만들 수 있어요. 무기에 바르면 피해가 크게 늘어요.",
	["Ya puedes salir del grupo: la guarida se queda contigo."] = "이제 파티를 나가도 돼요. 굴은 그대로예요.",
	["Ya salió Alfa %s"] = "Alfa %s 출시",
	["Ya salió una versión nueva de Alfa"] = "Alfa 새 버전 출시",
	["Ya se está buscando, espera un momento."] = "이미 검색 중입니다. 잠시 기다리세요.",
	["Ya se usa: clic otra vez"] = "이미 사용 중: 다시 클릭",
	["Ya te conté todo lo que sé por ahora. Con clic derecho puedo empezar de nuevo."] = "지금 아는 건 다 말했어요. 오른쪽 클릭하면 처음부터 다시 시작할 수 있어요.",
	["Ya te dejé prendido lo que le va a tu clase. Agrega o quita lo que quieras: nada de esto juega por ti."] = "직업에 맞는 건 이미 켜 뒀어요. 원하는 걸 더하거나 빼세요. 이건 대신 플레이하지 않아요.",
	["Ya terminaste Armas: estos puntos van a Furia por más golpe crítico."] = "무기 계열을 다 찍었습니다. 이 포인트는 치명타를 위해 분노 계열에 찍습니다.",
	["Ya tienes %d conjuntos: olvida uno primero."] = "이미 구성이 %d개예요. 먼저 하나를 지우세요.",
	["Ya tienes %d de %s. Te faltan %d de %d materiales."] = "지금 %d %s 있어요. 재료 %d/%d개 부족.",
	["Ya tienes %d talentos de este plan."] = "이 계획의 특성을 이미 %d개 찍었습니다.",
	["Ya tienes 1 talento de este plan."] = "이 계획의 특성을 이미 1개 찍었습니다.",
	["Ya tienes 3 citas propuestas. Quita una para proponer otra."] = "이미 약속을 3개 제안했어요. 하나를 지워야 새로 제안할 수 있어요.",
	["Ya tienes 60 notas. Borra alguna en La Jauría para dejar otra."] = "메모가 이미 60개예요. 새로 남기려면 La Jauría에서 하나를 지우세요.",
	["Ya tienes algo mejor"] = "이미 더 좋은 것이 있음",
	["Ya tienes demasiados builds importados. Borra alguno primero."] = "가져온 빌드가 너무 많습니다. 먼저 하나를 삭제하세요.",
	["Ya tienes el rango más alto"] = "최고 단계예요",
	["Ya tienes la equitación"] = "이미 타기를 배웠습니다",
	["Ya tienes las %d casillas de bolsa del banco. Para más espacio, pon bolsas más grandes en ellas."] = "은행 가방 칸 %d개를 이미 모두 샀습니다. 공간을 늘리려면 더 큰 가방을 넣으세요.",
	["Ya tienes seis guías abiertas: cierra una y vuelve a intentar."] = "가이드 6개가 이미 열려 있습니다. 하나를 닫고 다시 시도하세요.",
	["Ya tienes todos los materiales. ¡A trabajar!"] = "재료가 다 있어요. 시작해요!",
	["Ya tienes todos los talentos de este build. ¡Bien hecho!"] = "이 빌드의 특성을 모두 찍었습니다. 잘했어요!",
	["Ya tienes tu montura"] = "이미 탈것이 있습니다",
	["Ya van %d veces. La manada aúlla contigo."] = "벌써 %d번째입니다. 무리가 함께 울부짖습니다.",
	["Ya van %s de cacería. Un descanso corto también es de lobos sabios."] = "벌써 %s째 사냥 중이에요. 짧은 휴식도 현명한 늑대가 하는 일이에요.",
	["Ya vencieron a todos sus jefes. Si tienes misiones listas, entrégalas al salir."] = "모든 우두머리를 처치했습니다. 완료한 퀘스트가 있으면 나가는 길에 제출하세요.",
	["Ya vienen elegidas según tu clase y tu rol. Cámbialas si prefieres otra cosa."] = "직업과 역할에 맞게 미리 골라 두었습니다. 다른 것이 좋으면 바꾸세요.",
	["Yo correría por tu cuerpo."] = "저라면 시체로 달려가겠어요.",
	["Yo decido"] = "내가 정해",
	["Yo huelo el rastro; tú pones los colmillos."] = "냄새는 제가 맡고, 송곳니는 당신이 써요.",
	["Ysera, la Soñadora, cuida el Sueño Esmeralda: un reflejo de Azeroth como sería sin la mano de los mortales."] = "꿈꾸는 자 이세라는 에메랄드의 꿈을 지켜요. 필멸자의 손이 닿지 않았다면 아제로스가 어땠을지 비춘 세계예요.",
	["Zepelín de %s"] = "%s 비행선",
	["Zona"] = "지역",
	["Zona %d"] = "지역 %d",
	["Zona desconocida"] = "알 수 없는 지역",
	["Zona o raza"] = "지역 또는 종족",
	["Zona sin nombre"] = "이름 없는 지역",
	["Zonas"] = "지역",
	["Zonas de enemigos, objetos y lugares de las misiones de tu registro."] = "퀘스트 목록에 있는 퀘스트의 적, 아이템, 장소 구역입니다.",
	["Zonas sin descubrir"] = "미발견 지역",
	["Zonas: %s."] = "지역: %s.",
	["Zul'Farrak es la ciudad de los trols Furiarena, los trols del desierto."] = "줄파락은 사막 트롤인 성난모래 트롤의 도시예요.",
	["Zul'Gurub fue la capital del imperio Gurubashi. Sus sacerdotes llamaron a Hakkar, el Desollador de Almas, y casi pierden todo."] = "줄구룹은 구루바시 제국의 수도였어요. 사제들이 영혼의 학살자 학카르를 불러내고는 모든 걸 잃을 뻔했어요.",
	["Zul'jin, el gran cazador Amani, se unió a la Horda en la Segunda Guerra con un solo deseo: vengarse de los altos elfos."] = "아마니의 위대한 사냥꾼 줄진은 하이 엘프에게 복수하겠다는 단 하나의 바람으로 2차 대전쟁 때 호드에 합류했어요.",
