	["{dia}/{mes}"] = "{mes}월 {dia}일",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "오늘 제출한 퀘스트 %d개! 이게 무리의 사냥이에요.",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "오늘 퀘스트 %d개! 이러다 소시지 하나 빚지겠어요.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "오늘 퀘스트 %d개! 아무도 못 말려요.",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s 최대치: %d/%d! 더 배울 게 없어요. 정말 자랑스러워요.",
	["¡%s cazó a %s!"] = "%s 님이 %s 사냥!",
	["¡%s es tu aprendiz!"] = "%s 님이 내 제자가 됐어요!",
	["¡%s llegó al nivel %d!"] = "%s 님이 %d레벨을 달성했어요!",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s님이 %d레벨이 됐어요! 아우우, 축하해요.",
	["¡%s tiene su primera montura!"] = "%s 님이 첫 탈것을 얻었어요!",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s, 이제 행복해요! 함께 사냥하는 맛이 이런 거죠.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! 며칠 만이에요. 오늘에서 어디까지 했는지 알려 줄게요.",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s! 뭔가에 맞으면 탱커 쪽으로 달려요, 멀리 말고요.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s! 정말 보고 싶었어요. 오는 걸 보자마자 달려왔어요.",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s, 해냈어요! 무리가 당신을 위해 울어요. 아우우우. 제 소시지는요?",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, 돌아왔군요! 너무 보고 싶어서 꼬리를 멈출 수가 없었어요.",
	["¡Abrumar!"] = "제압!",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "이제 혀를 내밀고 당신 뒤를 달려갈게요!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "거기 있었네요, %s! 조언이 필요하면 저를 클릭하세요.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "거기 있었네요, %s! 계속 기다렸어요… 보고 싶었어요.",
	["¡Al máximo!"] = "최대치!",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "일어나요, 늑대! 다시 싸우기 전에 생명력과 마나를 회복하세요.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "일어나요, 늑대! 쓰러지는 것도 사냥의 일부예요. 되살아나면 장비를 수리하세요.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "일어나요, 늑대! 영혼을 해방하세요. 시체로 갈지 영혼의 치유사에게 갈지 화살표가 알려 줘요.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "일어나요, 늑대! 너무 많았다면 다음엔 하나씩 끌어요.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "레벨 업, %d레벨! 남은 특성 점수가 있으면 잊지 마세요.",
	["¡Así se ve un aviso!"] = "알림은 이렇게 보입니다!",
	["¡Ataque de la victoria!"] = "연전연승!",
	["¡Auuu! Juntas cazamos mejor."] = "아우우! 같이 사냥하면 더 잘해요.",
	["¡Auuu! Toda la manada está de fiesta."] = "아우우! 무리 모두가 축하해요.",
	["¡Auuuu! La manada unida no se rinde."] = "아우우우! 뭉친 무리는 포기하지 않아요.",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "아우우! %d레벨, 30분도 안 돼서 두 레벨이나! 보름달 아래 늑대 같아요.",
	["¡Bien hecho! %s"] = "잘했어요! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "좋은 아침, %s! 아제로스에 해가 떴어요. 가 볼까요?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "좋은 저녁이에요, %s! 우리 늑대들은 밤에 제일 사냥을 잘해요.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "좋은 오후예요, %s! 퀘스트 하기 딱 좋은 시간이에요.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "안녕하세요, %s! 한 걸음씩 가면 멀리 가요.",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "좋은 아침이에요! 든든하게 먹고 사냥하러 가요. 아침은 시간이 넉넉해요.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "좋은 아침이에요, %s! 기지개 켜고 하품하면 준비 끝이에요.",
	["¡Bájale, casi se lo quitas al tanque!"] = "살살 해요, 방어 전담에게서 뺏기 직전이에요!",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "물론이죠! 소환수를 부르면 인사하고, 사냥꾼이면 배고프거나 불만일 때 먹이를 주라고 알려 줄게요.",
	["¡Completaste %s!"] = "%s 완료!",
	["¡Contraataque!"] = "역습!",
	["¡Cumplido! Salchicha ganada."] = "완료! 소시지 획득.",
	["¡Córtale a tu foco!"] = "주시 대상을 차단하세요!",
	["¡Córtalo!"] = "차단하세요!",
	["¡De vuelta con la manada!"] = "무리로 돌아오셨군요!",
	["¡De vuelta en la manada, %s!"] = "무리로 돌아온 걸 환영해요, %s!",
	["¡Ejecutar!"] = "마무리 일격!",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "텔사마에서 순대를 팔아요! 텔사마 순대는 거의 소시지예요... 하나 사 줄래요?",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "할로윈 축제예요! 여관주인에게 사탕을 달라고 해 보세요. 가끔 웃긴 모습으로 변신시켜 줘요.",
	["¡Es ahora! Hasta las %s"] = "지금 진행 중! %s까지",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "한여름 불꽃축제예요! 도시의 화톳불을 찾아가 그 불꽃을 기려요.",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "잠깐요! 완료한 퀘스트 %d개를 제출 안 하고 가요. 지금 안 하면 다음에 거기서부터 시작해요.",
	["¡Esto le sirve a %s!"] = "%s에게 쓸모 있어요!",
	["¡Está lanzando!"] = "시전 중이에요!",
	["¡Explorada completa!"] = "탐험 완료!",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "%d레벨 축하해요, %s! 아우우.",
	["¡Feliz cumpleaños!"] = "생일 축하해요!",
	["¡Feliz cumpleaños, Alfa!"] = "생일 축하해요, Alfa!",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "고마워요! 벌써 소시지 %d개째예요. 다 세고 있다고요.",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "또 만나요! 여기서 자리 지키며 기다릴게요.",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "또 만나요! 오늘의 사냥: %s 여기서 기다릴게요.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Alfa에 새로운 게 있어요: %s! 보여 줄까요?",
	["¡Hola!"] = "안녕하세요!",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "안녕! Alfa에 대해 뭐든 물어봐요. 짧게 설명하고 데려갈게요.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "안녕하세요! 저는 알파가 믿는 암컷 늑대 Lya예요. 무리를 지키고 길을 함께 걸어요.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "안녕! 나는 알파의 믿음직한 늑대 리아예요. 이 설정과 그다음 여정을 함께할게요.",
	["¡Hola, %s!"] = "안녕하세요, %s 님!",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "안녕, %s! %s 계열에 좋은 혈통이네요. 우리 둘이 우리 알파를 지켜요.",
	["¡Hola, %s! Hoy huele a buena cacería."] = "안녕하세요, %s! 오늘은 좋은 사냥 냄새가 나요.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "안녕하세요, %s! 오후가 평화로워 보여요. 오늘은 뭘 사냥할까요?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "안녕하세요, %s! 달밤이네요. 무리에게 딱이에요.",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "안녕, %s! 우리 둘이 우리 알파를 지켜요.",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "오늘 Alfa가 %d살이 됐어요! La Jauría가 당신을 위해 정성껏 만들었어요. 소시지로 축하할까요?",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "오늘 Alfa가 1살이 됐어요! La Jauría가 당신을 위해 정성껏 만들었어요. 소시지로 축하할까요?",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "오늘로 함께 사냥한 지 %d년이에요, %s! 당신의 늑대가 되게 해 줘서 고마워요. 아우우우.",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "오늘로 함께 사냥한 지 1년이에요, %s! 당신의 늑대가 되게 해 줘서 고마워요. 아우우우.",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "%s의 리아가 인사에 답했어요! 이제 우린 무리예요.",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "%s의 리아가 저한테 인사했어요! 암늑대끼리는 통해요.",
	["¡Le encantan! Pero las mías son más ricas."] = "정말 좋아하네요! 그래도 제 게 더 맛있어요.",
	["¡Listo! %s precios guardados."] = "완료! 가격 %s개를 저장했습니다.",
	["¡Listo! Alfa ya es tuyo"] = "완료! 이제 나만의 Alfa입니다",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "겨울맞이 축제가 왔어요! 아이언포지와 오그리마의 나무가 불빛과 선물로 가득해요.",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "해냈어요: %s! 그 상 소시지는 천천히 먹을래요.",
	["¡Lo tienes! %s ×%d"] = "낚았어요! %s ×%d",
	["¡Martillo de cólera!"] = "천벌의 망치!",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "함께한 첫 소시지예요! 이건 절대 안 잊을 거예요.",
	["¡Misión completada: %s!"] = "퀘스트 완료: %s!",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "음, 맛있다! 고마워요, 무리에서 최고의 늑대예요.",
	["¡Mordedura de mangosta!"] = "살쾡이의 이빨!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "%d레벨! 잠깐 자랑해도 돼요. 당신이 해낸 거예요.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "%d레벨! 단단한 걸음, 날카로운 송곳니.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "%d레벨! 노력이 보여요. 계속 이렇게 가요.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "%d레벨! 아우우! 이게 무리가 크는 방식이에요.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "%d레벨, 잘했어요! 상급자에게 새로 배울 게 있는지 보세요.",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "%d레벨, 방금 올랐는데 또! 두 번 울게요, 한 번씩. 아우우, 아우우!",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "10레벨! 이제 특성이 있어요. 천천히 고르세요. 특성 페이지가 도와줘요.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "20레벨! 이제 진짜 던전도 갈 수 있어요. 파티를 꾸릴까요?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "30레벨! 벌써 절반이에요. 무리가 정말 자랑스러워해요!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "40레벨! 이제 타기를 배울 수 있어요. 첫 탈것이 기다려요!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "50레벨! 정상이 코앞이에요. 다가올 일을 위해 골드를 모으세요.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "60레벨! 해냈어요, 알파! 이제 큰 사냥을 할 차례예요.",
	["¡Nueva página en tu historia: %s! %s"] = "이야기에 새 페이지: %s! %s",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "새 기록: 하루에 퀘스트 %d개! 무리도 못 따라와요.",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "조심하세요! 가격이 가치보다 %d %% 낮아요.",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "벌써 또 레벨 업! %d레벨. 아우우, 이 기세는 아무도 못 막아요!",
	["¡Perdiste su atención!"] = "적의 관심을 잃었어요!",
	["¡Plan cumplido!"] = "계획 완료!",
	["¡Plan terminado!"] = "계획 완료!",
	["¡Primera vez! Nuevo en tu diario"] = "처음! 도감에 새로 등록",
	["¡Qué buena racha traes! Sigue así."] = "기세가 대단해요! 계속 이렇게 가요.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "돌아와서 정말 반가워요, %s! 저는 여전히 여기서 등 뒤를 지키고 있어요.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "다시 만나서 반가워요! 이번 버전이 나와 내 무리에게 가져온 것들이에요.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "만나서 반가워요, %s! 무리가 기다리고 있었어요.",
	["¡Repara tu equipo!"] = "장비를 수리하세요!",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "도전 완료: %s! 제가 소시지를 벌었어요... 아니, 당신이 번 거죠. 좋아요, 우리가 번 걸로 해요.",
	["¡Revancha!"] = "복수!",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "소시지! *꼬리를 엄청 빨리 흔들며* 고마워요, 고마워요.",
	["¡Salimos de %s! %s adentro."] = "%s에서 나왔어요! 안에서 %s.",
	["¡Salimos de la mazmorra! %s adentro."] = "던전에서 나왔어요! 안에서 %s.",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "예순! 해냈어요. 나한테 거대한 소시지 하나 빚졌어요.",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "%d레벨이 됐어요! 레벨마다 더 강해져요.",
	["¡Sí, acompáñame!"] = "응, 함께해 줘!",
	["¡Te está atacando a ti!"] = "나를 공격하고 있어요!",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "보고 싶었어요, %s! 보려고 여기까지 달려왔어요.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "보고 싶었어요, %s! 경로는 두고 간 그대로예요.",
	["¡Terminaste %s!"] = "완료했습니다: %s!",
	["¡Terminaste esta guía!"] = "이 가이드를 끝냈어요!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "이 가이드를 끝냈습니다! 다음 가이드를 골라 무리와 함께 계속 레벨을 올리세요.",
	["¡Terminaste tu guía!"] = "가이드를 끝냈습니다!",
	["¡Tienes todo!"] = "다 있어요!",
	["¡Tierra a la vista! La manada desembarca en %s"] = "육지다! 무리가 %s에 상륙해요",
	["¡Tierra a la vista: %s!"] = "육지가 보인다: %s!",
	["¡Todo listo para la mazmorra!"] = "던전 준비 완료!",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "%s %d/%d 달성! 이제 %s 등급을 배울 수 있어요.",
	["¡Tu lista de compras está completa!"] = "장보기 목록 완성!",
	["¡Tú!"] = "당신!",
	["¡Va! Te lo sigo diciendo, con gusto."] = "좋아요! 기꺼이 계속 알려 줄게요.",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "오늘 퀘스트 %d개! 무리가 자랑스러워해요.",
	["¡Volviste, %s! Estira las patas y vámonos."] = "돌아왔네요, %s! 다리 쭉 펴고 가요.",
	["¡Voy!"] = "갈게!",
	["¡Vuelta completa!"] = "순회 완료!",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "이제 %d레벨! 무리가 당신을 위해 울부짖어요.",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "%s에 왔어요! 탱커가 먼저 끌게 하고 치유사 가까이 있어요.",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "던전에 왔어요! 탱커가 먼저 끌게 하고 치유사 가까이 있어요.",
	["¡Ya estás en la %s!"] = "%s에 도착했어요!",
	["¡Ya estás en otro plano!"] = "이제 다른 레이어예요!",
	["¡Ya la desbloqueaste!"] = "해금했어요!",
	["¡Ya llegaste al 60!"] = "60레벨 달성!",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "왔군요, %s! 보고 싶었어요. 오늘은 어디로 갈까요?",
	["¡Ya llegó! Vamos, manada"] = "도착! 가자, 무리여",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "퀘스트를 %d개 끝냈어요! 보상 받으러 가요.",
	["¡Ya!"] = "지금!",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "내가 저장해 뒀어요! 이야기에서 퀘스트들이 들려준 걸 언제든 읽을 수 있어요.",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "냠! 이걸로 %d개째. 아제로스에서 제일 좋아하는 사람이에요.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "«%s»에는 사연이 있어요. 들려줄까요?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "«%s» 끝났어요. 결말이 들을 만해요. 들려줄까요?",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "'%s': 소식을 전하고 기다리는 사람과 이야기하면 돼요.",
	["«%s»: toca %s."] = "'%s': 이제 %s 차례예요.",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "편의 기능의 «카메라 더 멀리 빼기»가 켜져 있어 접속할 때 이 값보다 우선합니다.",
	["«Buscar cerca» en la página Hoy"] = "오늘 페이지의 «근처 찾기»",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "«근처 찾기»는 필요한 곳으로 화살표로 안내하고, «내 계획»은 자동으로 체크되는 나만의 목표를 만듭니다.",
	["«Camino al 60» en Hoy"] = "오늘의 '60까지의 길'",
	["«Cerrar mis misiones» está al día"] = "«내 퀘스트 끝내기»가 최신 상태입니다",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "«Alfa와 같게»는 설정 > 외형의 스타일을 따르고 함께 바뀝니다.",
	["«Invitar al clan» en el clic derecho"] = "우클릭 메뉴에 '길드 또는 커뮤니티에 초대'",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "'데려가 줘…'(경로 페이지, 내 단축키, /alfa llevame): 장소를 고르면 비행, 배, 비행선, 차원문으로 구간마다 데려가요.",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "'데려가 줘'는 이 단계로 화살표를 가리키고, '다음'은 완료로 표시하고 다음으로 넘어가요.",
	["«Ponte esto» con el equipo mejor"] = "더 좋은 장비에 '이거 입어요'",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "'이거 입어요', 장보기 목록, 전문 기술 1~300, 쉬운 경매.",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "«준비하기»는 지금 받을 수 있는 퀘스트만 받고 입구로 안내합니다.",
	["«Reportar» ya los lleva."] = "'보고'에 이미 들어 있어요.",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "La Jauría의 '따라가기'가 가이드 단계가 바뀌거나 시체로 달려가는 동안에도 풀리지 않습니다. 끝나면 화살표가 따라가던 사람에게 다시 향합니다.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "«항상»은 마법부여사 친구가 도와줄 때 쓰세요. 마력 추출 표는 추정치입니다.",
	["«Tomar todo» en el buzón"] = "우편함의 '모두 받기'",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "우편함의 '모두 받기', 시간당 골드, 가방이 거의 찼을 때 알림.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "«다음 보기»로 다음 단계를 미리 볼 수 있고, 미리 보는 중이라고 분명히 알려 줍니다. 완료한 단계 수도 하나로 통일했습니다.",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "파티 채팅에 「[퀘스트] 반납 가능」과 「퀘스트 완료!」를 모두에게. 끄면 나만 봐요.",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "「[퀘스트] 반납 가능」과 「퀘스트 완료!」. 파티에서는 모두가 보고, 혼자일 때는 내 채팅에 나와요.",
