	["¿En qué te ayudo? Toca una pregunta o una página y te cuento."] = "무엇을 도와줄까? 질문이나 페이지를 누르면 알려 줄게요.",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "이 냄새, 여관 빵이에요? 제 코는 절대 틀리지 않아요.",
	["¿Estoy listo para la mazmorra?"] = "던전 갈 준비가 됐나요?",
