	["¿Qué retos tengo esta semana?"] = "이번 주 도전은 뭐예요?",
	["¿Qué sigue?"] = "다음은?",
	["¿Qué talentos pongo?"] = "특성은 뭘 찍어?",
	["¿Reiniciar los gráficos?"] = "그래픽을 다시 시작할까요?",
	["¿Restaurar este respaldo?"] = "이 백업을 복원할까요?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "암컷 늑대가 무리에서 귀가 제일 밝은 거 알아요? 음, 제 말로는 그래요.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "알고 있었나요? Alfa는 완료한 퀘스트를 짧은 경로 하나로 묶어 줘요.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "알고 있었나요? Alfa에는 스타일이 세 가지 있어요: Alfa, WoW 클래식, 유리. 저도 고른 스타일을 입어요.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "알고 있었나요? 아이템을 Alt+클릭하면 백과사전에서 열려요.",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "알고 있었나요? 근처 찾기는 가장 가까운 대장장이, 은행, 비행 조련사로 안내해요.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "알고 있었나요? 거래는 상인에게 팔지, 경매에 올릴지, 가공할지 알려 줘요.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "알고 있었나요? /alfa reportar로 toxic3000에게 오류나 아이디어를 전할 수 있어요.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "알고 있었나요? 낚시 기능으로 키 하나로 던지고 낚아 올려요.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "알고 있었나요? 저를 오른쪽 클릭하면 한 시간 동안 조용히 시키거나 조언을 줄일 수 있어요.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "알고 있었나요? 미니맵 버튼으로 Alfa 전체를 숨기고 다시 불러올 수 있어요.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "알고 있었나요? Alfa 지도는 지형, 내 마커, 근처에 있는 것을 보여 줘요.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "알고 있었나요? 가방에서 내 가방, 은행, 모든 캐릭터의 물건을 볼 수 있어요.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "알고 있었나요? La Jauría에서 내 파티와 Alfa를 쓰는 무리를 볼 수 있어요.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "알고 있었나요? 내 계획에서 나만의 목표 목록을 만들면 화살표가 안내해요.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "알고 있었나요? 특성에서 지금 찍을 특성과 그 이유를 볼 수 있어요.",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "알고 있었나요? 백과사전은 모든 아이템, NPC, 퀘스트를 어디서 찾는지 알려 줘요.",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "알고 있었나요? 오늘 페이지는 지금 할 일과 캐릭터의 급한 일을 알려 줘요.",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "알고 있었나요? 던전은 내 차례인 던전과 준비하는 법을 알려 줘요.",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "알고 있었나요? 채집은 지도에 광석, 약초, 물고기 떼를 표시해 줘요.",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "제가 제일 좋아하는 음식이 소시지라고 말했던가요? 그 무엇도 못 따라와요.",
	["¿Te llevas bien con mi mascota?"] = "제 소환수랑 잘 지내요?",
	["¿Te puedes hacer a un lado en las peleas?"] = "전투 중에는 비켜 줄 수 있어요?",
	["¿Una carrerita hasta allá? Yo gano."] = "저기까지 달리기 시합할래요? 제가 이길 거예요.",
	["¿Usar tu hechizo nuevo?"] = "새 주문을 쓸까요?",
	["¿Usar «%s»?"] = "«%s»을(를) 쓸까요?",
	["¿Vaciar tu lista de compras?"] = "장보기 목록을 비울까요?",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "판매, 경매, 제작? (escanear: 스캔, precio <아이템>: 가격)",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>, oficios)"] = "상인, 경매, 아니면 제작? (escanear = 훑어보기, precio <아이템> = 가격, oficios = 전문 기술)",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "판매, 경매, 제작? 아이템마다 골드를 가장 많이 버는 방법을 알려 줍니다.",
	["¿Volver a lo de antes?"] = "이전으로 되돌릴까요?",
	["¿Y el siguiente?"] = "그다음은요?",
	["¿Y si me sale algo que le sirve a otro lobo?"] = "다른 늑대에게 쓸모 있는 게 나오면요?",
	["¿Y si pierdo mis ajustes?"] = "설정을 잃어버리면 어떡하죠?",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "%s 구석구석 다 둘러봤어요? 볼 곳은 늘 남아 있어요.",
	["¿Ya hiciste esta mazmorra?"] = "이 던전을 이미 해 봤나요?",
	["¿Ya te vas? Descansa bien. Yo me quedo vigilando hasta que vuelvas."] = "벌써 가요? 푹 쉬어요. 돌아올 때까지 제가 지키고 있을게요.",
	["¿Ya viste cómo caza %s? Me cae bien."] = "%s 사냥하는 거 봤어요? 마음에 들어요.",
	["¿qué quieres hacer?"] = "무엇을 할까요?",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "게임 메뉴 바의 버튼으로 여세요. 오른쪽 아래에 있는 작은 버튼 줄입니다.",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "특성 키(%s)나 게임 메뉴에서 여세요.",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "특성 키나 게임 메뉴에서 여세요.",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "유산 키(%s)나 게임 메뉴 바의 버튼으로 여세요.",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "/alfa 또는 미니맵의 늑대로 여세요. 이 설정을 바꾸려면: /alfa bienvenida.",
	["Ámbar"] = "호박색",
	["Ángel de la resurrección"] = "영혼의 치유사",
	["Ángeles de la resurrección"] = "영혼의 치유사",
	["Árboles, rocas, cercas y adornos: más alto, se ven completos desde más lejos."] = "나무, 바위, 울타리, 장식물: 높일수록 더 먼 곳에서도 온전히 보입니다.",
	["Área"] = "광역",
	["Échale la mano a un lobo nuevo"] = "새 늑대를 도와줘요",
	["Élite"] = "정예",
	["Épico"] = "영웅",
	["Éxito"] = "성공",
	["Ícono"] = "아이콘",
	["Ícono de rotación"] = "로테이션 아이콘",
	["Ícono del tipo de perjuicio"] = "약화 효과 종류 아이콘",
	["Ícono sobre el corcho"] = "찌 위 아이콘",
	["Íconos de ayuda"] = "도움 아이콘",
	["Íconos limpios y tus recursos en el mapa"] = "깔끔한 아이콘과 지도 위의 자원",
	["Íconos sin bordes negros: el mapa y las ventanas de Alfa se ven limpios al hacer zoom o al teñirse de color."] = "검은 테두리 없는 아이콘: 확대하거나 색이 입혀져도 지도와 Alfa 창이 깔끔하게 보입니다.",
	["Ídolo"] = "우상",
	["Ñam. Esto me da energía para cuidarte otras tres horas."] = "냠. 이걸로 세 시간은 더 지켜 줄 힘이 나요.",
	["×%d"] = "×%d",
	["Última posición enviada %s."] = "마지막 위치 전송: %s.",
	["Última: %s ×%d · %d en la sesión"] = "마지막: %s ×%d · 이번 세션 %d",
	["Último envío: %s por %s, respuesta %s"] = "마지막 전송: %s, 경로 %s, 결과 %s",
	["Último escaneo %s · %s objetos con precio."] = "마지막 스캔 %s · 가격이 있는 아이템 %s개.",
	["Únete a un grupo o banda para anunciar el top."] = "순위를 알리려면 파티나 공격대에 들어가세요.",
	["Únete a un grupo para compartir tus marcadores."] = "마커를 공유하려면 파티에 들어가세요.",
	["Único"] = "고유",
	["élite"] = "정예",
	["épico"] = "영웅",
	["última: %s"] = "최근: %s",
	["• El logo, el lobo, Lya y los módulos propios de Alfa son de toxic3000 / La Jauría (GPL-3.0)."] = "• 로고, 늑대, 리아, Alfa 자체 모듈은 toxic3000 / La Jauría의 것이에요(GPL-3.0).",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite, 제작 Wuild (MIT): 채집 지점 데이터베이스.",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• Inter, Fira Sans, Open Sans 글꼴 (SIL Open Font License 1.1).",
	["• Los datos que trae Polestar también vienen de QuestieDB, Efficient Games (CC BY 4.0), VMaNGOS, CMaNGOS y Factoruide (GPL) y de ForeverLevelingBiS de Thunder (MIT); sus avisos están en cada LICENSE-DATA.txt."] = "• Polestar의 데이터는 QuestieDB, Efficient Games(CC BY 4.0), VMaNGOS, CMaNGOS, Factoruide(GPL), 그리고 Thunder의 ForeverLevelingBiS(MIT)에서도 왔어요. 각 고지는 LICENSE-DATA.txt에 있어요.",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap, 제작 OpenMap contributors (MIT): 이어진 지도 로직과 영역 마스크.",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar, 제작 The Polestar authors (GPL-3.0): 가이드, 길 찾기, 데이터 엔진 (github.com/fitzforge/polestar).",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever, 제작 Cillian Berragan (GPL-3.0-or-later): 길 찾기와 근처 서비스.",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap, 제작 Dramacydal (MIT): 지도 지형 조각 표.",
	["• pfQuest, de shagu (MIT): datos de misiones, PNJ y objetos."] = "• pfQuest, 제작 shagu (MIT): 퀘스트, NPC, 오브젝트 데이터.",
	["≈ %s"] = "≈ %s",
}
